__d(function(g,r,i,a,m,e,d){"use strict";Object.defineProperty(e,'__esModule',{value:!0}),Object.defineProperty(e,"LEVEL_DATA",{enumerable:!0,get:function(){return u}});var t=r(d[0]),n=r(d[1]),_=r(d[2]),o=r(d[3]);const u={words:(0,r(d[4]).withExamples)(o.N1_WORDS,_.N1_EXAMPLES),grammar:t.N1_GRAMMAR,reading:n.N1_READING}},1914,[1933,1934,1935,1936,1920]);
__d(function(n,i,t,a,e,g,h){"use strict";Object.defineProperty(g,'__esModule',{value:!0}),Object.defineProperty(g,"N1_GRAMMAR",{enumerable:!0,get:function(){return r}});const r=[{id:'n1-g01',pattern:'〜ずにはおかない',connection:'動詞ない形（去ない） ＋ ずにはおかない（する→せずにはおかない）',meaning:'必定會〜；非〜不可',example:{ja:'この映画は見る人を感動させずにはおかない。',zh:'這部電影必定會讓觀眾感動。',highlight:'感動させずにはおかない'},tip:'主語多為事物，表「必然引起某種情感或結果」。常與「ずにはすまない」（義務、不得不）比較。',quiz:{blank:'ずにはおかない',distractors:['ずにはすまない','ずじまいだ','ずともよい']}},{id:'n1-g02',pattern:'〜までもない',connection:'動詞辭書形 ＋ までもない',meaning:'用不著〜',example:{ja:'そんな簡単なことは、説明するまでもない。',zh:'那麼簡單的事，用不著說明。',highlight:'説明するまでもない'},tip:'表「事情明顯，沒必要做」。常見「言うまでもない」。勿與「べくもない」（根本不可能）混淆。',quiz:{blank:'までもない',distractors:['べくもない','ほかない','きらいがある']}},{id:'n1-g03',pattern:'〜ともなれば',connection:'名詞／動詞辭書形 ＋ ともなれば',meaning:'一旦到了〜（的地位、程度）',example:{ja:'名探偵ともなれば、どんな嘘も見抜く。',zh:'到了名偵探的程度，什麼謊都看得穿。',highlight:'名探偵ともなれば'},tip:'「一旦到了某立場、時期，自然就會～」，後接理所當然的結果。與「ともなると」幾乎同義。',quiz:{blank:'ともなれば',distractors:['ならでは','をおいて','にひきかえ']}},{id:'n1-g04',pattern:'〜をものともせず',connection:'名詞 ＋ をものともせず',meaning:'不把〜放在眼裡',example:{ja:'彼は危険をものともせず、現場に向かった。',zh:'他不顧危險，前往現場。',highlight:'危険をものともせず'},tip:'不畏困難、障礙勇往直前，多用於稱讚他人。不能用於說話者自己。近義「を顧みず」。',quiz:{blank:'をものともせず',distractors:['をいいことに','を皮切りに','をおいて']}},{id:'n1-g05',pattern:'〜べくもない',connection:'動詞辭書形 ＋ べくもない',meaning:'無從〜；根本不可能〜',example:{ja:'素人の推理では、名探偵に勝つべくもない。',zh:'外行人的推理根本不可能贏過名偵探。',highlight:'勝つべくもない'},tip:'書面語，常見「望むべくもない」「知るべくもない」。する→すべくもない。勿與「までもない」混淆。',quiz:{blank:'べくもない',distractors:['べからず','までもない','ずにはおかない']}},{id:'n1-g06',pattern:'〜に至って',connection:'名詞／動詞辭書形 ＋ に至って',meaning:'直到〜（才）',example:{ja:'事件が起きるに至って、ようやく対策が取られた。',zh:'直到事件發生，才終於採取對策。',highlight:'起きるに至って'},tip:'「事態嚴重到～地步才終於…」，後句常接「ようやく／初めて」。與「に至っては」（舉極端例）不同。',quiz:{blank:'に至って',distractors:['をもって','にあって','に先駆けて']}},{id:'n1-g07',pattern:'〜ならでは',connection:'名詞 ＋ ならでは（の＋名詞／ならではだ）',meaning:'只有〜才有的',example:{ja:'これは名探偵ならではの推理だ。',zh:'這是只有名偵探才做得出的推理。',highlight:'名探偵ならでは'},tip:'只用於正面評價「唯有～才有」。常見「ならではの＋名詞」。不可用於負面事物。',quiz:{blank:'ならでは',distractors:['ごとき','ずくめ','まみれ']}},{id:'n1-g08',pattern:'〜といえども',connection:'名詞／普通形 ＋ といえども',meaning:'即使是〜也',example:{ja:'名探偵といえども、間違えることはある。',zh:'即使是名偵探，也會有出錯的時候。',highlight:'名探偵といえども'},tip:'硬い表現，「即使是～也…」，前接身分地位高者，後接與預期相反內容。近義「とはいえ」。',quiz:{blank:'といえども',distractors:['ともなれば','とあって','ならでは']}},{id:'n1-g09',pattern:'〜をもって',connection:'名詞 ＋ をもって',meaning:'以〜；在〜（時間點）',example:{ja:'本日をもって、捜査を終了します。',zh:'搜查於今天結束。',highlight:'本日をもって'},tip:'表期限（以～為止）或手段（以～）。正式場合用更客氣的「をもちまして」。',quiz:{blank:'をもって',distractors:['を皮切りに','を経て','をよそに']}},{id:'n1-g10',pattern:'〜きらいがある',connection:'動詞辭書形／名詞の ＋ きらいがある',meaning:'有〜的傾向（負面）',example:{ja:'彼は物事を悪く考えるきらいがある。',zh:'他有把事情往壞處想的傾向。',highlight:'考えるきらいがある'},tip:'表不好的傾向，帶批評語氣。與「傾向がある」不同，只用於負面。接續：辭書形／名詞の。',quiz:{blank:'きらいがある',distractors:['までもない','べくもない','にかたくない']}},{id:'n1-g11',pattern:'〜を皮切りに',connection:'名詞 ＋ を皮切りに',meaning:'以〜為開端',example:{ja:'東京を皮切りに、全国で事件が起きた。',zh:'從東京開始，全國各地都發生了事件。',highlight:'東京を皮切りに'},tip:'以～為開端，後接接連發生、擴展的事。與「を限りに」（以～為最後）意思相反。',quiz:{blank:'を皮切りに',distractors:['をよそに','をおいて','を限りに']}},{id:'n1-g12',pattern:'〜とあって',connection:'名詞／普通形 ＋ とあって',meaning:'因為是〜（特殊情況）',example:{ja:'人気の映画とあって、会場は満員だった。',zh:'因為是熱門電影，會場座無虛席。',highlight:'映画とあって'},tip:'因為是～的特殊情況，所以後述結果理所當然。後句多為客觀描述，不接意志、命令。',quiz:{blank:'とあって',distractors:['といえども','にひきかえ','ならでは']}},{id:'n1-g13',pattern:'〜が早いか',connection:'動詞辭書形 ＋ が早いか',meaning:'剛一〜就立刻〜',example:{ja:'ベルが鳴るが早いか、生徒たちは教室を飛び出した。',zh:'鈴聲一響，學生們就衝出了教室。',highlight:'鳴るが早いか'},tip:'剛一～幾乎同時就～，多用於過去的一次性事件。與「や否や」「なり」同屬「一～就」系列。',quiz:{blank:'が早いか',distractors:['そばから','までもなく','ともなれば']}},{id:'n1-g14',pattern:'〜や否や',connection:'動詞辭書形 ＋ や否や',meaning:'一〜就馬上〜',example:{ja:'彼は家に着くや否や、ベッドに倒れ込んだ。',zh:'他一到家就倒在床上。',highlight:'着くや否や'},tip:'書面語「一～就馬上」。也可說「や」。後句不接意志、命令。與「が早いか」可互換。',quiz:{blank:'や否や',distractors:['そばから','までもなく','ともなると']}},{id:'n1-g15',pattern:'〜なり',connection:'動詞辭書形 ＋ なり',meaning:'一〜就（出乎意料地）〜',example:{ja:'母は電話を切るなり、泣き出した。',zh:'母親一掛電話就哭了起來。',highlight:'切るなり'},tip:'前後主語須相同，後句為意外行為，不接意志、命令。注意與「〜なり〜なり」（或～或～）區別。',quiz:{blank:'なり',distractors:['そばから','までもなく','がてら']}},{id:'n1-g16',pattern:'〜そばから',connection:'動詞辭書形／た形 ＋ そばから',meaning:'才剛〜就又〜',example:{ja:'覚えるそばから忘れてしまう。',zh:'才剛記住就又忘了。',highlight:'覚えるそばから'},tip:'用於反覆發生的事：剛做完就又被抵銷。常帶不滿語氣。與一次性的「が早いか」區分。',quiz:{blank:'そばから',distractors:['が早いか','かたわら','までもなく']}},{id:'n1-g17',pattern:'〜てからというもの',connection:'動詞て形 ＋ からというもの',meaning:'自從〜以後（一直）',example:{ja:'子どもが生まれてからというもの、自由な時間がない。',zh:'自從孩子出生以後，就沒有自由的時間了。',highlight:'生まれてからというもの'},tip:'自從～之後，狀態就一直持續改變。接て形。與「からには」（既然）、「てから」區分。',quiz:{blank:'からというもの',distractors:['からには','からといって','からでないと']}},{id:'n1-g18',pattern:'〜をよそに',connection:'名詞 ＋ をよそに',meaning:'不顧〜；無視〜',example:{ja:'親の心配をよそに、彼は一人で海外へ旅立った。',zh:'不顧父母的擔心，他獨自出國去了。',highlight:'心配をよそに'},tip:'對周圍的擔心、反對等置之不理。前接「心配／期待／反対」等。近義「をものともせず」但對象不同。',quiz:{blank:'をよそに',distractors:['をいいことに','を皮切りに','をもって']}},{id:'n1-g19',pattern:'〜にかかわる',connection:'名詞 ＋ にかかわる',meaning:'攸關〜；關係到〜',example:{ja:'これは命にかかわる問題だ。',zh:'這是攸關性命的問題。',highlight:'命にかかわる'},tip:'前接「命／名誉／将来」等重大事項，表「攸關」。勿與「にまつわる」（有關～的傳說）混淆。',quiz:{blank:'にかかわる',distractors:['に足る','にかたくない','に先駆ける']}},{id:'n1-g20',pattern:'〜に即して',connection:'名詞 ＋ に即して',meaning:'依照〜；根據〜（實際情況）',example:{ja:'事実に即して報告してください。',zh:'請依照事實報告。',highlight:'事実に即して'},tip:'依照事實、規定、實際情況。修飾名詞用「に即した」。近義「に沿って」「に基づいて」。',quiz:{blank:'に即して',distractors:['にかこつけて','にかまけて','に先駆けて']}},{id:'n1-g21',pattern:'〜いかんでは',connection:'名詞（の） ＋ いかんでは',meaning:'根據〜的情況，有可能〜',example:{ja:'結果いかんでは、計画を中止することもある。',zh:'視結果而定，也可能中止計畫。',highlight:'結果いかんでは'},tip:'書面語「視～而定，有可能～」。與「いかんにかかわらず／によらず」（不論～）意思相反。',quiz:{blank:'いかんでは',distractors:['いかんによらず','いかんにかかわらず','ならでは']}},{id:'n1-g22',pattern:'〜を禁じ得ない',connection:'名詞 ＋ を禁じ得ない',meaning:'不禁〜；禁不住〜',example:{ja:'被害者の話に、同情を禁じ得ない。',zh:'聽了受害者的話，不禁感到同情。',highlight:'同情を禁じ得ない'},tip:'前接「涙／怒り／同情／驚き」等情感名詞，表情不自禁。硬い表現，常與「を余儀なくされる」混考。',quiz:{blank:'を禁じ得ない',distractors:['を余儀なくされる','をものともしない','をいいことにする']}},{id:'n1-g23',pattern:'〜てやまない',connection:'動詞て形 ＋ やまない',meaning:'衷心〜；一直〜',example:{ja:'皆様のご健康を願ってやみません。',zh:'衷心祝福各位身體健康。',highlight:'願ってやみません'},tip:'強烈願望持續不斷，前接「願う／祈る／愛する」。多用於致詞、書信，主語為說話者。',quiz:{blank:'やみません',distractors:['かないません','たまりません','やりません']}},{id:'n1-g24',pattern:'〜に堪えない',connection:'動詞辭書形／名詞 ＋ に堪えない',meaning:'不堪〜；不勝〜',example:{ja:'その番組は見るに堪えない内容だった。',zh:'那個節目的內容不堪入目。',highlight:'見るに堪えない'},tip:'①「見る／聞く＋に堪えない」：不堪入目入耳；②「感謝に堪えない」：不勝感激。兩種用法皆常考。',quiz:{blank:'に堪えない',distractors:['にかたくない','までもない','べくもない']}},{id:'n1-g25',pattern:'〜極まりない',connection:'な形容詞語幹 ＋ 極まりない／極まる',meaning:'極其〜；〜至極',example:{ja:'運転中にスマホを使うなんて、危険極まりない。',zh:'開車時用手機，真是危險至極。',highlight:'危険極まりない'},tip:'多接「失礼／危険／不愉快」等負面な形容詞。「極まりない」與「極まる」同義。勿與「の至り」混淆。',quiz:{blank:'極まりない',distractors:['の至り','まみれ','ならでは']}},{id:'n1-g26',pattern:'〜の至り',connection:'名詞 ＋ の至り',meaning:'〜之至；極為〜',example:{ja:'このような賞をいただき、光栄の至りです。',zh:'能獲得這樣的獎項，真是光榮之至。',highlight:'光栄の至り'},tip:'固定搭配「光栄の至り」「若気の至り」「恐縮の至り」。用於正式致詞。與「極まりない」常混考。',quiz:{blank:'の至り',distractors:['ずくめ','まみれ','のきらい']}},{id:'n1-g27',pattern:'〜とばかりに',connection:'引用句（普通形／命令形等） ＋ とばかりに',meaning:'簡直就像在說〜似地',example:{ja:'彼は待ってましたとばかりに手を挙げた。',zh:'他一副「就等這一刻」似地舉起了手。',highlight:'待ってましたとばかりに'},tip:'雖沒說出口，態度卻像在說「～」。前接引用句。與「んばかりに」（幾乎要～）常混考。',quiz:{blank:'とばかりに',distractors:['んばかりに','ながらに','ごとく']}},{id:'n1-g28',pattern:'〜ながらに',connection:'動詞ます形／名詞 ＋ ながらに',meaning:'保持〜的狀態；〜著',example:{ja:'彼女は涙ながらに事故の様子を語った。',zh:'她含淚講述了事故的情況。',highlight:'涙ながらに'},tip:'固定用法：「涙ながらに」「生まれながらに」「昔ながらの」。保持原狀態，不同於逆接「ながら」。',quiz:{blank:'ながらに',distractors:['ずくめに','ごときに','めいて']}},{id:'n1-g29',pattern:'〜まみれ',connection:'名詞 ＋ まみれ',meaning:'沾滿〜；滿是〜',example:{ja:'子どもたちは泥まみれになって遊んでいた。',zh:'孩子們玩得滿身是泥。',highlight:'泥まみれ'},tip:'表表面沾滿髒污液體（泥、汗、血、ほこり）。與「だらけ」相近，但「ずくめ」為全是某事物。',quiz:{blank:'まみれ',distractors:['ずくめ','ぐるみ','がち']}},{id:'n1-g30',pattern:'〜ずくめ',connection:'名詞 ＋ ずくめ',meaning:'全是〜；清一色〜',example:{ja:'今年はいいことずくめの一年だった。',zh:'今年是好事連連的一年。',highlight:'いいことずくめ'},tip:'清一色全是～，常見「黒ずくめ」「いいことずくめ」「規則ずくめ」。與「まみれ」（沾滿）區分。',quiz:{blank:'ずくめ',distractors:['まみれ','ぐるみ','がち']}},{id:'n1-g31',pattern:'〜めく',connection:'名詞 ＋ めく',meaning:'帶有〜的氣息；像〜',example:{ja:'日差しが暖かくなり、春めいてきた。',zh:'陽光變暖，有了春天的氣息。',highlight:'春めいてきた'},tip:'帶有～的氣息，常見「春めく」「冗談めいた」「謎めいた」。活用為五段動詞「めいて／めいた」。',quiz:{blank:'めいて',distractors:['ぶって','まみれて','がかって']}},{id:'n1-g32',pattern:'〜んばかりに',connection:'動詞ない形（去ない） ＋ んばかりに（する→せんばかりに）',meaning:'幾乎要〜似地',example:{ja:'彼女は泣き出さんばかりに頼んできた。',zh:'她幾乎要哭出來似地拜託我。',highlight:'泣き出さんばかりに'},tip:'差點就要～的樣子（實際沒發生）。與「とばかりに」（像在說～）常混考，注意前接ない形。',quiz:{blank:'んばかりに',distractors:['とばかりに','んがために','ずじまいで']}},{id:'n1-g33',pattern:'〜ではあるまいし',connection:'名詞 ＋ ではあるまいし',meaning:'又不是〜',example:{ja:'子どもではあるまいし、自分で考えなさい。',zh:'又不是小孩子，自己想想吧。',highlight:'子どもではあるまいし'},tip:'口語「又不是～」，後接說話者的判斷、命令、勸告。同「じゃあるまいし」。與「ではあるまいか」區分。',quiz:{blank:'ではあるまいし',distractors:['ではあるまいか','ともなれば','にひきかえ']}},{id:'n1-g34',pattern:'〜たところで',connection:'動詞た形 ＋ ところで',meaning:'即使〜也（沒用）',example:{ja:'今から急いだところで、間に合わないだろう。',zh:'就算現在趕，也來不及了吧。',highlight:'急いだところで'},tip:'即使做了也沒用，後接否定、負面推測。接た形。與「ところを」（正當～時）、「ところに」區分。',quiz:{blank:'ところで',distractors:['ところを','ばかりに','あげく']}},{id:'n1-g35',pattern:'〜であれ',connection:'名詞 ＋ であれ',meaning:'無論是〜都〜',example:{ja:'理由が何であれ、暴力は許されない。',zh:'無論理由是什麼，暴力都不可原諒。',highlight:'何であれ'},tip:'常接疑問詞「何／誰／どこであれ」。近義「であろうと」「にせよ」。書面語。',quiz:{blank:'であれ',distractors:['とあって','ならでは','ではあるまいし']}},{id:'n1-g36',pattern:'〜なくしては',connection:'名詞 ＋ なくしては',meaning:'如果沒有〜就無法〜',example:{ja:'皆様のご協力なくしては、成功はありませんでした。',zh:'如果沒有各位的協助，就不會成功。',highlight:'ご協力なくしては'},tip:'若沒有～就不可能～，後句必接否定或難以實現。近義「なしには」。常用於致謝。',quiz:{blank:'なくしては',distractors:['ならでは','とあって','をもってすれば']}},{id:'n1-g37',pattern:'〜をおいて',connection:'名詞 ＋ をおいて',meaning:'除了〜之外（沒有其他）',example:{ja:'この仕事を任せられるのは、彼をおいてほかにいない。',zh:'能託付這份工作的，除了他沒有別人。',highlight:'彼をおいて'},tip:'後接「ほかに～ない」，表除～以外別無他選，用於高度評價。勿與「をよそに」混淆。',quiz:{blank:'をおいて',distractors:['をもって','をよそに','を皮切りに']}},{id:'n1-g38',pattern:'〜にひきかえ',connection:'名詞／普通形の ＋ にひきかえ',meaning:'與〜相反；和〜不同',example:{ja:'兄にひきかえ、弟は社交的だ。',zh:'和哥哥相反，弟弟很外向。',highlight:'兄にひきかえ'},tip:'與～截然相反，帶說話者主觀評價。比「に対して」主觀。前接普通形時需加「の」。',quiz:{blank:'にひきかえ',distractors:['をよそに','にかこつけて','に先駆けて']}},{id:'n1-g39',pattern:'〜を余儀なくされる',connection:'名詞 ＋ を余儀なくされる',meaning:'不得不〜；被迫〜',example:{ja:'大雨のため、試合は中止を余儀なくされた。',zh:'因為大雨，比賽被迫中止。',highlight:'中止を余儀なくされた'},tip:'因外力被迫做～，前接「中止／変更／入院」等動作名詞。主動形「を余儀なくさせる」為使役。',quiz:{blank:'を余儀なくされた',distractors:['を禁じ得なかった','をものともしなかった','をよそにした']}},{id:'n1-g40',pattern:'〜べく',connection:'動詞辭書形 ＋ べく（する→すべく）',meaning:'為了〜',example:{ja:'夢を実現すべく、毎日努力している。',zh:'為了實現夢想，每天都在努力。',highlight:'実現すべく'},tip:'書面語「為了～」，する→すべく。後句不接命令、請求。勿與「べからず」「べくもない」混淆。',quiz:{blank:'べく',distractors:['べからず','まじき','べからざる']}},{id:'n1-g41',pattern:'〜べからず',connection:'動詞辭書形 ＋ べからず',meaning:'不得〜、禁止〜（告示用語）',example:{ja:'関係者以外、立ち入るべからず。',zh:'非相關人員，不得進入。',highlight:'立ち入るべからず'},tip:'告示、標語中的禁止用法，相當於「てはいけない」。句尾用。修飾名詞時用「べからざる」。',quiz:{blank:'べからず',distractors:['べく','べくもない','までもない']}},{id:'n1-g42',pattern:'〜べからざる',connection:'動詞辭書形 ＋ べからざる ＋ 名詞',meaning:'不可〜的、不容〜的',example:{ja:'それは警察官として許すべからざる行為だ。',zh:'那是身為警察不可原諒的行為。',highlight:'許すべからざる'},tip:'修飾名詞「不可～的」，常見「許すべからざる」「欠くべからざる」。句尾形是「べからず」。',quiz:{blank:'べからざる',distractors:['べからず','べく','べき']}},{id:'n1-g43',pattern:'〜ごとき（輕視）',connection:'名詞 ＋ ごとき',meaning:'像〜這種的（輕蔑、謙遜）',example:{ja:'素人ごときにこの事件が解けるものか。',zh:'區區一個外行人怎麼可能解得開這個案子。',highlight:'素人ごとき'},tip:'名詞＋ごとき：輕蔑他人或自謙（私ごとき）。口語可說「なんか」。注意與比喻「のごとく」區別。',quiz:{blank:'ごとき',distractors:['ごとく','ならでは','ずくめ']}},{id:'n1-g44',pattern:'〜ごとく（比喻）',connection:'名詞 ＋ の ＋ ごとく／動詞普通形 ＋ がごとく',meaning:'如同〜一般',example:{ja:'犯人は風のごとく姿を消した。',zh:'犯人像風一樣消失了蹤影。',highlight:'風のごとく'},tip:'「ように」的文語形：のごとく（修飾動詞）、のごとき（修飾名詞）。注意形態選擇。',quiz:{blank:'ごとく',distractors:['ごとき','ならでは','かぎり']}},{id:'n1-g45',pattern:'〜んがため（に）',connection:'動詞ない形（去ない） ＋ んがため（に）',meaning:'為了〜（強烈目的）',example:{ja:'真実を明らかにせんがため、彼は危険を冒した。',zh:'為了查明真相，他甘冒危險。',highlight:'明らかにせんがため'},tip:'強烈目的「無論如何也要～」，硬い表現。する→せんがため。後句不接請求、命令。',quiz:{blank:'んがため',distractors:['んばかり','ずじまい','ずとも']}},{id:'n1-g46',pattern:'〜をもってすれば',connection:'名詞 ＋ をもってすれば',meaning:'只要憑藉〜的話',example:{ja:'彼の推理力をもってすれば、解けない謎はない。',zh:'只要憑他的推理能力，沒有解不開的謎。',highlight:'推理力をもってすれば'},tip:'憑藉～的能力就能做到，後接正面結果。與「をもってしても」（即使～也不行）對照考。',quiz:{blank:'をもってすれば',distractors:['をもってしても','をおいて','をよそに']}},{id:'n1-g47',pattern:'〜をもってしても',connection:'名詞 ＋ をもってしても',meaning:'即使憑藉〜也（不）〜',example:{ja:'最新の技術をもってしても、指紋は検出できなかった。',zh:'即使用最新的技術，也驗不出指紋。',highlight:'技術をもってしても'},tip:'即使憑藉～也無法～，後接否定。與「をもってすれば」成對出題。',quiz:{blank:'をもってしても',distractors:['をもってすれば','をもちまして','を皮切りに']}},{id:'n1-g48',pattern:'〜をもちまして',connection:'名詞 ＋ をもちまして',meaning:'以〜（正式場合的結束、時間點）',example:{ja:'本日の営業は午後八時をもちまして終了いたします。',zh:'本日營業將於晚上八點結束。',highlight:'午後八時をもちまして'},tip:'「をもって」的謙讓、正式說法，用於典禮、廣播宣布結束時間。',quiz:{blank:'をもちまして',distractors:['を皮切りに','をよそに','を経て']}},{id:'n1-g49',pattern:'〜であれ〜であれ',connection:'名詞 ＋ であれ ＋ 名詞 ＋ であれ',meaning:'無論是〜還是〜',example:{ja:'男であれ女であれ、容疑者は全員調べる。',zh:'不管是男是女，嫌犯全部都要調查。',highlight:'男であれ女であれ'},tip:'舉出對立兩例表「不論哪一種都～」。近義「であろうと～であろうと」。勿與「といい～といい」混淆。',quiz:{blank:'であれ女であれ',distractors:['といい女といい','につけ女につけ','やら女やら']}},{id:'n1-g50',pattern:'〜であろうと',connection:'名詞／な形容詞語幹 ＋ であろうと',meaning:'即使是〜也',example:{ja:'相手が警視総監であろうと、私は真実を言う。',zh:'就算對方是警視總監，我也要說出真相。',highlight:'警視総監であろうと'},tip:'即使是～也不受影響，後接說話者意志或判斷。近義「であれ」「といえども」。書面語。',quiz:{blank:'であろうと',distractors:['とあって','ならでは','にひきかえ']}},{id:'n1-g51',pattern:'〜であろうとなかろうと',connection:'名詞 ＋ であろうとなかろうと',meaning:'不管是不是〜',example:{ja:'事故であろうとなかろうと、原因は突き止める。',zh:'不管是不是意外，都要查出原因。',highlight:'事故であろうとなかろうと'},tip:'不管是不是～結果都不變。近義「であるにせよないにせよ」。動詞版為「ようと～まいと」。',quiz:{blank:'であろうとなかろうと',distractors:['ではあるまいし','であるがゆえに','であったが最後']}},{id:'n1-g52',pattern:'〜（よ）うが',connection:'動詞意向形 ＋ が（い形容詞→かろうが／名詞・な形容詞→だろうが）',meaning:'無論〜都（不受影響）',example:{ja:'誰が何と言おうが、私の推理は変わらない。',zh:'不管誰說什麼，我的推理都不會變。',highlight:'何と言おうが'},tip:'常與疑問詞「誰が／何を／どんなに」搭配，表無論如何都不影響後項。近義「ようと」。',quiz:{blank:'言おうが',distractors:['言うが','言えば','言うなり']}},{id:'n1-g53',pattern:'〜（よ）うが〜まいが',connection:'動詞意向形 ＋ が ＋ 動詞辭書形 ＋ まいが',meaning:'不管〜還是不〜',example:{ja:'君が信じようが信じまいが、これが事実だ。',zh:'不管你信不信，這就是事實。',highlight:'信じようが信じまいが'},tip:'「Vようが Vまいが」不管做不做都一樣。注意「まい」前接辭書形（一段動詞也可接ない形語幹）。',quiz:{blank:'まいが',distractors:['まいか','たいが','ずとも']}},{id:'n1-g54',pattern:'〜（よ）うと〜まいと',connection:'動詞意向形 ＋ と ＋ 動詞辭書形 ＋ まいと',meaning:'不管做不做〜',example:{ja:'彼が自白しようとするまいと、証拠は揃っている。',zh:'不管他招不招供，證據都已經齊全了。',highlight:'自白しようとするまいと'},tip:'與「ようが～まいが」同義可互換。注意「する」的まい形：するまい／すまい。',quiz:{blank:'まいと',distractors:['まいか','べく','まいし']}},{id:'n1-g55',pattern:'〜（よ）うと（も）',connection:'動詞意向形 ＋ と（も）',meaning:'即使〜也',example:{ja:'どんなに脅されようとも、口を割るつもりはない。',zh:'不管受到怎樣的威脅，我都不打算招供。',highlight:'脅されようとも'},tip:'假定逆接「即使～也」，常與「どんなに／たとえ」呼應。書面語。勿與「ようにも～ない」混淆。',quiz:{blank:'ようとも',distractors:['ようにも','てこそ','たが最後']}},{id:'n1-g56',pattern:'〜（よ）うにも〜ない',connection:'動詞意向形 ＋ にも ＋ 動詞可能ない形',meaning:'想〜也沒辦法〜',example:{ja:'鍵がないので、部屋に入ろうにも入れない。',zh:'沒有鑰匙，想進房間也進不去。',highlight:'入ろうにも入れない'},tip:'同一動詞重複：「Vようにも V可能形ない」，因某原因想做也做不到。常考前後動詞一致。',quiz:{blank:'入ろうにも',distractors:['入っても','入れば','入ろうと']}},{id:'n1-g57',pattern:'〜ではあるまいか',connection:'普通形（名詞・な形容詞＋な） ＋ のではあるまいか／名詞 ＋ ではあるまいか',meaning:'是不是〜呢（委婉推測）',example:{ja:'犯人はまだこの屋敷にいるのではあるまいか。',zh:'犯人是不是還在這棟宅邸裡呢？',highlight:'いるのではあるまいか'},tip:'書面語的委婉推測，同「のではないだろうか」。與「ではあるまいし」（又不是～）常混考。',quiz:{blank:'ではあるまいか',distractors:['ではあるまいし','であれ','をものともせず']}},{id:'n1-g58',pattern:'〜ずにはすまない',connection:'動詞ない形（去ない） ＋ ずにはすまない',meaning:'不〜就無法了事、必須〜',example:{ja:'これほどの騒ぎを起こしたからには、謝罪せずにはすまない。',zh:'鬧出這麼大的風波，不道歉是交代不過去的。',highlight:'謝罪せずにはすまない'},tip:'從社會常理看不做就說不過去，表義務。與「ずにはおかない」（必然、一定讓～）常混考。',quiz:{blank:'ずにはすまない',distractors:['ずじまいだ','ずともよい','ずにはおかない']}},{id:'n1-g59',pattern:'〜ないではすまない',connection:'動詞ない形 ＋ ではすまない',meaning:'不〜就說不過去',example:{ja:'嘘がばれた以上、本当のことを話さないではすまないだろう。',zh:'既然謊言被拆穿，不說實話恐怕是不行了。',highlight:'話さないではすまない'},tip:'「ずにはすまない」的口語版，義務、不得不。勿與「ないではいられない」（忍不住）混淆。',quiz:{blank:'ではすまない',distractors:['までもない','ではあるまいし','ことには']}},{id:'n1-g60',pattern:'〜ないまでも',connection:'動詞ない形 ＋ までも',meaning:'雖然不到〜的程度，至少也〜',example:{ja:'毎日とは言わないまでも、週に一度は現場を見に行くべきだ。',zh:'雖說不必每天，至少一週也該去現場看一次。',highlight:'言わないまでも'},tip:'雖達不到前項的程度，至少也要後項。後句常接「べきだ／たい／ほしい」。近義「ないにしても」。',quiz:{blank:'までも',distractors:['ことには','ばかりか','がために']}},{id:'n1-g61',pattern:'〜までだ（只好）',connection:'動詞辭書形 ＋ までだ',meaning:'大不了〜就是了、只好〜',example:{ja:'協力してくれないなら、一人で調べるまでだ。',zh:'如果你不肯幫忙，我自己查就是了。',highlight:'調べるまでだ'},tip:'辭書形＋までだ：既然別無他法，只好（大不了）～。表說話者決心。與た形＋までだ（只不過）區分。',quiz:{blank:'までだ',distractors:['までもない','きらいがある','べくもない']}},{id:'n1-g62',pattern:'〜までのことだ（只不過）',connection:'動詞た形 ＋ までのことだ',meaning:'只不過是〜而已',example:{ja:'私は見たことをそのまま話したまでのことです。',zh:'我只不過是把看到的事照實說出來而已。',highlight:'話したまでのことです'},tip:'た形＋までだ／までのことだ：只不過做了～而已，用於辯解。與辭書形用法（只好～）常混考。',quiz:{blank:'までのことです',distractors:['までもないことです','ばかりです','きらいがあります']}},{id:'n1-g63',pattern:'〜ばそれまでだ',connection:'動詞ば形 ＋ それまでだ',meaning:'一旦〜就完了',example:{ja:'証拠を燃やされてしまえばそれまでだ。',zh:'證據要是被燒掉就一切都完了。',highlight:'燃やされてしまえばそれまでだ'},tip:'一旦～就一切都完了、白費了。常見「死んでしまえばそれまでだ」。前接ば形或たら形。',quiz:{blank:'それまでだ',distractors:['それまでもない','それにひきかえだ','それしきだ']}},{id:'n1-g64',pattern:'〜にあって',connection:'名詞 ＋ にあって',meaning:'在〜的狀況、立場下',example:{ja:'この非常時にあって、冷静さを失ってはならない。',zh:'在這種非常時期，不能失去冷靜。',highlight:'非常時にあって'},tip:'書面語「身處～的狀況、時期下」。後句可順接或逆接。與「において」相近但更強調特殊狀況。',quiz:{blank:'にあって',distractors:['にかこつけて','にかまけて','に先駆けて']}},{id:'n1-g65',pattern:'〜に至っては',connection:'名詞 ＋ に至っては',meaning:'至於〜（更極端的例子）',example:{ja:'他の容疑者も怪しいが、弟に至ってはアリバイすらない。',zh:'其他嫌犯也很可疑，至於弟弟，甚至連不在場證明都沒有。',highlight:'弟に至っては'},tip:'在列舉之後舉出最極端的例子，多為負面。常與「すら／さえ」呼應。勿與「に至って」（直到）混淆。',quiz:{blank:'に至っては',distractors:['にあっては','にひきかえ','をよそに']}},{id:'n1-g66',pattern:'〜に至る',connection:'名詞／動詞辭書形 ＋ に至る',meaning:'達到〜、發展到〜',example:{ja:'小さな口論が、ついに殺人に至った。',zh:'一場小口角，最後竟演變成殺人案。',highlight:'殺人に至った'},tip:'最終發展到～的地步。常用「〜に至るまで」「〜に至った経緯」。前多接嚴重結果或結論。',quiz:{blank:'に至った',distractors:['に足った','に堪えた','を経た']}},{id:'n1-g67',pattern:'〜に至っても',connection:'名詞／動詞辭書形 ＋ に至っても',meaning:'即使到了〜地步仍',example:{ja:'証拠を突きつけられるに至っても、彼は否認し続けた。',zh:'即使到了被證據擺在眼前的地步，他仍持續否認。',highlight:'突きつけられるに至っても'},tip:'即使到了～的地步，仍然～，後句常為令人意外或不滿的狀態。與「に至って」（直到才）對比。',quiz:{blank:'に至っても',distractors:['に至っては','にあって','までもなく']}},{id:'n1-g68',pattern:'〜を限りに',connection:'名詞 ＋ を限りに',meaning:'以〜為限、從〜之後就不再',example:{ja:'今日を限りに、私は探偵を引退する。',zh:'今天之後，我就從偵探這行退休。',highlight:'今日を限りに'},tip:'以～為最後一次，之後不再繼續。常接「今日／今回」。與「を皮切りに」（以～為開端）相反。',quiz:{blank:'を限りに',distractors:['を皮切りに','を経て','をよそに']}},{id:'n1-g69',pattern:'〜を経て',connection:'名詞 ＋ を経て',meaning:'經過〜',example:{ja:'三年の捜査を経て、ついに犯人が逮捕された。',zh:'經過三年的調查，犯人終於落網。',highlight:'三年の捜査を経て'},tip:'經過某過程、時間、地點後才達到結果。前接過程或期間名詞。',quiz:{blank:'を経て',distractors:['を皮切りに','をよそに','を限りに']}},{id:'n1-g70',pattern:'〜を機に',connection:'名詞 ＋ を機に',meaning:'以〜為契機',example:{ja:'あの事件を機に、彼は刑事を志した。',zh:'以那起事件為契機，他立志當刑警。',highlight:'事件を機に'},tip:'以某事件為契機開始新行動。近義「をきっかけに」「を契機に」。較書面。',quiz:{blank:'を機に',distractors:['をよそに','を押して','をおいて']}},{id:'n1-g71',pattern:'〜を顧みず',connection:'名詞 ＋ を顧みず',meaning:'不顧〜',example:{ja:'彼は身の危険を顧みず、人質を救い出した。',zh:'他不顧自身危險，救出了人質。',highlight:'危険を顧みず'},tip:'不顧自身危險、家人等該重視的事。常見「危険を顧みず」。近義「をものともせず」。',quiz:{blank:'を顧みず',distractors:['をいいことに','を機に','を皮切りに']}},{id:'n1-g72',pattern:'〜をいいことに',connection:'名詞 ＋ をいいことに／普通形 ＋ の ＋ をいいことに',meaning:'利用〜（鑽空子）',example:{ja:'主人の留守をいいことに、使用人は金庫を開けた。',zh:'僕人趁主人不在，打開了保險箱。',highlight:'留守をいいことに'},tip:'利用某狀況做壞事、鑽空子，含負面評價。與「にかこつけて」（以～為藉口）常混考。',quiz:{blank:'をいいことに',distractors:['を押して','を顧みず','を限りに']}},{id:'n1-g73',pattern:'〜を押して',connection:'名詞 ＋ を押して',meaning:'不顧〜（勉強）',example:{ja:'彼は高熱を押して、捜査会議に出席した。',zh:'他不顧發高燒，出席了偵查會議。',highlight:'高熱を押して'},tip:'勉強不顧病痛、反對等不利條件去做。常見「病を押して」「反対を押して」。',quiz:{blank:'を押して',distractors:['をいいことに','を機に','をおいて']}},{id:'n1-g74',pattern:'〜に先駆けて',connection:'名詞 ＋ に先駆けて',meaning:'搶先於〜、領先〜',example:{ja:'その新聞社は他社に先駆けて事件の真相を報じた。',zh:'那家報社搶在其他報社之前報導了案件真相。',highlight:'他社に先駆けて'},tip:'比其他人或事搶先一步。常用於新產品、研究、報導。修飾名詞用「に先駆けた」。',quiz:{blank:'に先駆けて',distractors:['にかこつけて','にかまけて','に至っては']}},{id:'n1-g75',pattern:'〜にかこつけて',connection:'名詞 ＋ にかこつけて',meaning:'以〜為藉口',example:{ja:'彼は出張にかこつけて、現場の近くを訪れていた。',zh:'他以出差為藉口，去了現場附近。',highlight:'出張にかこつけて'},tip:'以～為藉口做其他事，含負面語氣。近義「を口実に」。與「にかまけて」常混考。',quiz:{blank:'にかこつけて',distractors:['にかまけて','に先駆けて','に即して']}},{id:'n1-g76',pattern:'〜にかまけて',connection:'名詞 ＋ にかまけて',meaning:'只顧著〜（而忽略其他）',example:{ja:'仕事にかまけて、家族の異変に気づかなかった。',zh:'只顧著工作，沒察覺到家人的異狀。',highlight:'仕事にかまけて'},tip:'只顧著～而疏忽了其他該做的事，後句多為負面。與「にかこつけて」（藉口）形近易混。',quiz:{blank:'にかまけて',distractors:['にかこつけて','に即して','に先駆けて']}},{id:'n1-g77',pattern:'〜にかたくない',connection:'名詞（想像・理解など）／動詞辭書形（察する） ＋ にかたくない',meaning:'不難〜',example:{ja:'遺族の悲しみは想像にかたくない。',zh:'遺族的悲痛不難想像。',highlight:'想像にかたくない'},tip:'固定搭配「想像にかたくない」「察するにかたくない」。書面語。「難くない」意為不難。',quiz:{blank:'にかたくない',distractors:['を禁じ得ない','にかかわる','に足る']}},{id:'n1-g78',pattern:'〜に足る',connection:'名詞／動詞辭書形 ＋ に足る',meaning:'值得〜、足以〜',example:{ja:'彼の証言は信頼に足るものだ。',zh:'他的證詞是值得信賴的。',highlight:'信頼に足る'},tip:'值得～、足以～，常見「信頼に足る」「尊敬に足る」。修飾名詞居多。否定為「に足りない」。',quiz:{blank:'に足る',distractors:['にかたくない','に堪えない','にかまける']}},{id:'n1-g79',pattern:'〜に足りない',connection:'名詞／動詞辭書形 ＋ に足りない',meaning:'不值得〜、微不足道',example:{ja:'そんな噂は取るに足りない。',zh:'那種傳聞不值一提。',highlight:'取るに足りない'},tip:'固定說法「取るに足りない」「恐れるに足りない」，表微不足道、不值得。也作「に足らない」。',quiz:{blank:'に足りない',distractors:['に堪えない','にかたくない','べくもない']}},{id:'n1-g80',pattern:'〜に堪える',connection:'名詞／動詞辭書形 ＋ に堪える',meaning:'值得〜、經得起〜',example:{ja:'この報告書は専門家の批判にも堪える内容だ。',zh:'這份報告的內容經得起專家的批評。',highlight:'批判にも堪える'},tip:'值得～、經得起～，常見「鑑賞に堪える」「批判に堪える」。與否定「に堪えない」（不堪）意思不同。',quiz:{blank:'にも堪える',distractors:['にもまして','にも足りない','にもかまける']}},{id:'n1-g81',pattern:'〜にもまして',connection:'名詞 ＋ にもまして',meaning:'比〜更加〜',example:{ja:'今日の彼は、いつにもまして無口だった。',zh:'今天的他比平常更沉默寡言。',highlight:'いつにもまして'},tip:'比～更加。常見「いつにもまして」「何にもまして」（最重要）。',quiz:{blank:'にもまして',distractors:['にひきかえ','にもかかわらず','をおいて']}},{id:'n1-g82',pattern:'〜にしたところで',connection:'名詞 ＋ にしたところで',meaning:'就連〜也〜',example:{ja:'警察にしたところで、手がかりはほとんどない。',zh:'就連警方也幾乎沒有線索。',highlight:'警察にしたところで'},tip:'就連～也一樣（不例外），多接負面內容。口語為「にしたって」。近義「にしても」。',quiz:{blank:'にしたところで',distractors:['にひきかえ','ともなれば','をもってすれば']}},{id:'n1-g83',pattern:'〜にしてからが',connection:'名詞 ＋ にしてからが',meaning:'就連〜都（更不用說其他）',example:{ja:'リーダーにしてからが規則を守っていない。',zh:'就連領導人自己都不守規則。',highlight:'リーダーにしてからが'},tip:'舉最應該做到的人為例：連～都這樣，其他就更不用說。後接負面評價。',quiz:{blank:'にしてからが',distractors:['ともなれば','にひきかえ','をおいて']}},{id:'n1-g84',pattern:'〜にして（階段）',connection:'名詞 ＋ にして',meaning:'到了〜才〜',example:{ja:'五十歳にして、彼はようやく真実にたどり着いた。',zh:'到了五十歲，他才終於找到真相。',highlight:'五十歳にして'},tip:'「到了～階段才」，常與「ようやく／初めて」呼應。亦有「並存」用法，需依文脈判斷。',quiz:{blank:'にして',distractors:['にかこつけて','にもまして','をよそに']}},{id:'n1-g85',pattern:'〜にして（並存）',connection:'名詞 ＋ にして',meaning:'既是〜又是〜',example:{ja:'彼は医師にして作家でもある。',zh:'他既是醫生，也是作家。',highlight:'医師にして'},tip:'書面語「既是～又是～」，相當於「であり、同時に」。常與「でもある」呼應。',quiz:{blank:'にして',distractors:['にひきかえ','をおいて','ならでは']}},{id:'n1-g86',pattern:'〜にして初めて',connection:'名詞 ＋ にして初めて',meaning:'只有〜才能〜',example:{ja:'ベテラン刑事にして初めて気づける違和感だった。',zh:'那是只有老練刑警才能察覺的違和感。',highlight:'ベテラン刑事にして初めて'},tip:'只有達到～程度的人才能做到，前接高水準的人或條件。近義「てはじめて」。',quiz:{blank:'にして初めて',distractors:['にしたところで','をおいて','にひきかえ']}},{id:'n1-g87',pattern:'〜にのっとって',connection:'名詞 ＋ にのっとって',meaning:'依照〜、遵循〜',example:{ja:'法にのっとって、容疑者を処罰する。',zh:'依照法律處罰嫌犯。',highlight:'法にのっとって'},tip:'硬い書面語，前接法律、規則、傳統、慣例等基準；同義「に即して」「に基づいて」。',quiz:{blank:'にのっとって',distractors:['にかこつけて','をよそに','にひきかえ']}},{id:'n1-g88',pattern:'〜には当たらない',connection:'名詞／動詞辭書形 ＋ には当たらない',meaning:'用不著〜、不至於〜',example:{ja:'彼の失敗は責めるには当たらない。',zh:'他的失敗用不著責怪。',highlight:'責めるには当たらない'},tip:'多接「驚く・責める・非難する・感心する」等評價動詞，表示「不值得這樣反應」。',quiz:{blank:'には当たらない',distractors:['にすぎない','に越したことはない','にかたくない']}},{id:'n1-g89',pattern:'〜には及ばない',connection:'名詞／動詞辭書形 ＋ には及ばない',meaning:'不必〜、用不著〜',example:{ja:'わざわざ来ていただくには及びません。',zh:'不必勞駕您特地過來。',highlight:'来ていただくには及びません'},tip:'表「沒必要〜」，常見「ご心配には及びません」；與「は言うに及ばず（不用說）」意思不同。',quiz:{blank:'には及びません',distractors:['にほかなりません','に越したことはありません','にかたくありません']}},{id:'n1-g90',pattern:'〜は言うに及ばず',connection:'名詞 ＋ は言うに及ばず',meaning:'〜自不待言，連〜也',example:{ja:'現場の周辺は言うに及ばず、隣町まで捜索した。',zh:'現場周邊自不待言，連隔壁鎮都搜查了。',highlight:'周辺は言うに及ばず'},tip:'「A是當然的，連B也」，後句常搭「も・まで」；同類「はもちろん」「は言わずもがな」。',quiz:{blank:'は言うに及ばず',distractors:['はさておき','にひきかえ','をものともせず']}},{id:'n1-g91',pattern:'〜は言わずもがな',connection:'名詞 ＋ は言わずもがな',meaning:'〜就不用說了',example:{ja:'専門家は言わずもがな、素人でもその矛盾に気づく。',zh:'專家就不用說了，連外行人都能察覺那個矛盾。',highlight:'専門家は言わずもがな'},tip:'古語殘留的硬い表現，＝「は言うまでもなく」；後句常用「も・でさえ」。',quiz:{blank:'は言わずもがな',distractors:['はさておき','にひきかえ','と相まって']}},{id:'n1-g92',pattern:'〜に言わせれば',connection:'名詞 ＋ に言わせれば',meaning:'依〜的說法、要〜來說的話',example:{ja:'私に言わせれば、あの証言は嘘だらけだ。',zh:'要我說的話，那份證詞根本謊話連篇。',highlight:'私に言わせれば'},tip:'前接人物，表該人的主觀意見（常帶批評）；類似「にしてみれば（站在〜立場）」。',quiz:{blank:'に言わせれば',distractors:['に至っては','をよそに','にもまして']}},{id:'n1-g93',pattern:'〜に照らして',connection:'名詞 ＋ に照らして',meaning:'對照〜、依照〜',example:{ja:'過去の判例に照らして、判決が下された。',zh:'對照過去的判例做出了判決。',highlight:'判例に照らして'},tip:'前接法律、判例、常識、經驗等判斷基準，書面語；與「に即して」「に基づいて」近義。',quiz:{blank:'に照らして',distractors:['にかこつけて','をよそに','にひきかえ']}},{id:'n1-g94',pattern:'〜いかんだ',connection:'名詞 ＋ （の）いかんだ',meaning:'取決於〜',example:{ja:'事件が解決するかどうかは、目撃者の証言いかんだ。',zh:'案件能否解決，取決於目擊者的證詞。',highlight:'証言いかんだ'},tip:'＝「次第だ」的硬い說法；句首常有「〜かどうかは」「成否は」。',quiz:{blank:'いかんだ',distractors:['ずくめだ','までだ','の至りだ']}},{id:'n1-g95',pattern:'〜いかんによらず',connection:'名詞 ＋ （の）いかんによらず',meaning:'不論〜如何',example:{ja:'理由のいかんによらず、無断欠勤は認めない。',zh:'無論理由為何，都不允許無故缺勤。',highlight:'理由のいかんによらず'},tip:'＝「いかんにかかわらず／を問わず」；勿與「いかんによっては（視情況可能）」混淆。',quiz:{blank:'いかんによらず',distractors:['いかんでは','いかんによっては','ゆえに']}},{id:'n1-g96',pattern:'〜いかんにかかわらず',connection:'名詞 ＋ （の）いかんにかかわらず',meaning:'不管〜如何',example:{ja:'結果のいかんにかかわらず、報告書を提出すること。',zh:'不論結果如何，都要提交報告書。',highlight:'結果のいかんにかかわらず'},tip:'「不論〜如何都」，後接不受影響的決定；「いかんで／いかんによっては」則表示會受影響。',quiz:{blank:'いかんにかかわらず',distractors:['いかんによっては','いかんでは','いかんで']}},{id:'n1-g97',pattern:'〜とあれば',connection:'名詞／普通形 ＋ とあれば',meaning:'如果是〜的話（就願意）',example:{ja:'君の頼みとあれば、断るわけにはいかない。',zh:'既然是你的請求，我就不能拒絕。',highlight:'頼みとあれば'},tip:'「既然是〜就（願意做）」，後句多為積極意志；「とあっては」後句則多為不得不或負面結果。',quiz:{blank:'とあれば',distractors:['といえども','ならいざしらず','をよそに']}},{id:'n1-g98',pattern:'〜とあっては',connection:'名詞／普通形 ＋ とあっては',meaning:'如果是〜（那可就）〜',example:{ja:'警視総監の命令とあっては、従うしかない。',zh:'既然是警視總監的命令，只能服從了。',highlight:'命令とあっては'},tip:'「既然是〜（那就只好／當然）」，後句常為「しかない・わけにはいかない」等。',quiz:{blank:'とあっては',distractors:['といえども','ならまだしも','をものともせず']}},{id:'n1-g99',pattern:'〜ともなると',connection:'名詞／動詞辭書形 ＋ ともなると',meaning:'一旦到了〜（自然就）',example:{ja:'真夜中ともなると、この通りは人っ子一人いない。',zh:'一到深夜，這條路上連個人影都沒有。',highlight:'真夜中ともなると'},tip:'「一旦到了〜的程度／立場，自然就〜」，前接時間、年齡、身分；同義「ともなれば」。',quiz:{blank:'ともなると',distractors:['ともなく','ともあろう','ともすれば']}},{id:'n1-g100',pattern:'〜ともあろう',connection:'名詞 ＋ ともあろう ＋ 名詞',meaning:'堂堂〜竟然〜',example:{ja:'名探偵ともあろう者が、こんな初歩的な間違いをするとは。',zh:'堂堂名偵探竟然會犯這種基本錯誤。',highlight:'名探偵ともあろう'},tip:'「ともあろう者／人が」後接意外、不該有的行為，帶責備語氣；常與「〜とは」呼應。',quiz:{blank:'ともあろう',distractors:['ともなく','ともすれば','ともなしに']}},{id:'n1-g101',pattern:'〜ともなく',connection:'疑問詞（＋ 助詞） ＋ ともなく／動詞辭書形 ＋ ともなく',meaning:'不經意地〜、不知〜',example:{ja:'どこからともなく、ピアノの音が聞こえてきた。',zh:'不知從哪裡傳來了鋼琴聲。',highlight:'どこからともなく'},tip:'接疑問詞表「不知〜」（どこからともなく），接動詞表「無意中」；與「ともなしに」同義。',quiz:{blank:'ともなく',distractors:['ともなると','ともあろう','ともすれば']}},{id:'n1-g102',pattern:'〜ともなしに',connection:'動詞辭書形 ＋ ともなしに',meaning:'無意中〜',example:{ja:'見るともなしに窓の外を見ていたら、怪しい男がいた。',zh:'無意間望向窗外，發現有個可疑的男人。',highlight:'見るともなしに'},tip:'多接「見る・聞く・言う」，前後常重複同一或相近動詞；＝「ともなく」。',quiz:{blank:'ともなしに',distractors:['ともなると','ともあろう','とばかりに']}},{id:'n1-g103',pattern:'〜ともすれば',connection:'ともすれば ＋ 句子',meaning:'往往會〜、動不動就〜',example:{ja:'人はともすれば、見たいものだけを見てしまう。',zh:'人往往只會看自己想看的東西。',highlight:'ともすれば'},tip:'副詞用法，表「容易傾向〜（多為負面）」；同義「ややもすれば」，勿與「ともなると」混淆。',quiz:{blank:'ともすれば',distractors:['ともなく','ともあろう','ともなると']}},{id:'n1-g104',pattern:'〜といったらない',connection:'名詞（含形容詞さ形）／い形容詞辭書形／な形容詞語幹 ＋ といったらない',meaning:'〜得不得了、非常〜',example:{ja:'あの屋敷の不気味さといったらない。',zh:'那棟宅邸陰森得不得了。',highlight:'不気味さといったらない'},tip:'表程度極端，好壞皆可；口語「ったらない」。勿與「といったところだ（頂多）」混淆。',quiz:{blank:'といったらない',distractors:['といったところだ','にすぎない','どころではない']}},{id:'n1-g105',pattern:'〜といったらありはしない',connection:'名詞（含形容詞さ形）／い形容詞辭書形／な形容詞語幹 ＋ といったらありはしない',meaning:'〜得要命（多為負面）',example:{ja:'彼の態度の悪さといったらありはしない。',zh:'他的態度差得要命。',highlight:'悪さといったらありはしない'},tip:'只用於負面評價，口語作「ったらありゃしない」；正負皆可的是「といったらない」。',quiz:{blank:'といったらありはしない',distractors:['といったところだ','どころではない','にほかならない']}},{id:'n1-g106',pattern:'〜といったところだ',connection:'名詞 ＋ といったところだ',meaning:'大概就〜左右、頂多〜',example:{ja:'犯行に要した時間は、せいぜい十分といったところだ。',zh:'犯案所花的時間，頂多十分鐘左右。',highlight:'十分といったところだ'},tip:'表程度不高「頂多〜左右」，常與「せいぜい・まあ」連用；勿與「といったらない」混淆。',quiz:{blank:'といったところだ',distractors:['といったらない','にほかならない','にかたくない']}},{id:'n1-g107',pattern:'〜といわず〜といわず',connection:'名詞 ＋ といわず ＋ 名詞 ＋ といわず',meaning:'不論是〜還是〜（全部）',example:{ja:'部屋の中は、床といわず壁といわず血だらけだった。',zh:'房間裡不論地板還是牆壁，到處都是血。',highlight:'床といわず壁といわず'},tip:'舉出兩個例子表示「全部、到處」，多描述負面實況；與「といい〜といい（評價）」區別。',quiz:{blank:'といわず壁といわず',distractors:['なり壁なり','につけ壁につけ','はおろか壁はおろか']}},{id:'n1-g108',pattern:'〜と言わんばかりに',connection:'普通形 ＋ と言わんばかりに',meaning:'簡直像是在說〜似的',example:{ja:'彼は「お前が犯人だ」と言わんばかりに私をにらんだ。',zh:'他瞪著我，簡直像在說「你就是犯人」。',highlight:'と言わんばかりに'},tip:'雖沒說出口，但態度表情就像在說〜；同義「とばかりに」，用於描述他人。',quiz:{blank:'と言わんばかりに',distractors:['と言えども','と言うに及ばず','と言わずもがな']}},{id:'n1-g109',pattern:'〜ときている',connection:'普通形 ＋ ときている',meaning:'再加上〜（更是如此）',example:{ja:'この店は安くて、しかもうまいときている。',zh:'這家店便宜，而且還好吃。',highlight:'うまいときている'},tip:'口語，舉出特別的條件並加以評價，後句常接「〜のだから、〜はずだ」；名詞也可直接接。',quiz:{blank:'ときている',distractors:['といったところだ','きらいがある','にすぎない']}},{id:'n1-g110',pattern:'〜と相まって',connection:'名詞 ＋ と相まって',meaning:'與〜相結合、加上〜',example:{ja:'濃い霧と相まって、屋敷は一層不気味に見えた。',zh:'再加上濃霧，宅邸看起來更加陰森。',highlight:'濃い霧と相まって'},tip:'兩個因素相加產生更強效果，常用「〜と相まって、一層／ますます〜」；書面語。',quiz:{blank:'と相まって',distractors:['をよそに','にひきかえ','をものともせず']}},{id:'n1-g111',pattern:'〜とて',connection:'名詞 ＋ とて',meaning:'即使是〜也',example:{ja:'名探偵とて人間だ。間違えることもある。',zh:'名偵探也是人，也會有出錯的時候。',highlight:'名探偵とて'},tip:'「即使是〜也」＝「でも／だって」的硬い表現；另有「〜たとて（即使〜也）」用法。',quiz:{blank:'とて',distractors:['ならでは','こそ','たる']}},{id:'n1-g112',pattern:'〜としたところで',connection:'名詞／普通形 ＋ としたところで',meaning:'即使〜也〜',example:{ja:'今から急いだとしたところで、終電には間に合わない。',zh:'就算現在趕，也趕不上末班車了。',highlight:'急いだとしたところで'},tip:'「即使假設〜也」，後句多為否定或無用的結果；同義「としたって」（口語）、「にしても」。',quiz:{blank:'としたところで',distractors:['とあれば','からには','とばかりに']}},{id:'n1-g113',pattern:'〜としたって',connection:'名詞／普通形 ＋ としたって',meaning:'就算〜也（口語）',example:{ja:'私としたって、彼を疑いたくはない。',zh:'就算是我，也不想懷疑他。',highlight:'私としたって'},tip:'「としたところで」的口語形；接人稱名詞時表「站在〜的立場也」。',quiz:{blank:'としたって',distractors:['ともあろう','とあれば','ならでは']}},{id:'n1-g114',pattern:'〜と思いきや',connection:'普通形 ＋ と思いきや',meaning:'原以為〜，沒想到〜',example:{ja:'事件は解決したと思いきや、第二の殺人が起きた。',zh:'原以為案件解決了，沒想到又發生了第二起命案。',highlight:'解決したと思いきや'},tip:'「原以為〜，結果卻相反」，後句常為意外結果；硬い表現，不可用於說話者意志句。',quiz:{blank:'と思いきや',distractors:['とばかりに','とあって','と相まって']}},{id:'n1-g115',pattern:'〜ところを（逆接）',connection:'動詞普通形／い形容詞辭書形／な形容詞な／名詞の ＋ ところを',meaning:'正當〜的時候、在〜之際卻',example:{ja:'お忙しいところを、お時間をいただきありがとうございます。',zh:'在您百忙之中撥冗，非常感謝。',highlight:'お忙しいところを'},tip:'客套用法「お忙しいところを／お休みのところを〜」，表示在對方不便時仍打擾，後接致謝或致歉。',quiz:{blank:'ところを',distractors:['ところで','ものを','ばかりに']}},{id:'n1-g116',pattern:'〜ところを（被發現）',connection:'動詞普通形 ＋ ところを',meaning:'正在〜的時候（被）',example:{ja:'犯人は金庫を開けているところを取り押さえられた。',zh:'犯人正在開保險箱時被制伏了。',highlight:'開けているところを'},tip:'後接「見られる・捕まる・取り押さえる・助ける」等動詞，表動作正進行時被看到或被處置。',quiz:{blank:'ところを',distractors:['ものを','ことなしに','ともなく']}},{id:'n1-g117',pattern:'〜ても差し支えない',connection:'動詞て形 ＋ も差し支えない',meaning:'〜也無妨',example:{ja:'この資料は外部に公開しても差し支えない。',zh:'這份資料對外公開也無妨。',highlight:'公開しても差し支えない'},tip:'＝「てもかまわない」的禮貌、正式說法；常見於公文與商務場合。',quiz:{blank:'ても差し支えない',distractors:['てはかなわない','てやまない','てしかるべきだ']}},{id:'n1-g118',pattern:'〜てはばからない',connection:'動詞て形 ＋ はばからない',meaning:'毫無顧忌地〜',example:{ja:'彼は自分こそ天才だと公言してはばからない。',zh:'他毫不顧忌地公開宣稱自己才是天才。',highlight:'公言してはばからない'},tip:'多接「公言する・断言する・自称する」，帶負面評價；勿與「てやまない（衷心〜）」混淆。',quiz:{blank:'てはばからない',distractors:['てやまない','てもともとだ','てはかなわない']}},{id:'n1-g119',pattern:'〜てしかるべきだ',connection:'動詞て形 ＋ しかるべきだ',meaning:'理應〜、應該〜',example:{ja:'これほどの証拠があれば、再捜査されてしかるべきだ。',zh:'有了這麼多證據，理應重新調查。',highlight:'再捜査されてしかるべきだ'},tip:'「理所當然應該〜」，用於批評現狀未達應有狀態；書面語，常見被動形「〜されてしかるべきだ」。',quiz:{blank:'てしかるべきだ',distractors:['てはかなわない','てやまない','てもともとだ']}},{id:'n1-g120',pattern:'〜てもともとだ',connection:'動詞て形／名詞・な形容詞語幹＋で ＋ もともとだ',meaning:'就算〜也不吃虧',example:{ja:'ダメでもともとだ。彼に直接聞いてみよう。',zh:'失敗了也不吃虧，直接問他看看吧。',highlight:'ダメでもともとだ'},tip:'慣用「ダメでもともと（ダメもと）」，表示失敗也無損失，鼓勵嘗試；口語。',quiz:{blank:'でもともとだ',distractors:['ではすまされない','でなくてなんだろう','といったらない']}},{id:'n1-g121',pattern:'〜ては（反覆）',connection:'動詞て形 ＋ は ＋ 動詞',meaning:'〜了又〜（反覆）',example:{ja:'彼は報告書を書いては消し、一晩中悩んでいた。',zh:'他把報告書寫了又擦，煩惱了一整晚。',highlight:'書いては消し'},tip:'「Vては V」表兩動作反覆交替，常重複兩次「書いては消し、書いては消し」；書面多用。',quiz:{blank:'ては',distractors:['ても','てこそ','てまで']}},{id:'n1-g122',pattern:'〜てはかなわない',connection:'動詞て形 ＋ はかなわない',meaning:'〜可受不了',example:{ja:'毎晩こんなに騒がれてはかなわない。',zh:'每晚這樣吵鬧可真受不了。',highlight:'騒がれてはかなわない'},tip:'「〜可受不了」，常接被動（騒がれては）；同義「てはたまらない」。',quiz:{blank:'てはかなわない',distractors:['ても差し支えない','てしかるべきだ','てもともとだ']}},{id:'n1-g123',pattern:'〜ないものでもない',connection:'動詞ない形 ＋ ものでもない',meaning:'也不是不〜、也許會〜',example:{ja:'条件次第では、協力しないものでもない。',zh:'看條件如何，也不是不能合作。',highlight:'協力しないものでもない'},tip:'消極肯定「也不是不能〜」，常與「条件次第では」連用；同義「ないでもない」。',quiz:{blank:'ないものでもない',distractors:['ないではすまない','ないではおかない','ないまでも']}},{id:'n1-g124',pattern:'〜ないでもない',connection:'動詞ない形 ＋ でもない',meaning:'也不是不〜',example:{ja:'彼の気持ちもわからないでもない。',zh:'他的心情我也不是不了解。',highlight:'わからないでもない'},tip:'消極肯定，多接「わかる・気がする・考える」；同義「なくもない」，雙重否定勿誤解成否定。',quiz:{blank:'ないでもない',distractors:['ないではおかない','ないではすまない','ずにはいられない']}},{id:'n1-g125',pattern:'〜なくもない',connection:'動詞ない形（去い） ＋ くもない',meaning:'也並非不〜',example:{ja:'言われてみれば、そう見えなくもない。',zh:'被你這麼一說，看起來也不是不像。',highlight:'見えなくもない'},tip:'消極肯定「也不是不〜」，多接「見える・思える」等；與「ないでもない」可互換。',quiz:{blank:'なくもない',distractors:['ないではおかない','ずにはすまない','なくてはならない']}},{id:'n1-g126',pattern:'〜なしに',connection:'名詞 ＋ なしに',meaning:'沒有〜就〜',example:{ja:'彼は令状なしに家宅捜索を行った。',zh:'他在沒有搜索票的情況下搜索了住宅。',highlight:'令状なしに'},tip:'「沒有〜就做了〜」，後句為肯定事實；「なしには」後句則必為否定（不能〜）。',quiz:{blank:'なしに',distractors:['ならでは','ぬきでは','はおろか']}},{id:'n1-g127',pattern:'〜なしには',connection:'名詞 ＋ なしには',meaning:'沒有〜就無法〜',example:{ja:'皆さんの協力なしには、この事件は解決できなかった。',zh:'沒有各位的協助，這起案件就無法解決。',highlight:'協力なしには'},tip:'「なしには〜ない」構成必要條件；同義「なくしては」「ぬきには」。',quiz:{blank:'なしには',distractors:['ならでは','はおろか','ともなると']}},{id:'n1-g128',pattern:'〜ならいざしらず',connection:'名詞 ＋ ならいざしらず',meaning:'如果是〜就算了，但〜',example:{ja:'子どもならいざしらず、大人がそんな嘘を信じるものか。',zh:'小孩子也就算了，大人怎麼會相信那種謊話。',highlight:'子どもならいざしらず'},tip:'「〜倒也罷了，但〜」，後句常為驚訝、責備；同義「ならまだしも」，硬い表現。',quiz:{blank:'ならいざしらず',distractors:['ならでは','とあれば','ともあろう']}},{id:'n1-g129',pattern:'〜ならまだしも',connection:'名詞 ＋ ならまだしも',meaning:'如果是〜倒還可以，但〜',example:{ja:'一度ならまだしも、三度も同じミスをするとは。',zh:'一次也就罷了，竟然同樣的錯犯了三次。',highlight:'一度ならまだしも'},tip:'「〜還可容忍，但〜就太過分」，後句帶不滿；與「ならいざしらず」近義。',quiz:{blank:'ならまだしも',distractors:['ならでは','とあれば','ともなると']}},{id:'n1-g130',pattern:'〜なりに',connection:'名詞／普通形 ＋ なりに',meaning:'與〜相應地、以〜自己的方式',example:{ja:'私なりに考えた結果、犯人は彼だと思う。',zh:'我按自己的方式思考後，認為犯人是他。',highlight:'私なりに'},tip:'「以〜相應的方式」，常接人稱（私なりに）；名詞修飾用「なりの」。勿與「なりとも」混淆。',quiz:{blank:'なりに',distractors:['ならでは','なりとも','たりとも']}},{id:'n1-g131',pattern:'〜なりの',connection:'名詞 ＋ なりの ＋ 名詞',meaning:'與〜相應的、〜自己的',example:{ja:'彼には彼なりの事情があったのだろう。',zh:'他應該有他自己的苦衷吧。',highlight:'彼なりの'},tip:'「〜自己的、與〜相應的」，常見「〜には〜なりの〜がある」；與「ならではの（獨有）」區別。',quiz:{blank:'なりの',distractors:['たる','とおぼしき','ともあろう']}},{id:'n1-g132',pattern:'〜なり〜なり',connection:'名詞／動詞辭書形 ＋ なり ＋ 名詞／動詞辭書形 ＋ なり',meaning:'〜也好〜也好（舉例選擇）',example:{ja:'わからないことがあれば、電話するなりメールするなりしてください。',zh:'如果有不懂的地方，打電話或寄信都可以。',highlight:'電話するなりメールするなり'},tip:'舉例供選擇，後句多為建議或命令（〜してください）；不可用於過去事實描述。',quiz:{blank:'なりメールするなり',distractors:['やらメールするやら','といわずメールするといわず','につけメールするにつけ']}},{id:'n1-g133',pattern:'〜なりとも',connection:'名詞 ＋ なりとも',meaning:'哪怕只是〜也好',example:{ja:'少しなりとも、お役に立てれば幸いです。',zh:'哪怕只能幫上一點忙，我也很欣慰。',highlight:'少しなりとも'},tip:'「哪怕一點也好」，後接願望、請求；「たりとも」則接否定（一円たりとも〜ない）。',quiz:{blank:'なりとも',distractors:['たりとも','とて','ならでは']}},{id:'n1-g134',pattern:'〜ばこそ',connection:'動詞／形容詞ば形 ＋ こそ',meaning:'正因為〜才〜',example:{ja:'君を信頼していればこそ、この仕事を任せるのだ。',zh:'正因為信任你，才把這份工作交給你。',highlight:'信頼していればこそ'},tip:'強調理由「正因為〜才」，句尾常為「のだ」；同義「からこそ」，書面語。',quiz:{blank:'いればこそ',distractors:['いるにもかかわらず','いたところで','いようものなら']}},{id:'n1-g135',pattern:'〜ば〜たで',connection:'動詞・い形容詞ば形 ＋ 同一詞た形 ＋ で',meaning:'〜了也有〜的（麻煩）',example:{ja:'お金はなければ困るが、あればあったで悩みが増える。',zh:'沒錢很困擾，有了錢也有有錢的煩惱。',highlight:'あればあったで'},tip:'「Vば Vたで」表做了／有了也有另一種麻煩，前後重複同一詞；同義「たら〜たで」。',quiz:{blank:'あったで',distractors:['あってこそ','あるなり','あるまいし']}},{id:'n1-g136',pattern:'〜たら〜たで',connection:'動詞たら形 ＋ 動詞た形 ＋ で',meaning:'〜了也有〜的（問題）',example:{ja:'犯人が捕まったら捕まったで、今度は裁判が大変だ。',zh:'犯人抓到了，接下來審判又很辛苦。',highlight:'捕まったら捕まったで'},tip:'「〜了也有〜的問題」，前後必須重複同一動詞；與「ば〜たで」同義，口語感較強。',quiz:{blank:'捕まったで',distractors:['捕まってこそ','捕まったきり','捕まるまいが']}},{id:'n1-g137',pattern:'〜はおろか',connection:'名詞 ＋ はおろか',meaning:'別說〜了，連〜也',example:{ja:'現場には指紋はおろか、髪の毛一本残っていなかった。',zh:'現場別說指紋了，連一根頭髮都沒留下。',highlight:'指紋はおろか'},tip:'「別說〜，連〜也」，後句常與「も・さえ・すら」及否定呼應；不可用於命令、意志句。',quiz:{blank:'はおろか',distractors:['はさておき','にひきかえ','と相まって']}},{id:'n1-g138',pattern:'〜もさることながら',connection:'名詞 ＋ もさることながら',meaning:'〜固然〜，更〜',example:{ja:'彼の推理力もさることながら、その観察力には驚かされる。',zh:'他的推理能力固然出色，觀察力更是令人驚訝。',highlight:'推理力もさることながら'},tip:'「〜固然如此，〜更是」，重點在後項，多為正面評價；與「はもちろん」近義。',quiz:{blank:'もさることながら',distractors:['はおろか','にひきかえ','をよそに']}},{id:'n1-g139',pattern:'〜も顧みず',connection:'名詞 ＋ も顧みず',meaning:'連〜也不顧',example:{ja:'彼女は周囲の反対も顧みず、単身で調査を続けた。',zh:'她連周遭的反對都不顧，獨自繼續調查。',highlight:'反対も顧みず'},tip:'多接「危険・反対・周囲」等，表不顧〜而行動；同義「をものともせず」「をよそに」。',quiz:{blank:'も顧みず',distractors:['もそこそこに','もさることながら','にもまして']}},{id:'n1-g140',pattern:'〜もなんのその',connection:'名詞 ＋ もなんのその',meaning:'〜根本不算什麼',example:{ja:'刑事たちは大雨もなんのその、張り込みを続けた。',zh:'刑警們不把大雨當一回事，繼續埋伏。',highlight:'大雨もなんのその'},tip:'把困難不當回事，帶讚賞語氣；同義「をものともせず」，多接惡劣天氣、傷病等。',quiz:{blank:'もなんのその',distractors:['もそこそこに','もさることながら','と相まって']}},{id:'n1-g141',pattern:'〜もそこそこに',connection:'名詞 ＋ もそこそこに',meaning:'匆匆〜就〜',example:{ja:'彼は挨拶もそこそこに、本題に入った。',zh:'他草草打過招呼就切入正題。',highlight:'挨拶もそこそこに'},tip:'「匆匆〜就〜」，多接「挨拶・食事」等，表急著做下一件事。',quiz:{blank:'もそこそこに',distractors:['もなんのその','も顧みず','もさることながら']}},{id:'n1-g142',pattern:'〜ものを',connection:'普通形 ＋ ものを',meaning:'〜就好了，可是〜（遺憾）',example:{ja:'早く相談してくれれば助けられたものを。',zh:'早點找我商量的話，明明就能幫你。',highlight:'助けられたものを'},tip:'句尾表遺憾、不滿「明明可以〜」，常搭「〜ば〜ものを」；與「ものの（雖然）」易混。',quiz:{blank:'ものを',distractors:['ものの','ものなら','ものだから']}},{id:'n1-g143',pattern:'〜ものとして',connection:'普通形 ＋ ものとして',meaning:'當作〜、假定〜',example:{ja:'この件はなかったものとして処理します。',zh:'這件事就當作沒發生過來處理。',highlight:'なかったものとして'},tip:'「當作〜、視為〜」，常見公文「〜ものとする（規定）」及「なかったものとして」。',quiz:{blank:'ものとして',distractors:['ものを','ものなら','ものの']}},{id:'n1-g144',pattern:'〜ものやら',connection:'疑問詞 ＋ 普通形 ＋ ものやら',meaning:'到底〜呢（不知道）',example:{ja:'あの男は今ごろどこで何をしているものやら。',zh:'那個男人現在到底在哪裡做什麼呢。',highlight:'しているものやら'},tip:'與疑問詞連用，表「到底〜呢」的擔心或疑惑；句尾自言自語，同義「のだろうか」。',quiz:{blank:'ものやら',distractors:['ものを','ものの','ものとして']}},{id:'n1-g145',pattern:'〜こととて',connection:'名詞 ＋ の ＋ こととて／普通形 ＋ こととて',meaning:'因為〜（所以請見諒）',example:{ja:'慣れぬこととて、ご迷惑をおかけしました。',zh:'因為不熟悉，給您添麻煩了。',highlight:'慣れぬこととて'},tip:'說明理由並請求原諒的古風硬い表現，常接「慣れぬ・知らぬ」等文語否定。',quiz:{blank:'こととて',distractors:['ことなしに','ことか','ことのないよう']}},{id:'n1-g146',pattern:'〜ことなしに',connection:'動詞辭書形 ＋ ことなしに',meaning:'不〜就〜、沒有〜而〜',example:{ja:'努力することなしに、成功は得られない。',zh:'不努力就無法獲得成功。',highlight:'努力することなしに'},tip:'「不〜就（無法）〜」，後句多為否定；同義「なくしては」，書面語。',quiz:{blank:'ことなしに',distractors:['こととて','ことだから','ことのないよう']}},{id:'n1-g147',pattern:'〜ことこのうえない',connection:'な形容詞な／い形容詞辭書形 ＋ ことこのうえない',meaning:'再〜不過了、極其〜',example:{ja:'夜道を一人で歩くのは、危険なことこのうえない。',zh:'一個人走夜路是再危險不過的了。',highlight:'危険なことこのうえない'},tip:'「再〜不過」，前接表感情或評價的形容詞，書面語；同類「極まりない」「の極みだ」。',quiz:{blank:'ことこのうえない',distractors:['ことのないよう','こととて','ことなしに']}},{id:'n1-g148',pattern:'〜この上ない',connection:'な形容詞語幹 ＋ この上ない（い形容詞用「〜ことこの上ない」）／この上ない ＋ 名詞',meaning:'無比〜、最〜不過',example:{ja:'このような結末になり、残念この上ない。',zh:'落得這樣的結局，真是遺憾至極。',highlight:'残念この上ない'},tip:'也可作連體「この上ない喜び」；與「ことこのうえない」同義，屬書面語。',quiz:{blank:'この上ない',distractors:['にすぎない','どころではない','ではすまされない']}},{id:'n1-g149',pattern:'〜ことのないよう（に）',connection:'動詞辭書形 ＋ ことのないよう（に）',meaning:'為了不要〜',example:{ja:'二度と同じ過ちを犯すことのないよう、注意してください。',zh:'請注意不要再犯同樣的錯誤。',highlight:'犯すことのないよう'},tip:'「為了不〜」，＝「ないように」的正式說法，常見於公告、注意事項。',quiz:{blank:'ことのないよう',distractors:['ことなしに','ことこのうえなく','こととて']}},{id:'n1-g150',pattern:'〜始末だ',connection:'動詞辭書形／ない形 ＋ 始末だ（＊こんな／あんな始末だ）',meaning:'結果竟落到〜的地步',example:{ja:'彼は借金を重ね、ついには家まで売る始末だった。',zh:'他債台高築，最後竟落到連房子都要賣掉的地步。',highlight:'売る始末だった'},tip:'經過一連串壞事後落到糟糕結果，帶負面評價；常與「ついには・あげくに」連用。',quiz:{blank:'始末だった',distractors:['きらいがあった','までもなかった','にすぎなかった']}},{id:'n1-g151',pattern:'〜すら',connection:'名詞（＋ 助詞） ＋ すら',meaning:'連〜都',example:{ja:'彼は自分の名前すら思い出せなかった。',zh:'他連自己的名字都想不起來。',highlight:'名前すら'},tip:'＝「さえ」的書面語，舉極端例子；接主語時可作「ですら」。',quiz:{blank:'すら',distractors:['こそ','だけ','ならでは']}},{id:'n1-g152',pattern:'〜ずとも',connection:'動詞ない形（去ない） ＋ ずとも',meaning:'即使不〜也',example:{ja:'言わずとも、彼の気持ちは伝わってきた。',zh:'即使不說，他的心意也傳達過來了。',highlight:'言わずとも'},tip:'「即使不〜也」＝「なくても」的文語形；する變「せずとも」。',quiz:{blank:'ずとも',distractors:['ずじまいで','ずにはおかず','ずくめで']}},{id:'n1-g153',pattern:'〜そびれる',connection:'動詞ます形 ＋ そびれる',meaning:'錯過〜的機會、沒能〜',example:{ja:'忙しくて、彼に礼を言いそびれてしまった。',zh:'太忙了，結果錯過了向他道謝的時機。',highlight:'言いそびれて'},tip:'「錯過〜的時機」，多接「言う・聞く・寝る・食べる」；同義「〜損なう」。',quiz:{blank:'そびれて',distractors:['かけて','まくって','尽くして']}},{id:'n1-g154',pattern:'〜たが最後',connection:'動詞た形 ＋ が最後',meaning:'一旦〜就（完了）',example:{ja:'あの組織に目をつけられたが最後、逃げられない。',zh:'一旦被那個組織盯上就逃不掉了。',highlight:'つけられたが最後'},tip:'「一旦〜就完了」，後句為無法挽回的負面結果；同義「たら最後」。',quiz:{blank:'が最後',distractors:['が早いか','ところで','きり']}},{id:'n1-g155',pattern:'〜たら最後',connection:'動詞た形 ＋ ら最後',meaning:'一旦〜就（無法挽回）',example:{ja:'あの部屋に入ったら最後、二度と出てこられない。',zh:'一旦進了那個房間，就再也出不來了。',highlight:'入ったら最後'},tip:'「たが最後」的口語形，後句多為「〜ない・〜しまう」等負面結果。',quiz:{blank:'ら最後',distractors:['ものの','ところで','が早いか']}},{id:'n1-g156',pattern:'〜たりとも',connection:'數量詞（一〜） ＋ たりとも',meaning:'即使〜也（不）、連〜都不',example:{ja:'一秒たりとも、容疑者から目を離すな。',zh:'連一秒都不准讓嫌犯離開視線。',highlight:'一秒たりとも'},tip:'接「一＋量詞」，後接否定或禁止；勿與「なりとも（後接願望）」混淆。',quiz:{blank:'たりとも',distractors:['なりとも','ばかりか','かたがた']}},{id:'n1-g157',pattern:'〜だに',connection:'名詞／動詞辭書形 ＋ だに',meaning:'光是〜就、連〜都',example:{ja:'あの夜の出来事は、思い出すだに恐ろしい。',zh:'那一晚發生的事，光是回想就令人害怕。',highlight:'思い出すだに'},tip:'接「想像する・思い出す・聞く」＋負面情感，或「夢にだに思わない」；古風書面語。',quiz:{blank:'だに',distractors:['すら','とて','ばこそ']}},{id:'n1-g158',pattern:'〜たる',connection:'名詞 ＋ たる ＋ 名詞',meaning:'身為〜的',example:{ja:'一国の首相たる人物が、そのような発言をすべきではない。',zh:'身為一國首相的人，不應該說出那種話。',highlight:'首相たる'},tip:'「身為〜的」，前接具崇高地位的名詞，強調應有的資格與責任；硬い書面語。',quiz:{blank:'たる',distractors:['なりの','とおぼしき','ならではの']}},{id:'n1-g159',pattern:'〜たるもの',connection:'名詞 ＋ たるもの',meaning:'作為〜就應該〜',example:{ja:'警察官たるもの、市民の安全を第一に考えねばならない。',zh:'身為警察，必須以市民的安全為第一優先。',highlight:'警察官たるもの'},tip:'「身為〜就應〜」，後句常為「べきだ・ねばならない」；與「ともあろう（責備）」區別。',quiz:{blank:'たるもの',distractors:['ならまだしも','はおろか','をよそに']}},{id:'n1-g160',pattern:'〜でなくてなんだろう',connection:'名詞 ＋ でなくてなんだろう',meaning:'這不是〜又是什麼呢',example:{ja:'これが運命でなくてなんだろう。',zh:'這不是命運又是什麼呢？',highlight:'運命でなくてなんだろう'},tip:'反問強調「這正是〜」，多接「運命・愛・奇跡」等抽象名詞；文學性書面語。',quiz:{blank:'でなくてなんだろう',distractors:['にすぎない','ではすまされない','といったところだ']}},{id:'n1-g161',pattern:'〜ではすまされない',connection:'名詞／普通形 ＋ ではすまされない',meaning:'不能以〜了事',example:{ja:'「知らなかった」ではすまされない問題だ。',zh:'這不是一句「不知道」就能了事的問題。',highlight:'「知らなかった」ではすまされない'},tip:'「不能以〜了事」，常接「知らなかった・冗談」；同義「ではすまない」。',quiz:{blank:'ではすまされない',distractors:['でなくてなんだろう','にほかならない','といったらない']}},{id:'n1-g162',pattern:'〜手前',connection:'名詞 ＋ の ＋ 手前／動詞普通形 ＋ 手前',meaning:'在〜面前（顧及面子）、既然〜',example:{ja:'部下の手前、弱音を吐くわけにはいかない。',zh:'在部下面前，不能說洩氣話。',highlight:'部下の手前'},tip:'「顧及〜的面子、既然〜了」，後句常為「わけにはいかない」；接名詞需加「の」。',quiz:{blank:'手前',distractors:['反面','かたわら','あげく']}},{id:'n1-g163',pattern:'〜とおぼしき',connection:'名詞 ＋ とおぼしき ＋ 名詞',meaning:'似乎是〜的、看起來像〜的',example:{ja:'現場で凶器とおぼしきナイフが発見された。',zh:'在現場發現了一把疑似凶器的刀子。',highlight:'凶器とおぼしき'},tip:'「看起來像是〜的」，＝「と思われる」的書面語，多見於新聞報導；同義「らしき」。',quiz:{blank:'とおぼしき',distractors:['ともあろう','たる','なりの']}},{id:'n1-g164',pattern:'〜のなんのと',connection:'普通形 ＋ のなんのと',meaning:'說什麼〜之類的',example:{ja:'彼は頭が痛いのなんのと言って、事情聴取を断った。',zh:'他說什麼頭痛之類的，拒絕了偵訊。',highlight:'痛いのなんのと'},tip:'引用他人的各種藉口或抱怨，帶不滿語氣，後常接「言って・文句を言う」；口語。',quiz:{blank:'のなんのと',distractors:['ものを','ともなく','ばこそ']}},{id:'n1-g165',pattern:'〜べくして',connection:'動詞辭書形 ＋ べくして ＋ 同一動詞た形',meaning:'必然會〜、理所當然地〜',example:{ja:'この事故は起こるべくして起こったのだ。',zh:'這起事故是必然會發生的。',highlight:'起こるべくして'},tip:'「Vべくして Vた」重複同一動詞，表必然結果；常見「起こるべくして起こった」。',quiz:{blank:'べくして',distractors:['べからず','まじき','ものの']}},{id:'n1-g166',pattern:'〜べし',connection:'動詞辭書形 ＋ べし',meaning:'應當〜、必須〜（文言）',example:{ja:'学生は学業に専念すべし。',zh:'學生應當專心於學業。',highlight:'専念すべし'},tip:'文語句尾表義務或命令，多見於標語、規章；否定形為「べからず」，する可作「すべし」。',quiz:{blank:'べし',distractors:['べからず','まじき','べく']}},{id:'n1-g167',pattern:'〜まじき',connection:'動詞辭書形 ＋ まじき ＋ 名詞',meaning:'不應有的、不可〜的',example:{ja:'それは教師にあるまじき行為だ。',zh:'那是身為教師不應有的行為。',highlight:'あるまじき'},tip:'「〜にあるまじき＋名詞」最常考，表身分上不應有的行為；是「べき」的否定文語形。',quiz:{blank:'まじき',distractors:['べからず','べき','べく']}},{id:'n1-g168',pattern:'〜までもなく',connection:'動詞辭書形 ＋ までもなく',meaning:'用不著〜、不必〜',example:{ja:'言うまでもなく、この件は極秘だ。',zh:'不用說，這件事是最高機密。',highlight:'言うまでもなく'},tip:'「用不著〜」，慣用「言うまでもなく」；勿與「ともなく（無意中）」混淆。',quiz:{blank:'までもなく',distractors:['ともなく','べくもなく','ものの']}},{id:'n1-g169',pattern:'〜ゆえ（に）',connection:'名詞（＋ の） ＋ ゆえ（に）／普通形 ＋ がゆえに',meaning:'因為〜、由於〜（文言）',example:{ja:'若さゆえの過ちだった。',zh:'那是年輕所犯的錯。',highlight:'若さゆえ'},tip:'「因為〜」的文語硬い表現，常見「〜ゆえの＋名詞」「〜がゆえに」。',quiz:{blank:'ゆえ',distractors:['とて','たる','ばかり']}},{id:'n1-g170',pattern:'〜かたがた',connection:'名詞 ＋ かたがた',meaning:'順便〜、兼〜',example:{ja:'お礼かたがた、ご報告に伺いました。',zh:'我來向您道謝，順便報告一下。',highlight:'お礼かたがた'},tip:'「兼做〜」，多接「お礼・ご挨拶・お見舞い」，後接「伺う・訪問する」；勿與「かたわら」混淆。',quiz:{blank:'かたがた',distractors:['かたわら','なりとも','たりとも']}},{id:'n1-g171',pattern:'〜かたわら',connection:'名詞 ＋ の ＋ かたわら／動詞辭書形 ＋ かたわら',meaning:'一邊〜一邊〜（從事本業之餘）',example:{ja:'彼は医師として働くかたわら、推理小説を書いている。',zh:'他一邊當醫生，一邊寫推理小說。',highlight:'働くかたわら'},tip:'「從事本業之餘兼做〜」，表長期並行；「かたがた」為一次性的順便。',quiz:{blank:'かたわら',distractors:['かたがた','がてら','そばから']}},{id:'n1-g172',pattern:'〜か否か',connection:'名詞／普通形 ＋ か否か',meaning:'是否〜',example:{ja:'彼が犯人か否かは、まだわからない。',zh:'他是否是犯人，還不清楚。',highlight:'犯人か否か'},tip:'＝「かどうか」的書面語，常見「〜か否かは」「〜か否かを判断する」。',quiz:{blank:'か否か',distractors:['であれ','とあれば','ならでは']}},{id:'n1-g173',pattern:'〜きりがない',connection:'動詞たら形／ば形／辭書形＋と ＋ きりがない',meaning:'〜起來沒完沒了',example:{ja:'疑い始めたらきりがない。',zh:'一旦開始懷疑就沒完沒了。',highlight:'疑い始めたらきりがない'},tip:'前面常接たら／ば／と表示「一〜就沒完沒了」；也說「〜てもきりがない」。勿與ためしがない（從未）混淆。',quiz:{blank:'きりがない',distractors:['ためしがない','すべがない','までもない']}},{id:'n1-g174',pattern:'〜極まる',connection:'な形容詞語幹 ＋ 極まる',meaning:'極其〜',example:{ja:'彼の態度は無礼極まる。',zh:'他的態度極其無禮。',highlight:'無礼極まる'},tip:'「無礼極まる」＝「無礼極まりない」，兩者都是「極其〜」，注意極まりない並非否定。「の極み」前須加の。',quiz:{blank:'極まる',distractors:['極みだ','限りだ','ずくめだ']}},{id:'n1-g175',pattern:'〜こそあれ',connection:'名詞 ＋ こそあれ',meaning:'只有〜而已（絕不會〜）',example:{ja:'彼には感謝こそあれ、恨みなど一切ない。',zh:'我對他只有感謝，絲毫沒有怨恨。',highlight:'感謝こそあれ'},tip:'「AこそあれBはない」只有A絕無B，書面語。與こそすれ（接動作性名詞／ます形）區別：こそあれ接名詞。',quiz:{blank:'こそあれ',distractors:['ばかりか','はおろか','もさることながら']}},{id:'n1-g176',pattern:'〜こそすれ',connection:'動詞ます形／漢語名詞（する動詞語幹） ＋ こそすれ ＋ 否定',meaning:'只會〜（絕不會〜）',example:{ja:'そのやり方では、問題は悪化こそすれ解決はしない。',zh:'那種做法只會讓問題惡化，不會解決。',highlight:'悪化こそすれ'},tip:'「AこそすれBはしない」只會A不會B，後句必為否定。接動作名詞或ます形；名詞存在用こそあれ。',quiz:{blank:'こそすれ',distractors:['ばかりか','はおろか','なりとも']}},{id:'n1-g177',pattern:'〜といい〜といい',connection:'名詞 ＋ といい ＋ 名詞 ＋ といい',meaning:'不論〜還是〜（都）',example:{ja:'動機といい手口といい、前の事件とそっくりだ。',zh:'不論動機還是手法，都和之前的案件一模一樣。',highlight:'動機といい手口といい'},tip:'舉兩例表示「無論哪方面都〜」，帶說話者評價。易混：といわず〜といわず（不分場所時間，全部）。',quiz:{blank:'といい手口といい',distractors:['なり手口なり','につけ手口につけ','たりとも手口たりとも']}},{id:'n1-g178',pattern:'〜というもの',connection:'期間 ＋ というもの',meaning:'整整〜以來（一直）',example:{ja:'この一週間というもの、彼はほとんど眠っていない。',zh:'這整整一週以來，他幾乎沒睡。',highlight:'一週間というもの'},tip:'接表期間的詞，表「這段時間一直〜」，帶感慨。易混：てからというもの（自從〜之後）。',quiz:{blank:'というもの',distractors:['というのは','ともなると','からある']}},{id:'n1-g179',pattern:'〜といっても過言ではない',connection:'普通形（名詞・な形容詞可省略だ） ＋ といっても過言ではない',meaning:'說是〜也不為過',example:{ja:'彼は日本一の探偵といっても過言ではない。',zh:'說他是日本第一的偵探也不為過。',highlight:'といっても過言ではない'},tip:'強力斷言「說是〜也不為過」，常用於評論文。與と言えなくもない（勉強可以說）語氣強弱相反。',quiz:{blank:'といっても過言ではない',distractors:['といったらない','というものではない','とは限らない']}},{id:'n1-g180',pattern:'〜がまま（に）',connection:'動詞辭書形（多為受身形）／名詞の ＋ がまま（に）',meaning:'任憑〜、照著〜',example:{ja:'彼は言われるがままに、書類に署名してしまった。',zh:'他任人擺布，就那樣在文件上簽了名。',highlight:'言われるがままに'},tip:'常見「言われるがまま」「なすがまま」「あるがまま」，表毫無抵抗、任憑擺布，書面語。',quiz:{blank:'がままに',distractors:['までに','ともなく','ことなしに']}},{id:'n1-g181',pattern:'〜ものとする',connection:'普通形 ＋ ものとする',meaning:'視為〜、規定為〜（法律文件）',example:{ja:'期限までに返答がない場合は、辞退したものとする。',zh:'期限前未回覆者，視為放棄。',highlight:'辞退したものとする'},tip:'法律、規章用語，表「視為〜／規定為〜」。勿與ものとして（假定〜而）混淆，ものとする用於句尾。',quiz:{blank:'ものとする',distractors:['ものとして','ものがある','までもない']}},{id:'n1-g182',pattern:'〜んとする',connection:'動詞ない形（去ない） ＋ んとする',meaning:'即將〜、正要〜（文言）',example:{ja:'日が沈まんとする頃、ようやく犯人の足取りがつかめた。',zh:'太陽即將西沉之際，終於掌握了犯人的行蹤。',highlight:'沈まんとする'},tip:'文言「正要〜」，する→せんとする。易混：んばかり（幾乎要〜）、んがため（為了〜）。',quiz:{blank:'んとする',distractors:['んがため','ずとも','ずして']}},{id:'n1-g183',pattern:'〜ずして',connection:'動詞ない形（去ない） ＋ ずして',meaning:'不〜而〜',example:{ja:'戦わずして勝つのが最上の策だ。',zh:'不戰而勝才是上策。',highlight:'戦わずして'},tip:'＝ないで／ずに的書面語，する→せずして。常見慣用：「労せずして」「期せずして」。',quiz:{blank:'ずして',distractors:['んばかりに','ないまでも','ざる']}},{id:'n1-g184',pattern:'〜ねばならない',connection:'動詞ない形（去ない） ＋ ねばならない',meaning:'必須〜（書面語）',example:{ja:'我々は一刻も早く真犯人を見つけねばならない。',zh:'我們必須盡快找出真兇。',highlight:'見つけねばならない'},tip:'＝なければならない的書面語，する→せねばならない（非しねば）。也作ねばならぬ。',quiz:{blank:'ねばならない',distractors:['ずじまいだ','るまでもない','るにはあたらない']}},{id:'n1-g185',pattern:'〜ぬ',connection:'動詞ない形（去ない） ＋ ぬ',meaning:'不〜（文言否定）',example:{ja:'彼は何も言わぬまま、部屋を出て行った。',zh:'他一句話也沒說就走出了房間。',highlight:'言わぬまま'},tip:'文言否定助動詞，可修飾名詞（知らぬ人）、接まま；する→せぬ。ず不能直接修飾名詞，注意區別。',quiz:{blank:'ぬ',distractors:['ず','まい','ねば']}},{id:'n1-g186',pattern:'〜ざる',connection:'動詞ない形（去ない） ＋ ざる ＋ 名詞',meaning:'不〜的（文言否定連體形）',example:{ja:'それは知られざる歴史の一面だった。',zh:'那是不為人知的歷史一面。',highlight:'知られざる'},tip:'ず的連體形，用來修飾名詞，如「知られざる」「欠くべからざる」。する→せざる。',quiz:{blank:'ざる',distractors:['ず','ねば','ずして']}},{id:'n1-g187',pattern:'〜甲斐もなく',connection:'名詞 ＋ の ＋ 甲斐もなく／動詞た形 ＋ 甲斐もなく',meaning:'白費〜、〜也沒有用',example:{ja:'医師の懸命の治療の甲斐もなく、被害者は亡くなった。',zh:'儘管醫師全力搶救，被害者仍不治身亡。',highlight:'治療の甲斐もなく'},tip:'表努力付出卻沒有得到期待的結果，帶遺憾。常見「努力の甲斐もなく」「看病した甲斐もなく」。',quiz:{blank:'甲斐もなく',distractors:['おかげで','ゆえに','かたわら']}},{id:'n1-g188',pattern:'〜こと請け合いだ',connection:'動詞辭書形／ない形 ＋ こと請け合いだ',meaning:'保證〜、一定〜',example:{ja:'この小説を読めば、犯人の正体に驚くこと請け合いだ。',zh:'讀了這本小說，保證你會對犯人的真實身分大吃一驚。',highlight:'驚くこと請け合いだ'},tip:'說話者強力保證「一定〜」，多用於推薦、宣傳。主觀斷定，接續以動詞為主。',quiz:{blank:'こと請け合いだ',distractors:['ことはない','ことなしに','きらいがある']}},{id:'n1-g189',pattern:'〜に忍びない',connection:'動詞辭書形 ＋ に忍びない',meaning:'不忍心〜',example:{ja:'遺族が泣き崩れる姿は、見るに忍びなかった。',zh:'遺族哭倒在地的模樣，讓人不忍卒睹。',highlight:'見るに忍びなかった'},tip:'「見るに忍びない」「聞くに忍びない」為常見搭配，表不忍心。易混：に堪えない（不堪〜）。',quiz:{blank:'に忍びなかった',distractors:['に足りなかった','にかたくなかった','までもなかった']}},{id:'n1-g190',pattern:'〜限りだ',connection:'い形容詞辭書形／な形容詞な形 ＋ 限りだ',meaning:'〜極了、非常〜（情感）',example:{ja:'一人で夜の屋敷に残されるなんて、心細い限りだ。',zh:'一個人被留在夜晚的宅邸裡，真是不安極了。',highlight:'心細い限りだ'},tip:'表說話者自身強烈情感（うれしい、寂しい、心細い）。不用於第三人稱的感受。',quiz:{blank:'限りだ',distractors:['までだ','始末だ','ものとする']}},{id:'n1-g191',pattern:'〜に限ったことではない',connection:'名詞 ＋ に限ったことではない',meaning:'不只是〜才這樣',example:{ja:'遅刻するのは今日に限ったことではない。',zh:'遲到不是只有今天才這樣。',highlight:'今日に限ったことではない'},tip:'表「不只〜，其他也一樣」，常帶負面評價。與に限る（最好是〜）意思完全不同。',quiz:{blank:'に限ったことではない',distractors:['に越したことはない','にほかならない','に限る']}},{id:'n1-g192',pattern:'ただ〜のみ',connection:'ただ ＋ 名詞／動詞辭書形 ＋ のみ',meaning:'只有〜、唯有〜',example:{ja:'今はただ、結果を待つのみだ。',zh:'現在只能等待結果。',highlight:'ただ、結果を待つのみ'},tip:'「ただ〜のみ」＝ただ〜だけ的書面語。「待つのみだ」也可換成「待つばかりだ」。',quiz:{blank:'のみ',distractors:['がてら','なり','そばから']}},{id:'n1-g193',pattern:'ひとり〜だけでなく',connection:'ひとり ＋ 名詞 ＋ だけでなく',meaning:'不單單是〜',example:{ja:'この問題はひとり警察だけでなく、社会全体の責任だ。',zh:'這個問題不單單是警方的責任，而是整個社會的責任。',highlight:'ひとり警察だけでなく'},tip:'「ひとり〜だけでなく／のみならず」＝ただ〜だけでなく的書面語，後接更大範圍。',quiz:{blank:'ひとり',distractors:['もはや','いかに','かりに']}},{id:'n1-g194',pattern:'〜も〜なら〜も〜だ',connection:'名詞 ＋ も ＋ 名詞 ＋ なら ＋ 名詞 ＋ も ＋ 名詞 ＋ だ',meaning:'〜也不對，〜也不對（雙方都有問題）',example:{ja:'嘘をつく夫も夫なら、それを黙認する妻も妻だ。',zh:'說謊的丈夫不對，默許的妻子也有問題。',highlight:'夫も夫なら、それを黙認する妻も妻だ'},tip:'同一名詞重複「AもAならBもBだ」，批評雙方都有問題，帶責難語氣。',quiz:{blank:'なら',distractors:['ばかりか','とて','なりに']}},{id:'n1-g195',pattern:'〜をして〜させる',connection:'名詞 ＋ をして ＋ 動詞使役形',meaning:'使〜、讓〜（文言）',example:{ja:'彼の熱意が、頑固な証人をして口を開かせた。',zh:'他的熱忱讓頑固的證人開了口。',highlight:'証人をして口を開かせた'},tip:'書面語，「AをしてBさせる」表A使B〜，後必接使役形。常見「〜をして言わしめる」。',quiz:{blank:'をして',distractors:['にして','をおいて','をよそに']}},{id:'n1-g196',pattern:'〜ともども',connection:'名詞 ＋ ともども',meaning:'和〜一起',example:{ja:'社長ともども、心よりお詫び申し上げます。',zh:'在此與社長一同致上誠摯的歉意。',highlight:'社長ともども'},tip:'「和〜一起」，多用於正式致詞或問候，如「親子ともども」「社長ともども」。',quiz:{blank:'ともども',distractors:['ぐるみ','ならでは','かたがた']}},{id:'n1-g197',pattern:'〜ぐるみ',connection:'名詞 ＋ ぐるみ',meaning:'連同〜整個、全〜',example:{ja:'これは会社ぐるみの不正だった。',zh:'這是整個公司上下一起的舞弊。',highlight:'会社ぐるみ'},tip:'「包括〜在內整個」，如「家族ぐるみ」「町ぐるみ」「組織ぐるみ」。易混：がらみ（與〜有關）。',quiz:{blank:'ぐるみ',distractors:['まみれ','ずくめ','めき']}},{id:'n1-g198',pattern:'〜ずく',connection:'名詞 ＋ ずく',meaning:'憑藉〜、完全靠〜',example:{ja:'彼は力ずくでドアをこじ開けた。',zh:'他用蠻力撬開了門。',highlight:'力ずく'},tip:'只用於固定詞：力ずく、金ずく、腕ずく、納得ずく。表「全憑〜」，非尽く。',quiz:{blank:'ずく',distractors:['ぐるみ','まみれ','ながら']}},{id:'n1-g199',pattern:'〜がらみ',connection:'名詞 ＋ がらみ',meaning:'與〜有關的、〜左右',example:{ja:'今回の殺人は遺産がらみの事件らしい。',zh:'這次的命案似乎和遺產有關。',highlight:'遺産がらみ'},tip:'接名詞表「與〜有牽連」（多負面）；接年齡、金額表「大約〜」（四十がらみ）。易混：ぐるみ。',quiz:{blank:'がらみ',distractors:['ぐるみ','まみれ','ずくめ']}},{id:'n1-g200',pattern:'〜づくし',connection:'名詞 ＋ づくし',meaning:'全是〜、盡是〜',example:{ja:'今年はいいことづくしの一年だった。',zh:'今年是好事連連的一年。',highlight:'いいことづくし'},tip:'「盡是〜」，常見「料理づくし」「いいことづくし」。與ずくめ意思接近，但ずくめ也可用於顏色（黒ずくめ）。',quiz:{blank:'づくし',distractors:['ぐるみ','がらみ','まがい']}},{id:'n1-g201',pattern:'〜三昧',connection:'名詞 ＋ 三昧',meaning:'盡情地〜、沉迷於〜',example:{ja:'引退後の彼は、読書三昧の日々を送っている。',zh:'退休後的他，每天都沉浸在讀書中。',highlight:'読書三昧'},tip:'「沉浸於〜」，如「読書三昧」「ぜいたく三昧」。常形成「〜三昧の日々」。',quiz:{blank:'三昧',distractors:['ぐるみ','まがい','がらみ']}},{id:'n1-g202',pattern:'〜ぶる',connection:'名詞／形容詞語幹 ＋ ぶる',meaning:'裝出〜的樣子',example:{ja:'彼は善人ぶっているが、裏では何をしているかわからない。',zh:'他裝成好人的樣子，背地裡卻不知道在做什麼。',highlight:'善人ぶって'},tip:'「裝出〜樣子」，帶負面評價，如「偉ぶる」「善人ぶる」。易混：びる（自然帶有〜樣子）。',quiz:{blank:'ぶって',distractors:['びて','ずくで','まみれで']}},{id:'n1-g203',pattern:'〜じみる',connection:'名詞 ＋ じみる',meaning:'帶有〜的樣子、像〜似的',example:{ja:'子どもじみた言い訳はやめなさい。',zh:'別再找孩子氣的藉口了。',highlight:'子どもじみた'},tip:'「看起來像〜」，多負面，如「子どもじみた」「年寄りじみた」「汗じみた」。',quiz:{blank:'じみた',distractors:['びた','がましい','ずくめの']}},{id:'n1-g204',pattern:'〜びる',connection:'名詞／形容詞語幹（限少數詞：大人、古、鄙、田舎等） ＋ びる',meaning:'帶有〜的樣子',example:{ja:'その少女は年の割に大人びた口調で話した。',zh:'那個少女說話的口氣比實際年齡成熟。',highlight:'大人びた'},tip:'只用於固定詞：大人びる、古びる、ひなびる。非刻意裝出，與ぶる（假裝）不同。',quiz:{blank:'びた',distractors:['まみれの','ずくめの','がらみの']}},{id:'n1-g205',pattern:'〜がましい',connection:'名詞／動詞ます形 ＋ がましい',meaning:'有〜的樣子、近似〜（負面）',example:{ja:'恩着せがましいことを言うつもりはないが、君を助けたのは私だ。',zh:'我無意邀功，但救了你的人是我。',highlight:'恩着せがましい'},tip:'負面「有〜之嫌」，固定詞如「恩着せがましい」「押し付けがましい」「未練がましい」。',quiz:{blank:'がましい',distractors:['めいた','じみた','ぶった']}},{id:'n1-g206',pattern:'〜いかに〜とも',connection:'いかに ＋ 動詞意向形 ＋ とも／いかに ＋ い形容詞く形 ＋ とも',meaning:'無論多麼〜也',example:{ja:'いかに巧妙に隠そうとも、真実はいつか明らかになる。',zh:'無論藏得多麼巧妙，真相總有一天會水落石出。',highlight:'いかに巧妙に隠そうとも'},tip:'「いかに〜（よ）うとも」＝どんなに〜ても的書面語。易混：うにも〜ない（想〜也無法）。',quiz:{blank:'うとも',distractors:['うにも','うとして','うではないか']}},{id:'n1-g207',pattern:'〜たところが',connection:'動詞た形 ＋ ところが',meaning:'〜結果卻（出乎意料）',example:{ja:'念のため調べたところが、意外な事実が判明した。',zh:'為了保險起見調查了一下，結果發現了意想不到的事實。',highlight:'調べたところが'},tip:'「做了〜結果卻」，後句為意外發現。易混：たところで（即使〜也沒用，後接負面）。',quiz:{blank:'ところが',distractors:['ところで','ところを','ものを']}},{id:'n1-g208',pattern:'〜ではなかろうか',connection:'普通形 ＋ のではなかろうか／名詞・な形容詞語幹 ＋ ではなかろうか',meaning:'是不是〜呢（文言推測）',example:{ja:'彼の証言には、何か裏があるのではなかろうか。',zh:'他的證詞是不是另有隱情呢？',highlight:'あるのではなかろうか'},tip:'＝のではないだろうか的書面語，委婉提出看法。與ではあるまいか意思相同。',quiz:{blank:'ではなかろうか',distractors:['ではあるまいし','ではすまされない','でも何でもない']}},{id:'n1-g209',pattern:'〜かろう',connection:'い形容詞語幹 ＋ かろう',meaning:'大概〜吧（文言推量）',example:{ja:'この寒さでは、夜の張り込みはさぞつらかろう。',zh:'這麼冷，夜裡埋伏想必很辛苦吧。',highlight:'つらかろう'},tip:'い形容詞的文言推量，常與「さぞ」呼應。也見於「よかろう」「なかろう」。',quiz:{blank:'かろう',distractors:['くとも','かれ','がましい']}},{id:'n1-g210',pattern:'〜ないではおかない',connection:'動詞ない形 ＋ ではおかない',meaning:'一定要〜、必然會〜',example:{ja:'この屈辱は、必ず晴らさないではおかない。',zh:'這份屈辱，我一定要洗刷。',highlight:'晴らさないではおかない'},tip:'＝ずにはおかない，表強烈意志或必然結果。する→しないではおかない／せずにはおかない。',quiz:{blank:'ないではおかない',distractors:['ないものでもない','ないでもない','ずじまいだ']}},{id:'n1-g211',pattern:'〜を余儀なくさせる',connection:'名詞 ＋ を余儀なくさせる',meaning:'迫使〜、使〜不得不〜',example:{ja:'大雪が、捜査の中断を余儀なくさせた。',zh:'大雪迫使調查不得不中斷。',highlight:'中断を余儀なくさせた'},tip:'主語是造成原因的事物（大雪が〜）。以人為主語時用「を余儀なくされる」，常考兩者主語區別。',quiz:{blank:'を余儀なくさせた',distractors:['を余儀なくされた','を禁じ得なかった','をものともしなかった']}},{id:'n1-g212',pattern:'〜にやぶさかでない',connection:'名詞／動詞辭書形 ＋ にやぶさかでない',meaning:'樂意〜、不吝於〜',example:{ja:'誤りを認めることにやぶさかではない。',zh:'我很樂意承認錯誤。',highlight:'認めることにやぶさかではない'},tip:'「樂意〜、並非不願〜」，硬い表現，常接「認める」「協力する」。並非「不得已」之意。',quiz:{blank:'にやぶさかではない',distractors:['にほかならない','に堪えない','に足りない']}},{id:'n1-g213',pattern:'〜をよしとする',connection:'名詞 ＋ をよしとする',meaning:'認為〜是好的、甘於〜',example:{ja:'彼は不正をよしとしない、まっすぐな刑事だった。',zh:'他是個不容許不正之事的正直刑警。',highlight:'不正をよしとしない'},tip:'多以否定「〜をよしとしない」出現，表不認同、不甘於〜。書面語。',quiz:{blank:'をよしとしない',distractors:['をものともしない','を禁じ得ない','を顧みない']}},{id:'n1-g214',pattern:'〜まがい',connection:'名詞 ＋ まがい',meaning:'仿〜的、近似〜的（贗品）',example:{ja:'彼は詐欺まがいの商売で大金を得ていた。',zh:'他靠著近乎詐欺的生意賺了大錢。',highlight:'詐欺まがい'},tip:'「近似〜、仿〜」，如「詐欺まがい」「本物まがい」。常以「〜まがいの＋名詞」出現。',quiz:{blank:'まがい',distractors:['ぐるみ','ずく','ぶり']}},{id:'n1-g215',pattern:'〜ためしがない',connection:'動詞た形 ＋ ためしがない',meaning:'從來沒有〜過',example:{ja:'彼が約束の時間に来たためしがない。',zh:'他從來沒有準時赴約過。',highlight:'来たためしがない'},tip:'接た形，帶不滿或責難「從來沒〜過」。比たことがない更帶主觀批評。',quiz:{blank:'ためしがない',distractors:['までもない','きりがない','すべがない']}},{id:'n1-g216',pattern:'〜くらいのものだ',connection:'名詞 ＋ くらいのものだ',meaning:'只有〜而已',example:{ja:'あの金庫を開けられるのは、社長くらいのものだ。',zh:'能打開那個保險箱的，也只有社長而已。',highlight:'社長くらいのものだ'},tip:'「也只有〜而已」，強調僅此一個。也作「ぐらいのものだ」。',quiz:{blank:'くらいのものだ',distractors:['に限ったことではない','どころではない','ともなると']}},{id:'n1-g217',pattern:'〜はまだしも',connection:'名詞 ＋ はまだしも',meaning:'〜倒也還好，但〜',example:{ja:'遅刻はまだしも、無断欠席は許されない。',zh:'遲到也就罷了，無故缺席可不被允許。',highlight:'遅刻はまだしも'},tip:'「A還說得過去，但B不行」，後接否定評價。與ならまだしも幾乎同義。',quiz:{blank:'はまだしも',distractors:['はおろか','にひきかえ','もさることながら']}},{id:'n1-g218',pattern:'〜てもなお',connection:'動詞て形 ＋ もなお',meaning:'即使〜仍然〜',example:{ja:'証拠を突きつけられてもなお、彼は否認した。',zh:'即使證據擺在眼前，他仍然否認。',highlight:'突きつけられてもなお'},tip:'＝ても的強調版，「即使〜仍然〜」，書面語。',quiz:{blank:'てもなお',distractors:['てこそ','てからというもの','てはじめて']}},{id:'n1-g219',pattern:'〜の極み',connection:'名詞 ＋ の極み',meaning:'極度的〜、〜之至',example:{ja:'このような事態を招き、痛恨の極みです。',zh:'導致這樣的事態，實在悔恨至極。',highlight:'痛恨の極み'},tip:'「〜之至」，如「痛恨の極み」「贅沢の極み」。與の至り相近，但至り多用於光栄、若気等。',quiz:{blank:'の極み',distractors:['ずくめ','まみれ','がらみ']}},{id:'n1-g220',pattern:'〜くとも',connection:'い形容詞語幹 ＋ くとも',meaning:'至少〜、即使〜（文言）',example:{ja:'遅くとも明日までには、鑑定結果が出るはずだ。',zh:'最晚明天之前，鑑定結果應該就會出來。',highlight:'遅くとも'},tip:'＝くても的書面語，常見固定說法「遅くとも」「少なくとも」「早くとも」。',quiz:{blank:'くとも',distractors:['かれ','かろう','くして']}},{id:'n1-g221',pattern:'〜あっての',connection:'名詞 ＋ あっての ＋ 名詞',meaning:'有了〜才有的〜',example:{ja:'お客様あっての商売です。',zh:'有顧客才有生意。',highlight:'お客様あっての'},tip:'「AあってのB」：有A才有B，強調A不可或缺。易混：ならでは（〜特有的）。',quiz:{blank:'あっての',distractors:['ならではの','ぐるみの','ながらの']}},{id:'n1-g222',pattern:'〜かれ〜かれ',connection:'い形容詞語幹 ＋ かれ ＋ 反義い形容詞語幹 ＋ かれ',meaning:'不論〜或〜、或多或少',example:{ja:'多かれ少なかれ、誰にでも秘密はある。',zh:'多多少少，每個人都有秘密。',highlight:'多かれ少なかれ'},tip:'文言命令形並列，固定說法有「多かれ少なかれ」「遅かれ早かれ」「善かれ悪しかれ」。',quiz:{blank:'多かれ少なかれ',distractors:['多くとも少なくとも','多ければ少なければ','多いといい少ないといい']}},{id:'n1-g223',pattern:'〜すべがない',connection:'動詞辭書形 ＋ すべがない',meaning:'無法〜、無計可施',example:{ja:'嵐で道が塞がれ、外部と連絡をとるすべがない。',zh:'暴風雨堵住了道路，沒有辦法和外界聯絡。',highlight:'連絡をとるすべがない'},tip:'「術がない」表沒有手段，書面語。常見「なすすべがない／もない」。',quiz:{blank:'すべがない',distractors:['までもない','きらいがある','ためしがない']}},{id:'n1-g224',pattern:'〜からある',connection:'數量詞 ＋ からある',meaning:'多達〜、足足有〜',example:{ja:'犯人は五十キロからある荷物を一人で運んだ。',zh:'犯人一個人搬運了足足五十公斤的行李。',highlight:'五十キロからある'},tip:'強調數量之大。重量、長度用からある，價格用からする，人數用からの。',quiz:{blank:'からある',distractors:['からする','たりとも','にわたる']}},{id:'n1-g225',pattern:'〜までになる',connection:'動詞辭書形 ＋ までになる',meaning:'甚至達到〜的程度',example:{ja:'彼は独学で、プロと渡り合えるまでになった。',zh:'他靠自學，甚至達到能與專業人士相抗衡的程度。',highlight:'渡り合えるまでになった'},tip:'表經過努力或變化，終於達到〜的程度，多用「〜までになった」。',quiz:{blank:'までになった',distractors:['までもなかった','ばかりになった','きりになった']}},{id:'n1-g226',pattern:'〜でも何でもない',connection:'名詞／な形容詞語幹 ＋ でも何でもない',meaning:'根本不是〜',example:{ja:'あの男は友人でも何でもない。',zh:'那個男人根本不是我的朋友。',highlight:'友人でも何でもない'},tip:'強烈否定「根本不是〜」。易混：も何もない（談不上〜）、でなくてなんだろう（正是〜）。',quiz:{blank:'でも何でもない',distractors:['でなくてなんだろう','にほかならない','に限ったことではない']}},{id:'n1-g227',pattern:'〜こそ〜が',connection:'名詞 ＋ こそ ＋ 述語（動詞／形容詞） ＋ が',meaning:'雖然〜，但是〜',example:{ja:'彼は口数こそ少ないが、観察力は鋭い。',zh:'他雖然話少，但觀察力很敏銳。',highlight:'口数こそ少ないが'},tip:'「AこそXが、Y」：承認A的一面，但強調另一面。常見「〜こそしないが」「〜こそ少ないが」。',quiz:{blank:'こそ',distractors:['さえ','だに','たりとも']}},{id:'n1-g228',pattern:'〜にあらず',connection:'名詞／動詞連體形（文語） ＋ にあらず',meaning:'不是〜（文言）',example:{ja:'人はパンのみにて生くるにあらず。',zh:'人活著不是單靠麵包。',highlight:'生くるにあらず'},tip:'文言否定「不是〜」，常見「〜にあらず」「この限りにあらず」。易混：べからず（禁止）。',quiz:{blank:'にあらず',distractors:['べからず','にほかならず','に足らず']}},{id:'n1-g229',pattern:'〜に如くはない',connection:'名詞／動詞辭書形 ＋ に如くはない',meaning:'沒有比〜更好的了',example:{ja:'用心するに如くはない。',zh:'沒有比小心謹慎更好的了。',highlight:'用心するに如くはない'},tip:'＝に越したことはない的文言說法「最好是〜」。常見「用心するに如くはない」。',quiz:{blank:'に如くはない',distractors:['に足りない','には及ばない','に堪えない']}},{id:'n1-g230',pattern:'〜とも言うべき',connection:'名詞 ＋ とも言うべき ＋ 名詞',meaning:'可以稱之為〜的',example:{ja:'この事件は、まさに完全犯罪とも言うべきものだった。',zh:'這起案件可說是不折不扣的完美犯罪。',highlight:'完全犯罪とも言うべき'},tip:'「可稱為〜的」，後接名詞或もの。比喻、評價用法，書面語。',quiz:{blank:'とも言うべき',distractors:['ともつかない','ともなく','ともあろう']}},{id:'n1-g231',pattern:'〜に免じて',connection:'名詞 ＋ に免じて',meaning:'看在〜的份上',example:{ja:'今回は君の熱意に免じて許してやろう。',zh:'這次就看在你的熱忱份上原諒你吧。',highlight:'熱意に免じて'},tip:'「看在〜份上（原諒、寬恕）」，後句多為許す、大目に見る。',quiz:{blank:'に免じて',distractors:['にかこつけて','にかまけて','に即して']}},{id:'n1-g232',pattern:'〜にもとる',connection:'名詞 ＋ にもとる',meaning:'違背〜',example:{ja:'それは人の道にもとる行為だ。',zh:'那是違背人道的行為。',highlight:'人の道にもとる'},tip:'「違背〜」，接道德規範類名詞：人の道、信義、武士道。硬い表現。',quiz:{blank:'にもとる',distractors:['に足る','にかなう','にあずかる']}},{id:'n1-g233',pattern:'何なりと',connection:'何なりと ＋ 動詞',meaning:'無論什麼都〜',example:{ja:'ご用がございましたら、何なりとお申し付けください。',zh:'如有任何需要，請儘管吩咐。',highlight:'何なりと'},tip:'「無論什麼都〜」，多用於客氣表示願意服務。何ら須接否定，注意區別。',quiz:{blank:'何なりと',distractors:['何とも','何ら','何やら']}},{id:'n1-g234',pattern:'〜ばかりは',connection:'名詞 ＋ ばかりは',meaning:'唯獨〜（例外）',example:{ja:'今度ばかりは、彼も言い逃れできないだろう。',zh:'唯獨這一次，他也無法搪塞過去了吧。',highlight:'今度ばかりは'},tip:'「唯獨〜（與平常不同）」，常見「今度ばかりは」「こればかりは」，後接無可奈何或特例。',quiz:{blank:'ばかりは',distractors:['ばかりか','たりとも','なりとも']}},{id:'n1-g235',pattern:'〜も何もない',connection:'名詞 ＋ も何もない',meaning:'根本談不上〜',example:{ja:'ここまで証拠が揃えば、言い訳も何もない。',zh:'證據都已經齊全到這種地步，根本沒什麼好辯解的。',highlight:'言い訳も何もない'},tip:'重複對方用詞否定「哪有什麼〜可言」，口語。易混：でも何でもない（根本不是〜）。',quiz:{blank:'も何もない',distractors:['に越したことはない','に限ったことではない','というものだ']}},{id:'n1-g236',pattern:'〜もへったくれもない',connection:'名詞 ＋ もへったくれもない',meaning:'什麼〜不〜的（根本不管）',example:{ja:'緊急事態に、規則もへったくれもない。',zh:'緊急狀況下，哪管什麼規則不規則的。',highlight:'規則もへったくれもない'},tip:'口語，比も何もない更粗俗，表「哪管什麼〜」。不用於正式場合。',quiz:{blank:'もへったくれもない',distractors:['に越したことはない','にほかならない','をおいてない']}},{id:'n1-g237',pattern:'〜もせずに',connection:'動詞ます形／する動詞語幹 ＋ もせずに',meaning:'連〜都沒有就〜',example:{ja:'彼は確認もせずに、書類にサインした。',zh:'他連確認都沒有就在文件上簽了名。',highlight:'確認もせずに'},tip:'「連〜都不做就〜」，帶責難。也接ます形，如「見もせずに」「振り向きもせずに」。',quiz:{blank:'もせずに',distractors:['もさることながら','をおいて','ともなく']}},{id:'n1-g238',pattern:'いかなる〜も',connection:'いかなる ＋ 名詞 ＋ （助詞）＋ も／〜ても',meaning:'任何〜都〜',example:{ja:'いかなる理由があっても、暴力は許されない。',zh:'無論有任何理由，暴力都不被允許。',highlight:'いかなる理由があっても'},tip:'いかなる＋名詞（どんな的書面語）；いかに＋形容詞・動詞（どんなに）。兩者常考區別。',quiz:{blank:'いかなる',distractors:['いかに','いかんせん','いわんや']}},{id:'n1-g239',pattern:'〜ずにおく',connection:'動詞ない形（去ない） ＋ ずにおく',meaning:'故意不〜、暫時不〜',example:{ja:'彼女を傷つけないよう、真相は言わずにおいた。',zh:'為了不傷害她，我刻意沒說出真相。',highlight:'言わずにおいた'},tip:'＝ないでおく，表刻意不做〜（並保持此狀態）。易混：ずにはおかない（一定要〜）。',quiz:{blank:'ずにおいた',distractors:['ずにはおかなかった','ずにはいられなかった','んばかりだった']}},{id:'n1-g240',pattern:'〜の限りを尽くす',connection:'名詞 ＋ の限りを尽くす',meaning:'用盡〜、極盡〜',example:{ja:'犯人は残虐の限りを尽くした。',zh:'犯人極盡殘暴之能事。',highlight:'残虐の限りを尽くした'},tip:'「極盡〜之能事」，如「贅沢の限りを尽くす」「悪の限りを尽くす」。',quiz:{blank:'の限りを尽くした',distractors:['を禁じ得なかった','をものともしなかった','に堪えなかった']}},{id:'n1-g241',pattern:'〜ばかりになっている',connection:'動詞辭書形 ＋ ばかりになっている',meaning:'只差〜（萬事俱備）',example:{ja:'準備は整い、あとは犯人が現れるのを待つばかりになっている。',zh:'準備已經就緒，接下來只剩等犯人出現。',highlight:'待つばかりになっている'},tip:'「只差〜就完成」，表準備就緒，如「出発するばかりになっている」。',quiz:{blank:'ばかりになっている',distractors:['までもない','きらいがある','に忍びない']}},{id:'n1-g242',pattern:'〜と言えなくもない',connection:'普通形 ＋ と言えなくもない',meaning:'也不是不能說〜',example:{ja:'見方によっては、彼も被害者だと言えなくもない。',zh:'換個角度來看，也不是不能說他也是被害者。',highlight:'被害者だと言えなくもない'},tip:'雙重否定表消極肯定「也不是不能說〜」，常與「見方によっては」搭配。',quiz:{blank:'と言えなくもない',distractors:['と言わんばかりだ','といったらない','とばかりに']}},{id:'n1-g243',pattern:'〜をもって〜とする',connection:'名詞 ＋ をもって ＋ 名詞 ＋ とする',meaning:'以〜作為〜',example:{ja:'本書類の提出をもって、正式な申請とする。',zh:'以提交本文件作為正式申請。',highlight:'提出をもって、正式な申請とする'},tip:'「以A作為B」，規章、公告的書面語。也用於「本日をもって終了」（時間點）。',quiz:{blank:'をもって',distractors:['をおいて','をよそに','をめぐって']}},{id:'n1-g244',pattern:'〜ともつかない',connection:'名詞 ＋ とも ＋ 名詞 ＋ ともつかない',meaning:'既不像〜也不像〜、分不清是〜',example:{ja:'彼は笑いとも泣き声ともつかない声をあげた。',zh:'他發出分不清是笑聲還是哭聲的聲音。',highlight:'笑いとも泣き声ともつかない'},tip:'「AともBともつかない」：分不清是A還是B。易混：ともなく（不經意地）。',quiz:{blank:'ともつかない',distractors:['ともなると','ともあろう','ともなしに']}},{id:'n1-g245',pattern:'〜にあずかる',connection:'名詞 ＋ にあずかる',meaning:'蒙受〜、承蒙〜',example:{ja:'本日はお招きにあずかり、光栄に存じます。',zh:'今日承蒙邀請，深感榮幸。',highlight:'お招きにあずかり'},tip:'謙讓表現「承蒙〜」，常見「お招きにあずかる」「お褒めにあずかる」「ご紹介にあずかる」。',quiz:{blank:'にあずかり',distractors:['にかこつけ','に免じ','にもとり']}},{id:'n1-g246',pattern:'〜にかかっては',connection:'名詞 ＋ にかかっては',meaning:'一旦遇上〜（就無可奈何）',example:{ja:'名探偵にかかっては、どんなトリックも見破られてしまう。',zh:'一遇上名偵探，任何詭計都會被識破。',highlight:'名探偵にかかっては'},tip:'＝にかかると，「一碰上〜（就輕易被〜）」，強調對方厲害。',quiz:{blank:'にかかっては',distractors:['にかかわらず','にかこつけて','にひきかえ']}},{id:'n1-g247',pattern:'〜と見るや',connection:'普通形 ＋ と見るや',meaning:'一看到〜就立刻〜',example:{ja:'形勢不利と見るや、彼はすぐに逃げ出した。',zh:'一看情勢不利，他立刻逃走了。',highlight:'形勢不利と見るや'},tip:'「一判斷〜就立刻〜」，書面語，後接迅速行動。與や否や同類。',quiz:{blank:'と見るや',distractors:['と思いきや','といえども','としたところで']}},{id:'n1-g248',pattern:'〜てあまりある',connection:'動詞て形 ＋ あまりある',meaning:'充分可以〜、再怎麼〜也不為過',example:{ja:'遺族の無念は察してあまりある。',zh:'遺族的悲痛與不甘，令人完全能夠體會。',highlight:'察してあまりある'},tip:'常見「察するに余りある」「〜て余りある」，表程度之深足以〜。易混：に余る（超出）。',quiz:{blank:'あまりある',distractors:['やまない','はばからない','もともとだ']}},{id:'n1-g249',pattern:'〜にかけて（誓）',connection:'名詞 ＋ にかけて',meaning:'以〜發誓、賭上〜',example:{ja:'探偵の名にかけて、必ず犯人を捕まえてみせる。',zh:'以偵探之名發誓，我一定會抓到犯人。',highlight:'名にかけて'},tip:'「以〜發誓」，常見「名誉にかけて」「命にかけて」。勿與時間範圍的にかけて混淆。',quiz:{blank:'にかけて',distractors:['にかこつけて','にかかっては','にひきかえ']}},{id:'n1-g250',pattern:'〜ことと存じます',connection:'普通形／名詞の ＋ ことと存じます',meaning:'想必〜（書信、正式場合）',example:{ja:'皆様におかれましては、ますますご健勝のことと存じます。',zh:'想必各位都更加健康安好。',highlight:'ご健勝のことと存じます'},tip:'書信開頭問候語，常見「ご健勝のことと存じます」「お忙しいことと存じます」。',quiz:{blank:'のことと存じます',distractors:['の至りでございます','にあずかります','を賜ります']}},{id:'n1-g251',pattern:'〜を賜る',connection:'名詞 ＋ を賜る',meaning:'承蒙賜予〜（極敬語）',example:{ja:'格別のご配慮を賜り、心より感謝申し上げます。',zh:'承蒙特別關照，衷心感謝。',highlight:'ご配慮を賜り'},tip:'「もらう」的極謙讓語，多見於致詞、書信：「ご指導を賜り」「ご愛顧を賜り」。',quiz:{blank:'を賜り',distractors:['を余儀なくされ','をよそに','にもとり']}},{id:'n1-g252',pattern:'〜を契機として',connection:'名詞 ＋ を契機として',meaning:'以〜為契機',example:{ja:'この事件を契機として、町の防犯体制が見直された。',zh:'以這起事件為契機，鎮上的治安防範體制被重新檢討。',highlight:'事件を契機として'},tip:'＝を機に、をきっかけに，書面語。常考與を皮切りに（以〜為開端接連）區別。',quiz:{blank:'を契機として',distractors:['をよそに','をおいて','をものともせず']}},{id:'n1-g253',pattern:'〜とばかり思っていた',connection:'普通形 ＋ とばかり思っていた',meaning:'一直以為〜（其實不然）',example:{ja:'彼は海外にいるとばかり思っていた。',zh:'我一直以為他人在國外。',highlight:'いるとばかり思っていた'},tip:'「一直以為〜（實際不是）」，常與後句的意外事實呼應。易混：とばかりに（彷彿在說〜）。',quiz:{blank:'とばかり思っていた',distractors:['とばかりに','と思いきや','と見るや']}},{id:'n1-g254',pattern:'〜かと思えば',connection:'動詞た形 ＋ かと思えば',meaning:'才剛〜，馬上又〜',example:{ja:'泣いたかと思えば、急に笑い出した。',zh:'才剛哭完，又突然笑了起來。',highlight:'泣いたかと思えば'},tip:'「剛〜又馬上〜」表變化快，也可表對比「〜かと思えば〜も」。接た形。',quiz:{blank:'かと思えば',distractors:['が早いか','ところで','ばかりに']}},{id:'n1-g255',pattern:'〜まいとして',connection:'動詞辭書形（一段動詞也可接ない形去ない；する→するまい／すまい） ＋ まいとして',meaning:'為了不〜而〜',example:{ja:'彼は声を出すまいとして、口を手で押さえた。',zh:'他為了不發出聲音，用手摀住了嘴。',highlight:'出すまいとして'},tip:'「為了不〜而努力」，表意志否定。易混：（よ）うとして（想要〜）。',quiz:{blank:'まいとして',distractors:['までもなく','ばかりに','ことなしに']}},{id:'n1-g256',pattern:'〜ないものはない',connection:'動詞ない形 ＋ ものはない',meaning:'沒有不〜的、全都〜',example:{ja:'この情報屋に聞けば、わからないものはない。',zh:'只要問這個情報販子，沒有不知道的事。',highlight:'わからないものはない'},tip:'雙重否定「沒有不〜的」＝全都〜。易混：ないものでもない（並非不〜）。',quiz:{blank:'ものはない',distractors:['ではおかない','までもない','ためしがない']}},{id:'n1-g257',pattern:'〜に余る',connection:'名詞 ＋ に余る',meaning:'超出〜、〜不下',example:{ja:'最近の彼の言動は目に余る。',zh:'他最近的言行實在令人看不下去。',highlight:'目に余る'},tip:'慣用：「目に余る」（看不下去）、「手に余る」（處理不了）、「身に余る」（過分）。',quiz:{blank:'に余る',distractors:['に足る','にもとる','に堪える']}},{id:'n1-g258',pattern:'〜ずにはいない',connection:'動詞ない形（去ない） ＋ ずにはいない',meaning:'必然會〜、一定會〜',example:{ja:'彼の不可解な行動は、周囲の疑念を招かずにはいない。',zh:'他那令人費解的行動，必然會招致周遭的懷疑。',highlight:'招かずにはいない'},tip:'＝ずにはおかない，表自然必然結果。主語多為事物。易混：ずにはいられない（忍不住〜）。',quiz:{blank:'ずにはいない',distractors:['ずじまいだ','ずにおく','ずとも']}}]},1933,[]);
__d(function(g,r,i,a,m,e,d){"use strict";Object.defineProperty(e,'__esModule',{value:!0}),Object.defineProperty(e,"N1_READING",{enumerable:!0,get:function(){return n}});const n=[{id:"n1-r01",title:"効率化の果てに失うもの",titleZh:"效率化的盡頭所失去的東西",topic:"社會",paragraphs:[{ja:"現代社会において、「効率」という言葉ほど疑われることなく受け入れられている価値はあるまい。会議は短く、移動は速く、手続きは簡素に。無駄を省くことは、それ自体が善であるかのように語られる。確かに、効率化がもたらした恩恵は計り知れない。かつて数日を要した事務作業が数分で片付き、遠く離れた相手とも瞬時に意思を通わせることができるようになった。しかし、その恩恵を享受しつつも、我々は何かを置き去りにしてきたのではないか。",zh:"在現代社會中，恐怕沒有哪一種價值像「效率」這個詞一樣，未經懷疑就被全盤接受。會議要短、移動要快、手續要簡化。省去浪費，被說得好像本身就是一種善。的確，效率化帶來的恩惠難以估量。過去需要好幾天的行政工作，如今幾分鐘就能完成；即使與遠方的人，也能瞬間溝通意思。然而，在享受這些恩惠的同時，我們是否也把某些東西遺落在身後了呢？"},{ja:"例えば、地域の商店街を思い浮かべてみるといい。店主と客が天気の話を交わし、ついでに近所の噂話に花を咲かせる。効率という観点からすれば、こうしたやり取りは取引に不可欠なものではなく、むしろ時間の浪費にほかならない。だが、そうした一見無駄な会話こそが、人と人とを結びつけ、いざという時に互いを支え合う関係を育んできたのである。セルフレジやネット通販が普及するにつれ、そのような場が失われつつあるのは否めない。",zh:"例如，不妨想想社區的商店街。店主和客人聊聊天氣，順便熱烈地談起鄰里間的八卦。從效率的觀點來看，這樣的交流並非交易所必需，反而只不過是浪費時間。然而，正是這些乍看之下無用的對話，把人與人連結起來，培養出在緊要關頭能彼此扶持的關係。隨著自助結帳和網路購物的普及，這樣的場所正逐漸消失，這是無法否認的。"},{ja:"問題は、効率が手段であるにもかかわらず、いつの間にか目的と化してしまう点にある。本来、効率化とは、生み出された時間や余力を何に充てるかという問いと表裏一体であるはずだ。ところが現実には、節約された時間はさらなる業務で埋め尽くされ、人々は以前にも増して追い立てられている。効率を追求すればするほど余裕がなくなるという逆説は、我々が目的を見失っていることの証左と言えよう。",zh:"問題在於，效率明明是手段，卻不知不覺變成了目的。原本，效率化應該與「要把省下的時間和餘力用在什麼地方」這個問題是一體兩面的。然而現實中，省下的時間又被更多的工作填滿，人們比以前更加被追趕著。越追求效率就越沒有餘裕，這個悖論可說正是我們迷失了目的的證據。"},{ja:"もっとも、効率化そのものを否定するのは早計である。重労働から人を解放し、限られた資源を有効に活用するという点で、その意義は揺るがない。肝要なのは、何を効率化し、何をあえて非効率のまま残すかを見極めることだ。子どもの成長を見守る時間や、病床にある人に寄り添う時間は、短縮すればよいというものではない。むしろ、時間をかけること自体に意味があるものも少なくないのである。",zh:"不過，否定效率化本身是操之過急的。在把人從繁重勞動中解放、有效運用有限資源這一點上，它的意義是不可動搖的。至關重要的是，看清什麼該效率化、什麼該刻意保持不效率。守護孩子成長的時間、陪伴病榻上之人的時間，並不是縮短就好。反而，有不少事情正是「花時間」這件事本身就具有意義。"},{ja:"効率という物差しは便利だが、それですべてを測ろうとすれば、測りきれない価値は視界から消えてしまう。無駄に見えるものの中にこそ、人間らしい営みが宿っていることもある。我々に求められているのは、効率の恩恵を受け入れつつも、それに支配されない知恵を持つことではなかろうか。",zh:"效率這把尺很方便，但若想用它衡量一切，那些量不盡的價值就會從視野中消失。有時，正是在看似無用的事物之中，蘊含著富有人性的生活。我們所需要的，難道不是一邊接受效率的恩惠，一邊擁有不被它支配的智慧嗎？"}],vocab:[{word:"恩恵",reading:"おんけい",meaning:"恩惠、好處"},{word:"享受",reading:"きょうじゅ",meaning:"享受"},{word:"否めない",reading:"いなめない",meaning:"無法否認"},{word:"表裏一体",reading:"ひょうりいったい",meaning:"一體兩面、密不可分"},{word:"証左",reading:"しょうさ",meaning:"證據、證明"},{word:"早計",reading:"そうけい",meaning:"操之過急、輕率"},{word:"肝要",reading:"かんよう",meaning:"至關重要"},{word:"見極める",reading:"みきわめる",meaning:"看清、判斷清楚"}],questions:[{question:"筆者の言う「逆説」とはどのようなことか。",questionZh:"作者所說的「悖論」是指什麼？",options:["効率を追求するほど、人々の余裕がなくなること","効率化によって、店主と客の会話が増えること","効率化が進むほど、仕事の量が減っていくこと","効率を追求しても、恩恵がまったく得られないこと"]},{question:"筆者の主張に最も近いものはどれか。",questionZh:"下列何者最接近作者的主張？",options:["何を効率化し、何を非効率のまま残すかを見極めるべきだ","効率化は人を不幸にするので、すべて否定すべきだ","商店街を守るために、ネット通販を規制すべきだ","効率はあらゆる価値を測ることのできる最良の物差しだ"]}]},{id:"n1-r02",title:"余白が語るもの",titleZh:"留白所訴說的事物",topic:"文化",paragraphs:[{ja:"日本の伝統的な絵画や書を前にすると、描かれていない部分の広さに驚かされることがある。水墨画の多くは、画面の大半を白いまま残し、わずかな筆致で山や霧を表現する。西洋の油彩画が画面の隅々まで色を塗り込めるのとは対照的である。この「余白」は、決して描き忘れや手抜きではない。むしろ、作者が意図的に設けた、意味を持つ空間なのである。",zh:"站在日本傳統繪畫或書法作品前，有時會為未被描繪部分之廣而感到驚訝。許多水墨畫將畫面大半保留空白，只以寥寥筆觸表現山與霧。這與西洋油畫把顏色塗滿畫面每個角落形成對比。這種「留白」絕非忘了畫或偷工減料，反而是作者刻意設置、帶有意義的空間。"},{ja:"余白の働きを一言で言えば、見る者の想像力を呼び込むことにある。すべてを描き尽くした絵は、鑑賞者に解釈の余地をほとんど与えない。それに対して、余白を多く含む作品は、霧の向こうに広がる景色や、画面の外に続く世界を、見る者自身に思い描かせる。つまり、作品は作者一人によって完成するのではなく、鑑賞者との共同作業によって初めて成り立つと言っても過言ではない。",zh:"用一句話來說，留白的作用在於喚起觀者的想像力。把一切都畫盡的畫，幾乎不給欣賞者解讀的餘地。相對地，含有大量留白的作品，會讓觀者自己去描繪霧的另一端展開的景色，以及延續到畫面之外的世界。也就是說，作品並非由作者一人完成，而是要透過與欣賞者的共同合作才得以成立，這麼說也不為過。"},{ja:"こうした美意識は、絵画に限ったものではない。俳句はわずか十七音で一つの情景を切り取るが、語られなかった部分にこそ深い余韻が生まれる。茶室の簡素なしつらえや、能の抑制された所作にも、同様の考え方を見て取ることができる。言葉を尽くさず、飾りを削ぎ落とすことで、かえって豊かな世界が立ち現れるのである。",zh:"這樣的美感意識並不限於繪畫。俳句僅以十七個音節截取一個情景，而正是在未被說出的部分，產生了深遠的餘韻。在茶室簡樸的陳設、能劇克制的舉止中，也能看出同樣的思維。不把話說盡、削去裝飾，反而讓豐富的世界浮現出來。"},{ja:"翻って現代の生活を見渡すと、余白はむしろ忌避されているかのようだ。スマートフォンの画面は情報で埋め尽くされ、わずかな空き時間さえ動画や通知で満たされる。何もない時間や空間に耐えられず、絶えず何かで埋めようとする傾向は、想像する力を少しずつ衰えさせているのではないか。与えられた情報を受け取るばかりでは、自ら思い描く機会は失われる一方である。",zh:"反過來環顧現代生活，留白似乎反而被刻意迴避。手機畫面被資訊填滿，連片刻的空檔都被影片和通知占據。無法忍受空無一物的時間與空間、總想不斷用什麼東西去填補的傾向，是否正一點一點地削弱想像的能力呢？若只是一味接收別人給的資訊，自己去描繪想像的機會只會不斷流失。"},{ja:"余白とは、欠如ではなく可能性である。何も書かれていないからこそ、そこには無限の解釈が許される。先人たちが余白に込めた知恵は、情報に溺れがちな現代人にとって、立ち止まり、自ら考えるための手がかりとなるに違いない。",zh:"留白不是欠缺，而是可能性。正因為什麼都沒寫，那裡才容許無限的詮釋。前人寄託於留白中的智慧，對容易溺於資訊的現代人來說，必定能成為停下腳步、自行思考的線索。"}],vocab:[{word:"余白",reading:"よはく",meaning:"留白、空白處"},{word:"筆致",reading:"ひっち",meaning:"筆觸、筆法"},{word:"余地",reading:"よち",meaning:"餘地"},{word:"過言",reading:"かごん",meaning:"言過其實"},{word:"余韻",reading:"よいん",meaning:"餘韻"},{word:"削ぎ落とす",reading:"そぎおとす",meaning:"削去、去除多餘部分"},{word:"忌避",reading:"きひ",meaning:"忌避、迴避"},{word:"翻って",reading:"ひるがえって",meaning:"反過來（看）"}],questions:[{question:"筆者によれば、水墨画の余白とはどのようなものか。",questionZh:"根據作者，水墨畫的留白是什麼樣的東西？",options:["作者が意図的に設けた、意味を持つ空間","作者が描き忘れてしまった部分","制作の時間が足りなかったために残った部分","西洋の油彩画の影響を受けて生まれた技法"]},{question:"現代の生活について、筆者はどのように考えているか。",questionZh:"關於現代生活，作者怎麼想？",options:["余白を埋めようとする傾向が、想像する力を衰えさせている","情報が多ければ多いほど、想像力は豊かになる","現代人は昔の人以上に余白を大切にしている","スマートフォンは余白の美意識を受け継いでいる"]}]},{id:"n1-r03",title:"うまくいかなかった実験の価値",titleZh:"失敗實驗的價值",topic:"科學",paragraphs:[{ja:"科学の歴史は、しばしば輝かしい発見の連続として語られる。教科書に載るのは、仮説が見事に証明された実験であり、失敗に終わった無数の試みが顧みられることはまずない。しかし、実際の研究の現場では、予想どおりの結果が得られないことの方がはるかに多い。そして、その「うまくいかなかった」結果こそが、科学を支える重要な基盤となっているのである。",zh:"科學史常被描述為一連串輝煌的發現。教科書上刊載的，是假說被漂亮證明的實驗，而以失敗告終的無數嘗試幾乎不會被回顧。然而在實際的研究現場，得不到預期結果的情況要多得多。而正是那些「不順利」的結果，成為支撐科學的重要基礎。"},{ja:"ある薬に効果がないという結果や、ある仮説が成り立たないという結果は、一般に「否定的結果」と呼ばれる。こうした結果は、学術雑誌に掲載されにくい傾向がある。新規性に乏しく、読者の関心を引かないと見なされがちだからだ。その結果、研究者は否定的な結果を発表せずにしまい込み、肯定的な結果ばかりが世に出回ることになる。これは「出版バイアス」と呼ばれ、科学の信頼性を揺るがしかねない問題として認識されている。",zh:"某種藥物沒有效果、某個假說不成立之類的結果，一般稱為「否定性結果」。這類結果往往不易被學術期刊刊登，因為它們常被認為缺乏新穎性、引不起讀者興趣。結果，研究者把否定性結果收起來不發表，世上流通的就只剩肯定性結果。這被稱為「發表偏差」，被視為可能動搖科學可信度的問題。"},{ja:"出版バイアスの弊害は深刻である。例えば、ある治療法について十の研究が行われ、そのうち一つだけが効果を示したとしよう。もし残りの九つが公表されなければ、外部の人間には、その治療法が有効であるかのように映ってしまう。さらに、他の研究者が同じ実験を知らずに繰り返し、貴重な時間と資金を浪費することにもなりかねない。失敗の記録が共有されないことは、科学全体にとっての損失なのである。",zh:"發表偏差的弊害很嚴重。例如，假設針對某種療法進行了十項研究，其中只有一項顯示出效果。如果其餘九項沒有公開，在外界看來，那種療法就好像是有效的。此外，其他研究者也可能在不知情的情況下重複同樣的實驗，浪費寶貴的時間與資金。失敗的紀錄沒有被共享，對整個科學而言是一種損失。"},{ja:"こうした状況を改めるべく、近年では、研究計画を実験の前に登録しておく制度や、否定的結果を専門に扱う雑誌が登場している。結果の如何にかかわらず、適切な手法で行われた研究であれば公表するという考え方が、徐々に浸透しつつある。研究の価値は、結果が華々しいかどうかではなく、問いの立て方と検証の確かさによって測られるべきだという認識が広まっているのだ。",zh:"為了改正這種狀況，近年出現了在實驗前先登記研究計畫的制度，以及專門刊登否定性結果的期刊。「無論結果如何，只要是以適當方法進行的研究就應公開」的想法正逐漸滲透。研究的價值不應以結果是否亮眼來衡量，而應以提問方式與驗證的確實性來衡量，這樣的認識正在擴散。"},{ja:"「何もわからなかった」ということは、裏を返せば「この道は行き止まりだ」とわかったということでもある。地図に行き止まりを書き込むことは、後に続く者が迷わずに済むための大切な仕事である。失敗を恥じるのではなく、知の共有財産として扱う姿勢こそが、科學をより確かなものにしていくに違いない。",zh:"「什麼都沒弄清楚」，反過來說也就是弄清楚了「這條路是死路」。在地圖上標出死路，是讓後來者不必迷路的重要工作。不以失敗為恥，而是將它當作知識的共同財產來對待，這樣的態度必定能讓科學變得更加可靠。"}],vocab:[{word:"仮説",reading:"かせつ",meaning:"假說"},{word:"顧みる",reading:"かえりみる",meaning:"回顧、關注"},{word:"基盤",reading:"きばん",meaning:"基礎、根基"},{word:"乏しい",reading:"とぼしい",meaning:"缺乏、不足"},{word:"弊害",reading:"へいがい",meaning:"弊害、壞處"},{word:"浪費",reading:"ろうひ",meaning:"浪費"},{word:"如何",reading:"いかん",meaning:"如何、怎樣"},{word:"浸透",reading:"しんとう",meaning:"滲透、普及"}],questions:[{question:"「出版バイアス」とはどのような問題か。",questionZh:"「發表偏差」是什麼樣的問題？",options:["肯定的な結果ばかりが発表され、否定的な結果が公表されにくいこと","学術雑誌が否定的な結果だけを好んで掲載すること","研究者が実験の前に研究計画を登録しなければならないこと","教科書が失敗した実験ばかりを紹介していること"]},{question:"筆者が最後の段落で「行き止まり」のたとえを用いたのはなぜか。",questionZh:"作者在最後一段使用「死路」的比喻是為什麼？",options:["否定的な結果も、後の研究者にとって役立つ情報であることを示すため","科学研究にはもはや進むべき道がないことを嘆くため","失敗した研究者の能力不足を批判するため","正確な地図を作ることの難しさを説明するため"]}]},{id:"n1-r04",title:"雪の朝の足跡",titleZh:"雪晨的足跡",topic:"推理",paragraphs:[{ja:"山あいの小さな山荘で事件が起きたのは、一晩中降り続いた雪がようやくやんだ朝のことである。主人の書斎の窓ガラスが割られ、棚に飾られていた古い青磁の壺が消えていた。窓の外の雪の上には、森の方へ向かって一筋の足跡が続いている。たまたま宿泊していた探偵の真壁は、知らせを受けるとすぐに現場へ足を運んだ。",zh:"事件發生在山間一座小山莊，那是下了一整夜的雪終於停下的早晨。主人書房的窗玻璃被打破，擺在架上的一只古老青瓷壺不見了。窗外的雪地上，一行足跡朝著森林方向延伸。碰巧住在這裡的偵探真壁，一接到消息便立刻趕往現場。"},{ja:"管理人の田所は、青ざめた顔でこう証言した。「夜中の一時ごろ、ガラスの割れるような音で目が覚めました。外から誰かが侵入したに違いありません。気味が悪くて、朝まで部屋から出られませんでした」。宿泊客は画家の佐伯と編集者の三浦の二人だけで、どちらも物音には気づかなかったと言う。なお、気象台の記録によれば、この一帯の雪は午前二時ごろにやんでいた。",zh:"管理員田所臉色發青地作證說：「半夜一點左右，我被像是玻璃碎裂的聲音吵醒。一定是有人從外面闖進來。我覺得很害怕，一直到早上都不敢走出房間。」住宿的客人只有畫家佐伯和編輯三浦兩人，兩人都說沒有察覺任何聲響。另外，根據氣象台的紀錄，這一帶的雪在凌晨兩點左右停了。"},{ja:"真壁は窓の下にしゃがみ込み、しばらく雪面を見つめていた。割れたガラスの破片は、窓の外側の雪の上に散らばっている。しかも、どの破片の上にも雪は少しも積もっていなかった。続いて足跡をたどると、それは森の手前の車道で途切れていた。車道の雪は、早朝に田所が日課として除雪したため、きれいに取り除かれている。",zh:"真壁蹲在窗下，盯著雪面看了好一陣子。碎玻璃的碎片散落在窗戶外側的雪地上。而且，每一片碎片上都完全沒有積雪。接著他沿著足跡追查，發現足跡在森林前的車道上中斷了。車道上的雪因為田所清晨例行剷雪，已被清除得乾乾淨淨。"},{ja:"「外から侵入した者が窓を割ったのなら、破片は部屋の内側に落ちるはずです」と真壁は言った。「ところが破片は外にある。つまり、窓は内側から割られたのです。それに、破片の上に雪がないということは、割られたのは雪がやんだ後、すなわち二時以降ということになる」。一同は、はっとして田所の方を振り返った。",zh:"「如果是從外面闖入的人打破窗戶，碎片應該會落在房間內側。」真壁說，「但是碎片卻在外面。也就是說，窗戶是從內側被打破的。而且，碎片上沒有雪，代表窗戶是在雪停之後，也就是兩點以後才被打破的。」眾人猛然一驚，回頭望向田所。"},{ja:"「一時にガラスの音を聞いたというあなたの証言は、事実と食い違っています」と真壁は静かに続けた。「外部の者の仕業に見せかけるために、あなたは内側から窓を割り、森へ向かって足跡をつけた。そして帰りの足跡は、朝の除雪で跡形もなく消したのでしょう」。田所はしばらく黙り込んでいたが、やがて力なくうなずき、壺は物置の奥に隠してあると打ち明けた。",zh:"「你說一點聽到玻璃聲的證詞，與事實不符。」真壁平靜地繼續說，「為了偽裝成外人所為，你從內側打破窗戶，朝森林留下足跡。而回程的足跡，則是藉著早上剷雪消除得無影無蹤吧。」田所沉默了好一陣子，終於無力地點頭，坦白說壺藏在儲藏室深處。"}],vocab:[{word:"山荘",reading:"さんそう",meaning:"山莊"},{word:"証言",reading:"しょうげん",meaning:"證詞、作證"},{word:"破片",reading:"はへん",meaning:"碎片"},{word:"途切れる",reading:"とぎれる",meaning:"中斷"},{word:"除雪",reading:"じょせつ",meaning:"剷雪、除雪"},{word:"食い違う",reading:"くいちがう",meaning:"不一致、有出入"},{word:"見せかける",reading:"みせかける",meaning:"偽裝成、假裝"},{word:"跡形",reading:"あとかた",meaning:"痕跡"}],questions:[{question:"ガラスの破片が窓の外側に落ちていたことから、何がわかるか。",questionZh:"從玻璃碎片落在窗外這件事，可以知道什麼？",options:["窓は内側から割られたこと","窓は外側から割られたこと","犯人は森から山荘にやって来たこと","窓は雪がやむ前に割られたこと"]},{question:"犯人は誰か。また、その決め手となったのは何か。",questionZh:"犯人是誰？決定性的關鍵又是什麼？",options:["田所。破片の上に雪がなく、一時に音を聞いたという証言と矛盾したから","佐伯。物音に気づかなかったと嘘をついていたから","三浦。森へ続く足跡が三浦の靴と一致したから","外部の泥棒。森へ向かう足跡がはっきり残っていたから"]}]},{id:"n1-r05",title:"「待つ」ことを忘れた私たち",titleZh:"忘記「等待」的我們",topic:"生活",paragraphs:[{ja:"かつて人は、実によく待っていた。駅のホームで電車を待ち、郵便受けの前で返事の手紙を待ち、写真屋に預けたフィルムが現像されるのを数日待った。待つことは日常の一部であり、取り立てて苦痛とみなされることもなかった。ところが今日、我々の生活から「待つ」時間は急速に姿を消しつつある。注文した品は翌日に届き、知りたい情報は検索すれば即座に得られる。わずか数分の空き時間でさえ、手元の画面によって瞬く間に埋められてしまうのである。",zh:"從前的人，真的很常等待。在車站月台等電車，在信箱前等回信，把底片交給照相館後要等好幾天才能沖洗出來。等待是日常的一部分，也不特別被視為痛苦。然而今天，「等待」的時間正急速從我們的生活中消失。訂購的東西隔天就送到，想知道的資訊一搜尋就能立刻取得。就連短短幾分鐘的空檔，也會在轉眼之間被手邊的螢幕填滿。"},{ja:"こうした変化を、単に便利になったと喜んでばかりもいられまい。待つ時間を失うにつれ、我々は待つことに耐える力そのものを失いつつあるように思われる。ウェブページの表示が数秒遅れただけで苛立ち、返信が少し遅いだけで相手の気持ちを疑う。待つことへの耐性が低下すればするほど、些細な遅れが大きなストレスとなって跳ね返ってくるという悪循環に陥っているのではないか。",zh:"對於這樣的變化，恐怕不能只是因為變方便而一味高興。隨著失去等待的時間，我們似乎也正逐漸失去忍耐等待的能力本身。網頁只要晚幾秒顯示就焦躁不已，回覆稍微慢一點就懷疑對方的心意。對等待的耐受度越低，微不足道的延遲就越會化為巨大的壓力反彈回來——我們是否正陷入這樣的惡性循環呢？"},{ja:"そもそも、待つ時間とは本当に空白だったのだろうか。電車を待ちながらぼんやりと空を眺めていた時に、ふと考えがまとまったという経験は誰にでもあるはずだ。手紙の返事を待つ間には、相手の顔を思い浮かべ、何と書いてくるだろうかと想像を巡らせた。待つことは、何もしない時間であると同時に、心の中で何かが熟していく時間でもあったのである。",zh:"說到底，等待的時間真的是一片空白嗎？一邊等電車一邊茫然望著天空時，想法突然整理好了——這樣的經驗應該每個人都有。等待回信的期間，人們會想起對方的臉，想像對方會寫些什麼。等待既是什麼都不做的時間，同時也是內心某些東西逐漸成熟的時間。"},{ja:"心理学の分野でも、何かに集中していない状態の脳が、記憶の整理や発想に一役買っていることが指摘されている。だとすれば、空き時間を残らず情報で埋め尽くす今の生活は、自ら考える機会を手放していることにほかならない。退屈を恐れるあまり、退屈がもたらす実りまで捨て去っているとも言えよう。",zh:"在心理學領域也有人指出，處於未專注於任何事物狀態下的大腦，在整理記憶和產生想法上發揮了作用。如此說來，把空檔全部用資訊填滿的現代生活，無異於放棄了自己思考的機會。也可以說，我們因為過度害怕無聊，連無聊所帶來的收穫也一併丟掉了。"},{ja:"もちろん、かつての不便な暮らしに戻れと言うつもりは毛頭ない。ただ、一日のうちわずかでも、画面から目を離して何もせずに過ごす時間を意識的に設けてみてはどうだろうか。待つことを無駄と決めつけず、むしろ贅沢な時間として味わう。そうした心構えこそ、せわしない時代を生き抜くための知恵なのかもしれない。",zh:"當然，我絲毫沒有要大家回到過去不便生活的意思。只是，一天之中哪怕只有一點點，何不試著有意識地安排一段把視線從螢幕移開、什麼都不做的時間呢？不把等待斷定為浪費，反而當作奢侈的時光來品味。這樣的心態，或許正是在忙碌時代中生存下去的智慧。"}],vocab:[{word:"取り立てて",reading:"とりたてて",meaning:"特別地、特意（多接否定）"},{word:"瞬く間",reading:"またたくま",meaning:"轉眼之間"},{word:"苛立つ",reading:"いらだつ",meaning:"焦躁、煩躁"},{word:"些細",reading:"ささい",meaning:"瑣碎、微不足道"},{word:"悪循環",reading:"あくじゅんかん",meaning:"惡性循環"},{word:"一役買う",reading:"ひとやくかう",meaning:"發揮作用、出一份力"},{word:"毛頭",reading:"もうとう",meaning:"絲毫（接否定）"},{word:"心構え",reading:"こころがまえ",meaning:"心態、心理準備"}],questions:[{question:"筆者によれば、かつての「待つ時間」にはどのような意味があったか。",questionZh:"根據作者，過去的「等待時間」具有什麼意義？",options:["何もしない時間であると同時に、心の中で考えが熟していく時間でもあった","人々にとって耐えがたい苦痛であり、早くなくすべき時間であった","情報を集めるための、最も効率のよい時間であった","他人との会話を楽しむためだけに設けられた時間であった"]},{question:"筆者が最後に提案していることは何か。",questionZh:"作者最後提出的建議是什麼？",options:["一日のうちに、画面から離れて何もしない時間を意識的に作ること","便利な道具をすべて手放し、昔の暮らしに戻ること","空き時間には必ず新しい情報を調べるようにすること","返信が遅い相手とは連絡を取らないようにすること"]}]},{id:"n1-r06",title:"「型」に始まり「型」を離れる",titleZh:"始於「型」，終於離開「型」",topic:"文化",paragraphs:[{ja:"茶道や武道、能や歌舞伎といった日本の伝統的な芸道には、「型」と呼ばれる決まった所作の体系が存在する。初心者はまず、師匠の動きを寸分違わずなぞることから稽古を始める。なぜそうするのかという説明はほとんどなされず、弟子はただ黙々と繰り返すのみである。個性や創造性を重んじる現代の教育観からすれば、こうした方法は時代遅れの押し付けに映るかもしれない。",zh:"茶道、武道、能劇、歌舞伎等日本傳統藝道中，存在著被稱為「型」的固定動作體系。初學者首先要從分毫不差地模仿師父的動作開始練習。為什麼要這樣做，幾乎不加說明，弟子只是默默地反覆練習。從重視個性與創造力的現代教育觀來看，這種方法或許看起來像是過時的強迫灌輸。"},{ja:"しかし、型の稽古を単なる模倣と片付けるのは短絡的にすぎる。型とは、先人たちが長い年月をかけて試行錯誤を重ね、無駄を削ぎ落とした末にたどり着いた、いわば知恵の結晶にほかならない。一つ一つの所作には、身体の理にかなった合理性が秘められている。弟子は理屈を頭で理解する前に、まず身体でそれを会得するのである。言葉で説明されないからこそ、自ら気づくまで考え続けることが求められるとも言える。",zh:"然而，把型的練習當作單純的模仿就草草了事，未免太過短視。型可說正是前人花費漫長歲月反覆嘗試錯誤、削去多餘部分之後最終到達的智慧結晶。每一個動作中，都蘊藏著符合身體原理的合理性。弟子在用頭腦理解道理之前，先用身體去領會它。也可以說，正因為沒有用言語說明，才要求弟子持續思考，直到自己察覺為止。"},{ja:"芸道の世界には「守破離」という言葉がある。最初は師の教えを忠実に守り、次にそれを破って他流の良さも取り入れ、最後には型から離れて独自の境地を開くという修行の段階を示したものだ。注目すべきは、型を破ることが最初から否定されているわけではないという点である。むしろ、型を徹底的に身につけた者だけが、真に型を超えることができると考えられているのだ。",zh:"藝道的世界裡有「守破離」這個詞。它表示修行的階段：最初忠實遵守師父的教導，接著打破它、吸收其他流派的優點，最後離開型、開創獨自的境界。值得注意的是，打破型這件事並不是一開始就被否定的。反而是認為，只有徹底掌握型的人，才能真正超越型。"},{ja:"伝統芸能の世界でしばしば引かれる言葉に、「型があるから型破り、型がなければただの形無し」というものがある。基礎を持たない者が奇抜なことをしても、それは独創ではなく単なる無秩序にすぎない。型という土台があってこそ、そこからの逸脱が意味を持ち、新しい表現として人の心を打つのである。",zh:"傳統藝能的世界裡常被引用的一句話是：「有型才能破格，沒有型就只是不成樣子。」沒有基礎的人即使做出奇特的事，那也不是獨創，只不過是單純的無秩序。正因為有型這個基礎，從中的偏離才具有意義，才能作為新的表現打動人心。"},{ja:"この考え方は、芸道に限らず広く学びの場に通じるものがあろう。自由な発想を重視するあまり、基礎の習得を軽んじれば、かえって創造の芽を摘むことになりかねない。遠回りに見える反復こそが、実は最も確かな近道なのかもしれない。型に始まり、型を離れる。その長い道のりを経てこそ、本当の意味での個性が花開くのではなかろうか。",zh:"這種想法不限於藝道，應該也廣泛適用於各種學習場合。若因過度重視自由發想而輕視基礎的習得，反而可能摘除創造的幼芽。看似繞遠路的反覆練習，或許其實才是最確實的捷徑。始於型，終於離開型。正是經過這段漫長的道路，真正意義上的個性才會綻放，不是嗎？"}],vocab:[{word:"寸分違わず",reading:"すんぶんたがわず",meaning:"分毫不差"},{word:"黙々と",reading:"もくもくと",meaning:"默默地"},{word:"試行錯誤",reading:"しこうさくご",meaning:"反覆嘗試錯誤"},{word:"削ぎ落とす",reading:"そぎおとす",meaning:"削去、去除"},{word:"会得",reading:"えとく",meaning:"領會、掌握"},{word:"境地",reading:"きょうち",meaning:"境界、境地"},{word:"奇抜",reading:"きばつ",meaning:"奇特、出奇"},{word:"逸脱",reading:"いつだつ",meaning:"偏離、脫離"}],questions:[{question:"「守破離」の説明として最も適切なものはどれか。",questionZh:"下列何者最適合用來說明「守破離」？",options:["師の教えを守り、それを破り、最後に型から離れて独自の境地を開くという段階","師の教えを最後まで一切変えずに守り続けるべきだという教え","最初から型を破り、自由に表現することを勧める考え方","他流の型をまねることを禁じる、芸道の厳しい規則"]},{question:"筆者の考えに最も近いものはどれか。",questionZh:"下列何者最接近作者的想法？",options:["型を徹底的に身につけることが、真の個性を生む前提となる","型の稽古は時代遅れなので、現代の教育には不要である","基礎がなくても、奇抜なことをすれば独創と認められる","型は言葉で丁寧に説明しなければ、弟子には身につかない"]}]},{id:"n1-r07",title:"「自己責任」という言葉の危うさ",titleZh:"「自我責任」這個詞的危險",topic:"社會",paragraphs:[{ja:"困難に陥った人に対して「それは自己責任だ」という言葉が投げかけられる場面を、近年しばしば目にするようになった。失業、貧困、病気、あるいは災害による被害に至るまで、その対象は際限なく広がりつつある。一見すると、この言葉は自立を促す健全な倫理観の表れのようにも思える。自らの選択の結果を引き受けるのは大人として当然だ、というわけである。",zh:"近年來，經常看到有人對陷入困境的人丟出「那是自我責任」這句話的場面。從失業、貧困、疾病，甚至到災害造成的損失，其對象正無止境地擴大。乍看之下，這句話似乎也是一種促進自立的健全倫理觀的表現。也就是說，承擔自己選擇的結果，是身為大人理所當然的事。"},{ja:"だが、この言葉が持つ説得力の裏には、見過ごせない危うさが潜んでいる。それは、個人の置かれた状況が、あたかもすべて本人の自由な選択の結果であるかのように前提してしまう点だ。どの家庭に生まれ、どの地域で育ち、どのような時代に社会へ出たか。こうした条件は本人の意思ではいかんともしがたいにもかかわらず、その人の人生を大きく左右する。それを捨象して結果だけを本人に帰するのは、公平な見方とは言い難い。",zh:"但是，在這句話所具有的說服力背後，潛藏著不可忽視的危險。那就是它把個人所處的狀況，預設得彷彿全都是本人自由選擇的結果。生在哪個家庭、在哪個地區長大、在什麼樣的時代踏入社會——這些條件儘管是本人的意志無可奈何的，卻大大左右了那個人的人生。忽略這些，只把結果歸咎於本人，很難說是公平的看法。"},{ja:"さらに深刻なのは、この言葉が社会の側の責任を免除する機能を果たしかねないことである。ある人が困窮しているのは本人のせいだと断じてしまえば、制度の不備や構造的な問題に目を向ける必要はなくなる。結果として、本来改善されるべき仕組みが温存され、同じ境遇に陥る人が後を絶たないという事態を招くことになる。",zh:"更嚴重的是，這句話可能發揮免除社會一方責任的功能。一旦斷定某人生活困苦是本人的錯，就不再需要正視制度的缺陷或結構性的問題。結果，本來應該改善的機制被原封不動地保留下來，導致陷入同樣處境的人接連不斷。"},{ja:"加えて、「自己責任」の論理は、言う側自身をも縛ることになる点を忘れてはなるまい。人は誰しも、病や事故、景気の変動といった予期せぬ事態に見舞われる可能性を抱えている。他者の困難を突き放す社会は、自分が困った時にも誰も手を差し伸べてくれない社会にほかならない。助けを求めること自体が恥とされる風潮の中では、人々は孤立を深め、問題はいっそう見えにくくなるだろう。",zh:"此外，不能忘記「自我責任」的邏輯也會束縛說出這句話的人自己。任何人都有可能遭遇疾病、事故、景氣變動等意料之外的事態。一個對他人的困難置之不理的社會，正是一個在自己遇到困難時也沒有人會伸出援手的社會。在連求助本身都被視為可恥的風氣中，人們會越來越孤立，問題也會變得更加難以看見。"},{ja:"もちろん、個人の努力や責任感の意義を否定するわけではない。問われているのは、その言葉を誰が、どのような場面で、誰に対して用いるかである。他者を裁く道具としてではなく、互いの事情に想像力を働かせることから出発する社会のあり方を、今一度考え直す必要があるのではないか。",zh:"當然，這並不是否定個人努力與責任感的意義。真正被質問的是：這句話是由誰、在什麼場合、對誰使用的。我們是否需要再一次重新思考一種社會的樣貌——不是把這句話當作審判他人的工具，而是從對彼此處境發揮想像力出發？"}],vocab:[{word:"際限なく",reading:"さいげんなく",meaning:"無止境地"},{word:"潜む",reading:"ひそむ",meaning:"潛藏"},{word:"捨象",reading:"しゃしょう",meaning:"捨棄（不考慮）、抽離"},{word:"困窮",reading:"こんきゅう",meaning:"窮困、生活困苦"},{word:"温存",reading:"おんぞん",meaning:"保留、維持原狀"},{word:"後を絶たない",reading:"あとをたたない",meaning:"接連不斷"},{word:"見舞われる",reading:"みまわれる",meaning:"遭受、遇到（災難等）"},{word:"風潮",reading:"ふうちょう",meaning:"風氣、潮流"}],questions:[{question:"筆者が「自己責任」という言葉の危うさとして第一に挙げているものは何か。",questionZh:"作者首先舉出「自我責任」一詞的危險是什麼？",options:["本人の意思では変えられない条件を無視し、結果をすべて本人に帰してしまうこと","人々が自立しすぎて、互いに助け合わなくなること","大人が自らの選択の結果を引き受けなくなること","災害の被害者だけが特別に守られるようになること"]},{question:"筆者によれば、この言葉が社会の側にもたらす問題は何か。",questionZh:"根據作者，這句話對社會一方帶來的問題是什麼？",options:["制度の不備が見過ごされ、改善されないまま残ってしまうこと","社会の制度が急激に変わり、人々が混乱すること","困窮している人がすぐに助けを求めるようになること","景気の変動が大きくなり、失業者が増えること"]}]},{id:"n1-r08",title:"人の手が育む自然",titleZh:"由人手培育的自然",topic:"自然",paragraphs:[{ja:"自然保護と聞けば、多くの人は人間の手が一切及ばない原生の森を守ることを思い浮かべるだろう。人の介入を排し、自然をあるがままに委ねることこそが保護である、という考え方だ。ところが、日本各地に見られる「里山」は、その常識に一石を投じる存在である。",zh:"一聽到自然保護，很多人會想到守護人類完全觸及不到的原始森林吧。也就是認為排除人的介入、讓自然保持原貌，才是保護。然而，日本各地可見的「里山」，卻對這個常識投下了一顆石子。"},{ja:"里山とは、集落の周辺に広がる雑木林や草地、田畑、ため池などが一体となった環境を指す。かつて人々は、薪や炭を得るために定期的に木を伐り、落ち葉をかき集めて肥料とし、草を刈って家畜の餌とした。こうした営みによって、林の中には適度に光が差し込み、背の低い草花が育つ余地が生まれた。明るい林床に咲くカタクリや、草地を舞うさまざまな蝶は、まさに人の暮らしと共にあった生き物なのである。",zh:"所謂里山，是指聚落周邊延伸的雜木林、草地、田地、蓄水池等融為一體的環境。過去人們為了取得柴薪和木炭而定期伐木，把落葉收集起來當作肥料，割草當作家畜的飼料。透過這樣的生活作業，林中有適度的陽光照進來，產生了讓矮小花草生長的空間。在明亮林床上綻放的豬牙花、在草地上飛舞的各種蝴蝶，正是與人類生活共存的生物。"},{ja:"皮肉なことに、戦後の燃料革命と農村の過疎化によって人の手が入らなくなると、里山の生態系はむしろ貧弱になっていった。放置された雑木林は常緑樹や竹に覆われて薄暗くなり、光を好む植物は姿を消した。手入れされなくなったため池や水田も土砂や草に埋もれ、そこを住みかとしていたメダカやカエルの姿も見られなくなった。それに依存していた昆虫や鳥も、次第に数を減らしつつある。人が手を引けば自然が豊かになるという単純な図式は、ここでは成り立たないのである。",zh:"諷刺的是，戰後由於燃料革命和農村人口外流，人手不再介入之後，里山的生態系反而變得貧乏。被棄置的雜木林被常綠樹和竹子覆蓋而變得昏暗，喜歡陽光的植物消失了。無人照料的蓄水池和水田也被泥沙和雜草掩埋，以那裡為棲所的青鱂魚和青蛙也不見蹤影了。依賴這些植物的昆蟲和鳥類，數量也逐漸減少。「人一抽手，自然就會變豐富」這種單純的圖式，在這裡並不成立。"},{ja:"この事実は、人間と自然を対立するものとして捉える見方そのものを問い直すよう迫っている。人間を自然の外部から脅かす存在とのみ見なすのではなく、生態系の一員として、適切な関わり方を模索するべきだという考え方である。現在、各地で市民による雑木林の手入れや草刈りが行われているのも、そうした認識の広がりを示すものと言えよう。",zh:"這個事實迫使我們重新審視把人類與自然視為對立事物的看法本身。也就是說，不應只把人類看作從外部威脅自然的存在，而應作為生態系的一員，摸索適當的相處方式。現在各地有市民進行雜木林的整理和割草，也可說顯示了這種認識的擴展。"},{ja:"もっとも、過去の営みをそのまま復元すればよいというわけではない。かつての里山は生活の必要に迫られて維持されていたものであり、その動機が失われた今、誰がどのような形で担い手となるのかという難題が残されている。自然とどう付き合うかという問いは、結局のところ、我々がどのような暮らしを選ぶのかという問いと切り離せないのである。",zh:"不過，並不是把過去的生活作業原封不動地復原就好。過去的里山是因生活所需而被維持的，如今這個動機已經消失，仍留下「由誰、以什麼形式來承擔」這個難題。如何與自然相處這個問題，歸根究柢，與我們選擇過什麼樣的生活這個問題是分不開的。"}],vocab:[{word:"一石を投じる",reading:"いっせきをとうじる",meaning:"投下一顆石子、引起波瀾或問題意識"},{word:"営み",reading:"いとなみ",meaning:"生活作業、活動"},{word:"余地",reading:"よち",meaning:"餘地、空間"},{word:"過疎化",reading:"かそか",meaning:"人口外流、人口稀少化"},{word:"貧弱",reading:"ひんじゃく",meaning:"貧乏、薄弱"},{word:"模索",reading:"もさく",meaning:"摸索"},{word:"担い手",reading:"にないて",meaning:"承擔者、主力"}],questions:[{question:"戦後、里山の生態系が貧弱になったのはなぜか。",questionZh:"戰後里山的生態系為什麼變得貧乏？",options:["人の手が入らなくなり、林が暗くなって光を好む植物が消えたから","人々が木を伐りすぎて、林そのものがなくなってしまったから","落ち葉を肥料にしすぎて、土地がやせてしまったから","市民による草刈りが行われ、草花が刈り取られたから"]},{question:"筆者の考えに最も近いものはどれか。",questionZh:"下列何者最接近作者的想法？",options:["人間を生態系の一員として捉え、自然との適切な関わり方を探るべきだ","自然を守るには、人間の介入を一切排除するのが最善だ","昔の里山の暮らしをそのまま復元すれば、問題はすべて解決する","里山は人工的な環境なので、保護する価値はない"]}]},{id:"n1-r09",title:"相関は因果にあらず",titleZh:"相關並非因果",topic:"科學",paragraphs:[{ja:"「朝食を毎日食べる子どもほど学力が高い」。こうした調査結果が報じられると、我々はつい「朝食を食べれば成績が上がる」と受け取ってしまいがちである。しかし、二つの事柄が同時に見られるという「相関」と、一方が他方を引き起こすという「因果」とは、本来まったく別の概念である。この区別を怠ると、データは真実を照らすどころか、かえって誤った結論へと人を導きかねない。",zh:"「每天吃早餐的孩子學力越高。」這樣的調查結果一被報導，我們往往就會不自覺地理解成「吃早餐成績就會變好」。然而，兩件事同時出現的「相關」，和一方引起另一方的「因果」，本來是完全不同的概念。若疏於區分，數據非但不能照亮真相，反而可能把人引向錯誤的結論。"},{ja:"相関が因果を意味しない理由の一つに、「第三の要因」の存在が挙げられる。先の例で言えば、毎朝そろって食卓を囲むことのできる家庭は、生活のリズムが整っていたり、教育への関心が高かったりする傾向があるかもしれない。だとすれば、学力を左右しているのは朝食そのものではなく、背後にある家庭環境だという可能性も否定できない。このような見かけ上の関係は「疑似相関」と呼ばれる。",zh:"相關不代表因果的理由之一，可以舉出「第三因素」的存在。以前面的例子來說，每天早上能全家一起圍坐餐桌的家庭，或許有生活規律、對教育關心度高的傾向。如此一來，左右學力的就不是早餐本身，而可能是背後的家庭環境，這種可能性也無法否定。這種表面上的關係被稱為「虛假相關」。"},{ja:"また、因果の向きが逆である場合もある。ある地域で警察官の数が多いほど犯罪件数も多いというデータがあったとしても、警察官が犯罪を増やしているとは考えにくい。むしろ、犯罪が多い地域だからこそ警察官が多く配置されていると見るのが妥当であろう。原因と結果を取り違えれば、対策はまったく的外れなものになってしまう。",zh:"此外，也有因果方向相反的情況。即使有數據顯示某地區警察越多犯罪件數也越多，也很難認為是警察讓犯罪增加。反而，認為正因為是犯罪多的地區才配置了較多警察，才是妥當的看法。若把原因和結果弄反，對策就會完全偏離重點。"},{ja:"では、因果関係を確かめるにはどうすればよいのか。科学の世界で重視されるのが、対象を無作為に二つの集団に分け、一方にだけ特定の処置を施して結果を比較する「ランダム化比較試験」である。無作為に分けることで、第三の要因の影響が両集団に均等に散らばり、処置の効果のみを取り出すことが可能になるのだ。もっとも、倫理的あるいは費用的な制約から、こうした実験が常に行えるわけではない。",zh:"那麼，要確認因果關係該怎麼做呢？科學界所重視的是「隨機對照試驗」：把對象隨機分成兩組，只對其中一組施加特定處理，再比較結果。透過隨機分組，第三因素的影響會平均分散到兩組，便能只抽取出處理的效果。不過，由於倫理或費用上的限制，這樣的實驗並非總是能夠進行。"},{ja:"数字やグラフは客観的な装いをまとっているがゆえに、人を説得する強い力を持つ。だからこそ、受け手には「本当にそれが原因なのか」と立ち止まって問う姿勢が求められる。情報があふれる現代において、相関と因果を見分ける力は、専門家のみならず市民一人一人に欠かせない素養と言っても過言ではない。",zh:"數字和圖表正因為披著客觀的外衣，才具有說服人的強大力量。正因如此，接收者需要有停下腳步、問一句「那真的是原因嗎」的態度。在資訊氾濫的現代，說分辨相關與因果的能力不只是專家，而是每一位市民不可或缺的素養，也不為過。"}],vocab:[{word:"怠る",reading:"おこたる",meaning:"疏忽、怠慢"},{word:"疑似相関",reading:"ぎじそうかん",meaning:"虛假相關"},{word:"妥当",reading:"だとう",meaning:"妥當、合理"},{word:"的外れ",reading:"まとはずれ",meaning:"離題、沒抓到重點"},{word:"無作為",reading:"むさくい",meaning:"隨機、不刻意選擇"},{word:"施す",reading:"ほどこす",meaning:"施加、實施"},{word:"素養",reading:"そよう",meaning:"素養"},{word:"過言",reading:"かごん",meaning:"言過其實"}],questions:[{question:"警察官と犯罪件数の例は、何を説明するために挙げられているか。",questionZh:"警察與犯罪件數的例子，是為了說明什麼而舉出的？",options:["原因と結果の向きが逆である場合があること","警察官が増えると犯罪も増えるということ","第三の要因が学力を左右しているということ","ランダム化比較試験が常に行えるということ"]},{question:"ランダム化比較試験で対象を無作為に分けるのはなぜか。",questionZh:"隨機對照試驗中為什麼要把對象隨機分組？",options:["第三の要因の影響を両集団に均等にし、処置の効果だけを取り出すため","実験にかかる費用をできるだけ少なくするため","倫理的な問題をすべて避けることができるため","どちらの集団にも同じ処置を施すため"]}]},{id:"n1-r10",title:"「雑草」という名の草はない",titleZh:"沒有叫做「雜草」的草",topic:"自然",paragraphs:[{ja:"道端やアスファルトの割れ目、手入れの行き届かない庭の片隅。人が望まない場所に生えてくる草を、我々は一括りに「雑草」と呼ぶ。しかし、植物学の上では雑草という名の種は存在しない。ある植物が雑草と呼ばれるかどうかは、その植物自体の性質ではなく、人間の都合によって決まるのである。畑に生えれば忌み嫌われる草も、野原に咲けば可憐な野の花として愛でられることがある。",zh:"路邊、柏油路的裂縫、疏於照料的庭院角落。我們把長在人們不希望之處的草，一概稱為「雜草」。然而，在植物學上並不存在名為雜草的物種。某種植物是否被稱為雜草，並非由植物本身的性質決定，而是由人類的方便來決定。長在田裡會被厭惡的草，開在原野上時也可能被當作可愛的野花而受到欣賞。"},{ja:"もっとも、雑草と呼ばれる植物たちには、確かに共通する特徴がある。その多くは、荒れた土地や頻繁に踏みつけられる場所を生き抜く術に長けている。実は、雑草の多くは他の植物との光や養分の奪い合いには決して強くない。深い森の中では、背の高い木々に光を遮られ、たちまち駆逐されてしまうのだ。彼らはあえて他の植物が生きられない過酷な環境を選び、そこを自らの居場所としてきたのである。",zh:"不過，被稱為雜草的植物們確實有共同的特徵。它們大多擅長在荒地或經常被踩踏的地方生存下去。其實，大多數雜草在與其他植物爭奪陽光和養分方面絕對稱不上強。在深林中，它們會被高大的樹木遮住陽光，很快就被驅逐。它們刻意選擇其他植物無法生存的嚴苛環境，並把那裡當作自己的棲身之處。"},{ja:"例えば、道端でよく見かけるオオバコは、人や車に踏まれることでむしろ分布を広げてきた。その種子は水に濡れると粘り気を帯び、靴底やタイヤに付着して遠くへ運ばれる。踏まれることを耐え忍ぶだけでなく、それを利用しているとさえ言える。逆境を逆手に取るこのしたたかさこそ、雑草の真骨頂であろう。",zh:"例如路邊常見的車前草，反而是靠著被人和車踩過而擴大了分布範圍。它的種子一沾到水就會帶有黏性，附著在鞋底或輪胎上被帶到遠方。甚至可以說，它不只是忍受被踩，還利用了這一點。這種將逆境反過來加以利用的頑強，正是雜草的真本事吧。"},{ja:"また、雑草は刈り取られてもすぐに再生する。地下に栄養を蓄えた根や茎を残していたり、種子が何年も土の中で休眠し、条件が整うのを待ち続けたりするからだ。一度にすべての種子が芽を出さないのも、一斉に全滅する危険を避けるための戦略だと考えられている。草刈りをした直後に、かえって別の草が勢いよく伸びてくるのも、光を独占していた草がいなくなった隙を、土の中の種子が逃さず突いた結果なのである。",zh:"此外，雜草即使被割除也會馬上再生。這是因為它們在地下留有儲存養分的根和莖，或者種子在土中休眠多年，持續等待條件齊備。所有種子不會一次全部發芽，也被認為是為了避免一起全滅的危險而採取的策略。剛割完草之後，反而有別的草猛然長出來，也是土中的種子不放過原本獨占陽光的草消失的空檔，趁虛而入的結果。"},{ja:"「雑草のようにたくましく」という言い回しは、しばしば根性論と結びつけて語られる。しかし、彼らの生き方の本質は、むやみに競うことではなく、自分が勝てる場所を見極めることにあるのではないか。強者と正面からぶつかるのではなく、独自の居場所を見出す。雑草の生存戦略は、我々人間にとっても示唆に富むものと言えよう。",zh:"「像雜草一樣堅強」這種說法，常常和毅力論連結在一起。然而，它們生存方式的本質，難道不是在於看清自己能夠獲勝的地方，而不是盲目地競爭嗎？不與強者正面衝突，而是找出獨自的棲身之處。雜草的生存策略，對我們人類而言也可說充滿啟示。"}],vocab:[{word:"忌み嫌う",reading:"いみきらう",meaning:"厭惡、嫌棄"},{word:"愛でる",reading:"めでる",meaning:"欣賞、喜愛"},{word:"長ける",reading:"たける",meaning:"擅長、精通"},{word:"駆逐",reading:"くちく",meaning:"驅逐、排擠掉"},{word:"逆手に取る",reading:"さかてにとる",meaning:"將計就計、反過來利用"},{word:"真骨頂",reading:"しんこっちょう",meaning:"真本事、真正價值"},{word:"示唆",reading:"しさ",meaning:"啟示、暗示"}],questions:[{question:"筆者によれば、雑草と呼ばれる植物の多くはどのような性質を持っているか。",questionZh:"根據作者，被稱為雜草的植物大多具有什麼樣的性質？",options:["他の植物との競争には強くないが、過酷な環境を生き抜く術に長けている","どんな環境でも、他の植物との光の奪い合いに必ず勝つ","深い森の中でしか育つことができない","人間に踏まれると、すぐに枯れてしまう"]},{question:"オオバコの例から分かることは何か。",questionZh:"從車前草的例子可以知道什麼？",options:["踏まれるという逆境を利用して、分布を広げてきたこと","人間に大切に育てられて、各地に広まったこと","種子が乾燥すると、風に乗って遠くへ飛ぶこと","すべての種子が一度に芽を出して、一気に増えること"]}]},{id:"n1-r11",title:"雨の日の古書店",titleZh:"雨天的舊書店",topic:"推理",paragraphs:[{ja:"神保町の裏通りに、桐生という老人が営む小さな古書店がある。その日は朝から冷たい雨が降り続き、午後になっても客足はまばらであった。桐生が近くの蕎麦屋で昼食をとる一時間ほどの間、店番は孫娘の沙織に任せていた。夕刻、閉店の支度をしていた桐生は、レジ横のガラスケースに収めてあった明治期の稀覯本が、箱だけを残して消えていることに気づいた。ケースの鍵は、うっかり掛け忘れられていたのである。",zh:"神保町的後街上，有一間由名叫桐生的老人經營的小舊書店。那天從早上就一直下著冰冷的雨，到了下午客人仍然稀稀落落。桐生在附近的蕎麥麵店吃午餐的約一個小時期間，把看店的工作交給了孫女沙織。傍晚，正在準備打烊的桐生發現，收在收銀台旁玻璃櫃中的明治時期珍本，只留下了盒子，書本身卻不見了。玻璃櫃的鎖不小心忘了鎖上。"},{ja:"沙織によれば、その一時間の間に店を訪れた客は三人だけだという。一人目は近所の大学に通う学生で、入り口の傘立てに黒い傘を差して、文学の棚を長いこと眺めていた。二人目は和服姿の年配の婦人で、店の前にタクシーを止めさせ、運転手を待たせたまま数分で詩集を一冊買っていった。三人目は灰色のコートを着た中年の男で、しばらく店内を歩き回ったあと、何も買わずに出て行った。",zh:"據沙織說，那一個小時內來店裡的客人只有三位。第一位是在附近大學念書的學生，他把黑傘插在入口的傘架上，在文學書架前看了很久。第二位是穿著和服的年長婦人，她讓計程車停在店門口，讓司機等著，幾分鐘內就買了一本詩集離開。第三位是穿著灰色大衣的中年男子，他在店內走來走去一陣子之後，什麼也沒買就離開了。"},{ja:"翌日、桐生は沙織の記憶を頼りに三人を探し当て、それぞれに話を聞いた。学生は「傘を立てたあとは、ずっと文学の棚の前にいました」と言い、婦人は「車を待たせていましたから、長居などしておりません」と答えた。中年の男は落ち着き払った様子で、「駅から傘を差して歩いてきたので、雨には濡れていませんよ。ケースなど見てもいない」と語った。",zh:"隔天，桐生憑著沙織的記憶找到了這三人，分別向他們問話。學生說：「把傘插好之後，我就一直待在文學書架前。」婦人回答：「我讓車子在外面等著，所以根本沒有久留。」中年男子則一副泰然自若的樣子說：「我是從車站撐著傘走過來的，所以沒有被雨淋濕。我連櫃子都沒看。」"},{ja:"店に戻った桐生は、残された空箱をあらためて手に取った。本を包んでいた薄紙の上には、小さな水の染みがいくつも点々と残っている。濡れた指で触れた跡に違いない。「沙織、あの日、傘立てには何本の傘があった」と桐生は尋ねた。沙織は少し考えてから答えた。「一本だけよ。学生さんの黒い傘。そういえば、あの灰色のコートの人は手ぶらだったけど、肩のところが雨でずいぶん色が変わっていたわ」",zh:"回到店裡的桐生，再次拿起留下來的空盒子。包著書的薄紙上，殘留著好幾處點點的小水漬。這一定是用濕手指碰過的痕跡。「沙織，那天傘架上有幾把傘？」桐生問道。沙織想了一下回答：「只有一把喔，是那位學生的黑傘。這麼說來，那位穿灰色大衣的人兩手空空，可是肩膀的地方被雨淋得顏色都變深了。」"},{ja:"桐生は静かにうなずいた。「傘を差してきたと言うのなら、その傘はどこにあったのか。傘立てにもなく、手にも持っていなかった。あの男は傘など差さずに、雨の中を歩いてきたのだ。濡れた手のままケースを開けたからこそ、薄紙に染みが残った。学生は傘を差していたし、婦人は車で店先に乗りつけた。手を濡らしていたのは、あの男だけだよ」。嘘はたった一つでも、真実を照らし出すには十分なのである。",zh:"桐生靜靜地點了點頭。「如果他說是撐傘來的，那把傘在哪裡？既不在傘架上，手上也沒拿著。那個男人根本沒撐傘，是在雨中走過來的。正因為他用濕手打開了櫃子，薄紙上才留下了水漬。學生撐著傘，婦人是搭車直接到店門口的。手是濕的，只有那個男人而已。」謊言即使只有一個，也足以照出真相。"}],vocab:[{word:"営む",reading:"いとなむ",meaning:"經營"},{word:"客足",reading:"きゃくあし",meaning:"客流、來客情況"},{word:"稀覯本",reading:"きこうぼん",meaning:"珍本、罕見的書"},{word:"長居",reading:"ながい",meaning:"久留、久坐"},{word:"落ち着き払う",reading:"おちつきはらう",meaning:"泰然自若、十分沉著"},{word:"手ぶら",reading:"てぶら",meaning:"兩手空空"},{word:"乗りつける",reading:"のりつける",meaning:"（搭車）直接到達"}],questions:[{question:"和服姿の婦人が店に長居しなかったのはなぜか。",questionZh:"穿和服的婦人為什麼沒有在店裡久留？",options:["タクシーの運転手を店の前で待たせていたから","雨に濡れて、早く家に帰りたかったから","欲しかった詩集が店になかったから","店番の沙織と話が合わなかったから"]},{question:"桐生が真相に気づく決め手となった手がかりはどれか。",questionZh:"讓桐生察覺真相的關鍵線索是哪一個？",options:["傘立てには学生の傘一本しかなく、灰色のコートの男は手ぶらなのに肩が濡れていたこと","学生が文学の棚の前に長い時間立っていたこと","婦人が数分で詩集を一冊買っていったこと","ガラスケースの鍵が壊されていたこと"]},{question:"稀覯本を持ち去ったのは誰か。",questionZh:"拿走珍本的人是誰？",options:["灰色のコートを着た中年の男","近所の大学に通う学生","和服姿の年配の婦人","孫娘の沙織"]}]},{id:"n1-r12",title:"打ち上げられなかった花火",titleZh:"沒有施放的煙火",topic:"推理",paragraphs:[{ja:"海沿いの町にある小さな美術館で、収蔵庫に保管されていた江戸期の掛け軸が盗まれたのは、八月十日の夜のことであった。翌朝、出勤した職員が収蔵庫の扉の錠が開いているのを発見し、警察に通報した。収蔵庫の鍵を扱えるのは、館長を除けば三人しかいない。県警の刑事である真柴は、その三人から事件当夜の行動を聞くことにした。",zh:"海邊小鎮的一間小美術館裡，收藏庫中保管的江戶時期掛軸被偷，是在八月十日晚上的事。隔天早上，來上班的職員發現收藏庫的門鎖開著，便報了警。除了館長之外，能使用收藏庫鑰匙的只有三個人。縣警的刑警真柴，決定向這三人詢問案發當晚的行動。"},{ja:"一人目の警備員の大野は、その夜、館内で勤務していた。巡回の記録は一時間ごとに機械に残されており、どの時刻にも空白は見当たらない。二人目の学芸員の森下は、十日から二日間、遠方の都市で開かれた学会に出席しており、ホテルの宿泊記録や講演の録画がそれを裏付けていた。",zh:"第一位是警衛大野，那天晚上他在館內值勤。巡邏紀錄每小時都留存在機器裡，任何時段都找不到空白。第二位是學藝員森下，他從十日起連續兩天出席在遠方城市舉辦的學會，飯店的住宿紀錄和演講錄影都證實了這一點。"},{ja:"三人目は、修復を担当する外部の技術者、篠田である。篠田は少し照れたような笑みを浮かべて言った。「あの晩は、河原で花火を見ていました。毎年の楽しみなんですよ。九時ごろから一時間ほど、最後の金色の大輪まで見届けて帰りました。あいにく携帯の電池が切れていて、写真は一枚も残っていませんが」。花火の様子を語る篠田の口ぶりは淀みなく、その光景が目に浮かぶようであった。真柴は黙って手帳に書き留めながら、どこか引っかかるものを感じていた。",zh:"第三位是負責修復的外部技師篠田。篠田帶著有點靦腆的笑容說：「那天晚上我在河灘看煙火。那是我每年的樂趣。從九點左右看了大約一小時，一直看到最後那朵金色的大煙火才回家。不巧手機沒電了，一張照片也沒留下。」篠田描述煙火情景的語氣流暢無礙，那光景彷彿浮現在眼前。真柴一邊默默記在筆記本上，一邊隱約覺得有什麼地方不太對勁。"},{ja:"真柴は礼を述べて篠田と別れると、その足で町の観光協会に向かった。窓口の職員は、壁に貼られたポスターを指さして言った。「今年の花火大会ですか。本来は十日の予定でしたが、あの日は台風の影響で夕方から風が強まりましてね。安全のため、翌日の十一日に延期したんです」。真柴が念のために確かめると、十日の夜は河原に人影もなく、花火の音を聞いたという住民も一人もいなかった。",zh:"真柴向篠田道謝告別後，直接前往鎮上的觀光協會。窗口的職員指著貼在牆上的海報說：「您是說今年的煙火大會嗎？原本預定在十日舉行，但那天受颱風影響，從傍晚開始風就變強了。為了安全起見，延到隔天十一日舉行了。」真柴為了慎重起見加以確認，十日晚上河灘上連個人影都沒有，也沒有任何一位居民聽到煙火的聲音。"},{ja:"真柴の頭の中で、すべてがつながった。篠田が見たという花火は、十日の夜には一発も打ち上げられていなかったのである。彼はおそらく、翌日の花火大会を実際に見て、その記憶をもとに偽りのアリバイを組み立てたのだろう。警備員の記録にも、学芸員の出張にも、ほころびは見当たらない。巧みに作られた嘘ほど、思わぬ一つの事実によって、あっけなく崩れ去るものである。",zh:"真柴腦中的一切都串連起來了。篠田說他看到的煙火，在十日晚上一發也沒有施放。他恐怕是實際看了隔天的煙火大會，再根據那段記憶編造了假的不在場證明吧。警衛的紀錄也好，學藝員的出差也好，都找不到破綻。越是精心編造的謊言，越會因為一個意想不到的事實而輕易崩塌。"}],vocab:[{word:"裏付ける",reading:"うらづける",meaning:"證實、提供證據"},{word:"見届ける",reading:"みとどける",meaning:"看到最後、親眼確認"},{word:"あいにく",reading:"あいにく",meaning:"不巧、偏偏"},{word:"淀みない",reading:"よどみない",meaning:"流暢、毫不停頓"},{word:"ほころび",reading:"ほころび",meaning:"破綻、漏洞"},{word:"巧み",reading:"たくみ",meaning:"巧妙"},{word:"崩れ去る",reading:"くずれさる",meaning:"崩塌、瓦解"}],questions:[{question:"学芸員の森下の行動を裏付けたものは何か。",questionZh:"證實學藝員森下行動的是什麼？",options:["ホテルの宿泊記録や講演の録画","一時間ごとに機械に残された巡回の記録","河原で撮影された花火の写真","観光協会に貼られたポスター"]},{question:"篠田の証言のどこに矛盾があったか。",questionZh:"篠田的證詞哪裡有矛盾？",options:["花火大会は十一日に延期され、十日の夜には花火が打ち上げられていなかったこと","携帯の電池が切れていたのに、写真を何枚も撮っていたこと","河原ではなく、美術館の屋上から花火を見ていたこと","九時ごろにはすでに花火大会が終わっていたこと"]},{question:"掛け軸を盗んだ犯人として最も疑わしいのは誰か。",questionZh:"最可能是偷走掛軸的犯人是誰？",options:["修復を担当する技術者の篠田","警備員の大野","学芸員の森下","観光協会の職員"]}]},{id:"n1-r13",title:"「ひとりの時間」を取り戻す",titleZh:"找回「獨處的時間」",topic:"生活",paragraphs:[{ja:"スマートフォンが手放せなくなってから、私たちは一人でいながら一人ではなくなった。電車の中でも、寝る前の数分間でも、指先一つで誰かの近況を知り、自分の近況を発信することができる。孤独を感じる隙もないほど、常に誰かとつながっている状態である。一見すれば、寂しさから解放された幸福な時代のように思える。しかし、そうした絶え間ないつながりの中で、私たちは「ひとりの時間」を知らず知らずのうちに手放してはいないだろうか。",zh:"自從離不開智慧型手機之後，我們即使一個人，也不再是獨自一人了。無論是在電車上，或是睡前的幾分鐘，只要動動指尖，就能得知某人的近況，也能發布自己的近況。這是一種隨時與某人相連、連感到孤獨的空隙都沒有的狀態。乍看之下，這似乎是個從寂寞中解放出來的幸福時代。然而，在這種永不間斷的連結之中，我們是否在不知不覺間放掉了「獨處的時間」呢？"},{ja:"ここで言う「ひとりの時間」とは、単に誰とも会わない時間のことではない。他人の視線や評価から離れ、自分自身と向き合う時間のことである。散歩をしながら取り留めのないことを考える、あるいは窓の外をぼんやりと眺める。生産性という観点からすれば、それは何も生み出さない空白に見えるかもしれない。だが、思考が整理され、新たな発想が芽生えるのは、往々にしてそうした無為の時間においてなのである。",zh:"這裡所說的「獨處的時間」，並不單純是指不與任何人見面的時間，而是遠離他人的目光與評價、面對自己的時間。一邊散步一邊想些漫無邊際的事，或是茫然地望著窗外。從生產力的觀點來看，這或許看似什麼也不產出的空白。然而，思緒得以整理、新的想法得以萌芽，往往正是在這種無所事事的時間裡。"},{ja:"ところが、つながりが常態化した現代において、この空白は真っ先に埋められてしまう。少しでも手持ち無沙汰になると、私たちは反射的に画面を開き、他人の言葉や映像で頭を満たそうとする。その結果、自分が本当は何を感じ、何を望んでいるのかを問う機会が失われていく。他人の意見に絶えずさらされていれば、いつしかそれを自分の考えだと思い込んでしまうことさえあるだろう。",zh:"然而，在連結已成常態的現代，這段空白總是最先被填滿。只要稍微閒得發慌，我們就會反射性地打開螢幕，想用他人的話語和影像填滿腦袋。結果，詢問自己真正感受到什麼、渴望什麼的機會便逐漸喪失。若不斷暴露在他人的意見之下，甚至可能在不知不覺間，把那些意見誤以為是自己的想法吧。"},{ja:"もっとも、孤独を礼賛し、人とのつながりを断てと言いたいわけではない。人は他者との関わりの中でこそ生きる存在であり、孤立が心身を蝕むことはよく知られている。肝心なのは、つながることと一人になることを、自らの意思で選び取れるかどうかである。誰かとつながっていなければ不安になるというのであれば、それはもはや選択ではなく、依存と呼ぶべきものではなかろうか。",zh:"不過，我並不是想歌頌孤獨、要人斷絕與他人的連結。人正是在與他人的關係中生存的存在，而孤立會侵蝕身心，這是眾所周知的。關鍵在於，能否憑自己的意志，選擇要與人連結或是獨處。如果不與某人保持連結就會感到不安，那麼這已經不是選擇，而應該稱為依賴了吧？"},{ja:"一日にほんの十分でも構わない。通知を切り、誰に見せるためでもない時間を過ごしてみてはどうだろう。初めは落ち着かず、退屈に感じるかもしれない。しかし、その静けさの中でしか聞こえてこない自分の声というものが、確かにあるはずだ。ひとりの時間を取り戻すことは、他者とより良くつながるための準備でもあるのだ。",zh:"一天哪怕只有十分鐘也無妨。何不試著關掉通知，度過一段不為了給任何人看的時間呢？起初或許會靜不下心、感到無聊。但是，一定存在著只有在那份寧靜中才聽得見的、自己的聲音。找回獨處的時間，也是為了與他人建立更好的連結所做的準備。"}],vocab:[{word:"手放す",reading:"てばなす",meaning:"放手、放棄"},{word:"絶え間ない",reading:"たえまない",meaning:"不間斷的、接連不斷的"},{word:"取り留めのない",reading:"とりとめのない",meaning:"漫無邊際的、沒有重點的"},{word:"往々にして",reading:"おうおうにして",meaning:"往往、常常"},{word:"手持ち無沙汰",reading:"てもちぶさた",meaning:"閒得發慌、無所事事"},{word:"礼賛",reading:"らいさん",meaning:"讚美、歌頌"},{word:"蝕む",reading:"むしばむ",meaning:"侵蝕、損害"},{word:"依存",reading:"いぞん",meaning:"依賴"}],questions:[{question:"筆者の言う「ひとりの時間」とはどのような時間か。",questionZh:"作者所說的「獨處的時間」是什麼樣的時間？",options:["他人の視線や評価から離れ、自分自身と向き合う時間","誰とも会わずに、家の中で静かに過ごす時間","仕事の効率を上げるために、集中して作業する時間","スマートフォンで友人と気軽に連絡を取り合う時間"]},{question:"筆者の主張に最も近いものはどれか。",questionZh:"下列何者最接近作者的主張？",options:["つながるか一人になるかを、自分の意思で選べることが大切だ","孤立は心身に害があるので、常に誰かとつながっているべきだ","スマートフォンは依存を生むので、使うのをやめるべきだ","一人の時間は何も生み出さないので、できるだけ減らすべきだ"]}]},{id:"n1-r14",title:"訳せない言葉が教えること",titleZh:"無法翻譯的詞語教會我們的事",topic:"文化",paragraphs:[{ja:"外国語を学んでいると、どうしても一語では訳しきれない言葉に出くわすことがある。日本語で言えば、「木漏れ日」がその好例だろう。木々の葉の間から差し込む日の光を指すこの言葉は、多くの言語において、説明的な言い回しを用いなければ表現できない。こうした語はしばしば「翻訳不可能な言葉」として紹介され、その言語を話す人々の独特な感性の表れであるかのように語られる。",zh:"學習外語時，難免會遇到無法用一個詞完整翻譯的詞語。以日語來說，「木漏れ日」大概就是很好的例子。這個指從樹葉間灑落的陽光的詞，在許多語言中都必須使用說明性的措辭才能表達。這類詞語常被當作「無法翻譯的詞」來介紹，並被說成彷彿是說該語言的人們獨特感性的展現。"},{ja:"確かに、ある言語に特定の語が存在することは、その社会が何に関心を払ってきたかを映し出している。光と影の微妙な移ろいに目を留め、それに名前を与えてきたことは、自然の細やかな変化を愛でる文化と無関係ではあるまい。言葉とは、人々が世界をどのように切り分けてきたかの記録でもあるのだ。",zh:"的確，某種語言中存在特定的詞，反映出那個社會一直以來關注的是什麼。留意光影細微的變化並為其命名，這與欣賞自然細膩變化的文化恐怕不無關係。語言同時也是一份紀錄，記載著人們如何劃分這個世界。"},{ja:"しかし、ここから「その言葉を持たない人々には、その感覚が理解できない」と結論づけるのは早計である。木漏れ日という単語を知らない人であっても、森の中で揺れる光の美しさに心を動かされることは十分にありうる。単語がないことは、感覚がないことを意味しない。むしろ、名前のないものを言葉を尽くして伝えようとする営みこそが、翻訳の本質と言えるのではないか。",zh:"然而，若由此斷定「沒有那個詞的人們無法理解那種感覺」，就太過草率了。即使是不知道「木漏れ日」這個詞的人，也完全可能被森林中搖曳光影之美所打動。沒有那個詞，並不代表沒有那種感覺。倒不如說，竭盡言語去傳達沒有名字的事物，這樣的努力才正是翻譯的本質，不是嗎？"},{ja:"実際、優れた翻訳者は、一語対一語の置き換えに固執しない。原文の背後にある情景や情感を汲み取り、それを別の言語の文脈の中に移し替えようと試みる。その過程で、訳者は二つの言語の間を何度も往復し、どちらの言語にも存在しなかった新たな表現を生み出すことさえある。翻訳とは、失われるものを嘆く作業であると同時に、新たな意味を創造する作業でもあるのだ。",zh:"事實上，優秀的譯者不會執著於一個詞對一個詞的替換。他們會體察原文背後的情景與情感，並嘗試將其移植到另一種語言的脈絡之中。在這個過程中，譯者會在兩種語言之間來回往返許多次，有時甚至會創造出兩種語言中都不曾存在的新表達。翻譯既是哀嘆失去之物的工作，同時也是創造新意義的工作。"},{ja:"「訳せない言葉」という言い方には、言語や文化の間に越えがたい壁があるかのような響きがある。だが、それは壁というよりも、互いの世界を覗き込むための窓なのかもしれない。訳しきれないもどかしさを抱えつつも、なお伝えようとすること。そこにこそ、異なる文化を持つ者同士が理解し合うための糸口があるように思われる。",zh:"「無法翻譯的詞」這種說法，聽起來彷彿語言與文化之間存在著難以跨越的高牆。但與其說那是牆，或許更像是一扇讓我們窺看彼此世界的窗。即使懷著無法完整翻譯的焦急，仍然試圖傳達——正是在這裡，似乎存在著擁有不同文化的人們彼此理解的線索。"}],vocab:[{word:"出くわす",reading:"でくわす",meaning:"偶然遇到、碰上"},{word:"好例",reading:"こうれい",meaning:"好例子、恰當的例子"},{word:"移ろい",reading:"うつろい",meaning:"變遷、推移"},{word:"愛でる",reading:"めでる",meaning:"欣賞、喜愛"},{word:"固執",reading:"こしつ",meaning:"執著、固守"},{word:"汲み取る",reading:"くみとる",meaning:"體察、領會"},{word:"もどかしさ",reading:"もどかしさ",meaning:"焦急、心有餘而力不足的感覺"},{word:"糸口",reading:"いとぐち",meaning:"線索、頭緒"}],questions:[{question:"筆者は「訳せない言葉」についてどのように考えているか。",questionZh:"作者對「無法翻譯的詞」有什麼看法？",options:["その単語がなくても感覚はあり、言葉を尽くせば伝えうる","その言葉を持たない人々には、決して理解できない感覚だ","翻訳者の能力が足りないために生じる問題にすぎない","文化の間に越えがたい壁があることを証明するものだ"]},{question:"筆者によれば、優れた翻訳者はどのようなことをするか。",questionZh:"根據作者的說法，優秀的譯者會做什麼？",options:["原文の情景や情感を汲み取り、別の言語の文脈に移し替えようとする","原文の一語一語を、最も近い意味の単語に正確に置き換える","訳せない言葉は省略し、読みやすさを何よりも優先する","訳せない言葉には、必ず長い注釈をつけて意味を説明する"]}]},{id:"n1-r15",title:"「わかりやすさ」の代償",titleZh:"「淺顯易懂」的代價",topic:"社會",paragraphs:[{ja:"近年、あらゆる場面で「わかりやすさ」が求められるようになった。ニュースは要点を三つにまとめ、政治家は短い言葉で主張を言い切り、書店には「一冊でわかる」と銘打った本が並ぶ。忙しい現代人にとって、複雑な事柄を手短に理解できるのはありがたいことだ。情報があふれる時代に、わかりやすさが重宝されるのも無理からぬことである。",zh:"近年來，在各種場合都開始要求「淺顯易懂」。新聞把重點歸納成三點，政治人物用簡短的話語斷然表明主張，書店裡擺滿了標榜「一本就懂」的書。對忙碌的現代人來說，能在短時間內理解複雜的事情，是很令人感激的。在資訊氾濫的時代，淺顯易懂之所以受到重視，也是情有可原的。"},{ja:"しかし、世の中の問題の多くは、そもそも単純ではない。例えば、ある政策が一部の人々を救う一方で、別の人々に負担を強いるということは珍しくない。そうした利害の絡み合いを一言で言い表そうとすれば、どこかで切り捨てられる部分が生じる。わかりやすさとは、多くの場合、複雑さの一部を削ぎ落とすことによって得られるものなのである。",zh:"然而，世上的許多問題本來就不單純。例如，某項政策在拯救一部分人的同時，又迫使另一部分人承受負擔，這種情形並不少見。若想用一句話來表達這種錯綜複雜的利害關係，難免會有某些部分被捨棄。淺顯易懂在多數情況下，是靠削去複雜性的一部分才得到的。"},{ja:"厄介なのは、削ぎ落とされた部分が受け手には見えないという点である。明快な説明を聞いた人は、問題の全体を理解したと感じる。ところが実際には、説明する側が選んだ一つの切り口から眺めたにすぎない。しかも、わかりやすい主張ほど人の心に残りやすく、繰り返し語られるうちに、あたかもそれが唯一の真実であるかのように受け止められていく。",zh:"麻煩的是，被削去的部分是接收者看不見的。聽了明快說明的人，會覺得自己理解了問題的全貌。但實際上，那只不過是從說明者所選的一個切入點去看罷了。而且，越是淺顯易懂的主張越容易留在人心中，在被反覆傳述的過程裡，它就逐漸被當成彷彿是唯一的真相。"},{ja:"さらに言えば、わかりやすさへの過度な要求は、物事を考える力そのものを衰えさせかねない。すぐに結論を示してくれる説明に慣れてしまうと、答えの出ない問いを抱え続けることに耐えられなくなる。白か黒かをはっきりさせたいという欲求が、灰色のまま留保すべき問題にまで、性急な判断を下させるのである。",zh:"進一步說，對淺顯易懂的過度要求，可能會讓思考能力本身衰退。一旦習慣了馬上就給出結論的說明，就會變得無法忍受一直懷抱著沒有答案的問題。想要分清是黑是白的慾望，會讓人連那些本應以灰色狀態暫且保留的問題，也倉促地做出判斷。"},{ja:"もちろん、難解であればよいというわけではない。専門家が平易な言葉で語る努力は、今後ますます重要になるだろう。ただ、受け手の側にも、わかりやすい説明に接したときこそ「ここで省かれているものは何か」と問う姿勢が求められる。わかりにくさに踏みとどまる忍耐こそ、複雑な社会を生きる私たちにとって不可欠な知性ではなかろうか。",zh:"當然，並不是艱澀難懂就好。專家努力用平易的語言說明，今後將越來越重要吧。只是，接收者這一方也需要一種態度：正是在接觸到淺顯易懂的說明時，更要問一問「這裡省略了什麼」。能夠在難以理解之處堅持下去的耐心，不正是生活在複雜社會中的我們不可或缺的知性嗎？"}],vocab:[{word:"銘打つ",reading:"めいうつ",meaning:"標榜、以……為名號"},{word:"重宝",reading:"ちょうほう",meaning:"珍視、方便好用"},{word:"無理からぬ",reading:"むりからぬ",meaning:"情有可原、理所當然"},{word:"削ぎ落とす",reading:"そぎおとす",meaning:"削去、刪減"},{word:"厄介",reading:"やっかい",meaning:"麻煩、棘手"},{word:"留保",reading:"りゅうほ",meaning:"保留、暫緩"},{word:"性急",reading:"せいきゅう",meaning:"性急、倉促"},{word:"踏みとどまる",reading:"ふみとどまる",meaning:"堅持、站穩腳步"}],questions:[{question:"筆者が「厄介」だと述べているのはどのようなことか。",questionZh:"作者說「麻煩」的是什麼樣的事情？",options:["説明から削ぎ落とされた部分が、受け手には見えないこと","複雑な問題を説明できる専門家が、ほとんどいないこと","わかりやすい本が、書店にあまり並ばなくなったこと","受け手が明快な説明を、なかなか信用しようとしないこと"]},{question:"筆者の考えに最も近いものはどれか。",questionZh:"下列何者最接近作者的想法？",options:["わかりやすい説明に接したときこそ、何が省かれているかを問うべきだ","専門家は平易な言葉を避け、正確で難解な説明をするべきだ","複雑な問題こそ、白か黒かをはっきりさせて判断するべきだ","忙しい現代人には、わかりやすさよりも情報の量が必要だ"]}]},{id:"n1-r16",title:"「多数決」は万能か",titleZh:"「多數決」是萬能的嗎",topic:"社會",paragraphs:[{ja:"学級会で文化祭の出し物を決めるときも、国会で法案を可決するときも、私たちは当然のように多数決という方法を用いる。意見が割れたときには、数の多い方に従う。これほど公平で明快な決め方はないように思われる。民主主義とは多数決のことだと理解している人も少なくないだろう。だが、多数決は本当に、人々の意思を正しく反映する万能の仕組みなのだろうか。",zh:"無論是在班會上決定校慶要表演什麼，或是在國會通過法案，我們都理所當然地使用多數決這種方法。意見分歧時，就服從人數多的一方。似乎再也沒有比這更公平明快的決定方式了。認為民主主義就是多數決的人，應該也不在少數。但是，多數決真的是能正確反映人們意志的萬能機制嗎？"},{ja:"まず指摘しておきたいのは、多数決の結果が、選択肢の示し方によって大きく左右されるという点である。例えば、三つの案から一つを選ぶ場合、似通った二つの案に票が分散すれば、過半数の支持を得ていない第三の案が選ばれてしまうことがある。多くの人が「あれだけは避けたい」と考えていた案が、結果として採用されるという事態も起こりうるのである。",zh:"首先要指出的是，多數決的結果會因選項的呈現方式而大受影響。例如，從三個方案中選出一個時，如果票數分散在兩個相似的方案上，沒有得到過半數支持的第三個方案就可能被選上。許多人心想「唯獨那個要避免」的方案，結果卻被採用，這樣的事態也是可能發生的。"},{ja:"さらに重大なのは、少数派の声が切り捨てられやすいという問題である。多数決は、何人が賛成したかを数えはするが、それぞれの人がどれほど切実にその問題を抱えているかまでは測れない。大多数にとっては些細な不便にすぎないことが、少数の人々にとっては生活の根幹に関わることもある。数の論理だけで押し切れば、そうした人々の暮らしは容易に踏みにじられかねない。",zh:"更嚴重的是，少數派的聲音容易被捨棄的問題。多數決雖然會計算有幾個人贊成，卻無法衡量每個人對那個問題的感受有多麼切身。對大多數人來說只不過是微不足道的不便，對少數人而言卻可能關係到生活的根本。若只靠人數的邏輯強行通過，那些人的生活很可能輕易地遭到踐踏。"},{ja:"そもそも、民主主義の本質は、採決そのものよりも、そこに至るまでの過程にあると言ってよい。異なる立場の人々が意見を出し合い、互いの事情を知ることで、当初の案が修正されたり、誰もが受け入れられる妥協点が見いだされたりする。多数決とは、議論を尽くしてもなお合意に至らない場合の、最後の手段であるべきなのだ。",zh:"說到底，民主主義的本質，與其說在於表決本身，不如說在於表決之前的過程。立場不同的人們提出意見、了解彼此的處境，藉此修正最初的方案，或找出每個人都能接受的妥協點。多數決應該是在充分討論之後仍無法達成共識時的最後手段。"},{ja:"時間をかけた議論は、確かに手間がかかる。だが、その手間を惜しみ、安易に数で決着をつけることが常態となれば、少数派は声を上げることさえ諦めてしまうだろう。多数決の明快さに安住することなく、決める前にどれだけ耳を傾けたかを問い続けること。それこそが、民主主義を形骸化させないための条件ではなかろうか。",zh:"花時間討論的確很費工夫。但是，如果吝於付出這份工夫，動輒以人數輕易做出決定成了常態，少數派恐怕連發聲都會放棄吧。不安於多數決的明快，持續追問自己在做決定之前究竟傾聽了多少——這難道不正是讓民主主義不至於流於形式的條件嗎？"}],vocab:[{word:"左右",reading:"さゆう",meaning:"左右、影響"},{word:"似通う",reading:"にかよう",meaning:"相似、類似"},{word:"切実",reading:"せつじつ",meaning:"切身、迫切"},{word:"根幹",reading:"こんかん",meaning:"根本、核心"},{word:"踏みにじる",reading:"ふみにじる",meaning:"踐踏、蹂躪"},{word:"妥協",reading:"だきょう",meaning:"妥協、讓步"},{word:"安住",reading:"あんじゅう",meaning:"安於（現狀）、滿足於"},{word:"形骸化",reading:"けいがいか",meaning:"流於形式、空洞化"}],questions:[{question:"第二段落で筆者が指摘している多数決の問題点はどれか。",questionZh:"作者在第二段指出的多數決問題是哪一個？",options:["選択肢の示し方によって、多くの人が避けたい案が選ばれることがある","票を数えるのに時間がかかり、決定が大幅に遅れてしまう","賛成した人の数が、正確に記録されないことがよくある","案が三つ以上あると、投票そのものが成り立たなくなる"]},{question:"筆者は多数決をどのように位置づけているか。",questionZh:"作者如何定位多數決？",options:["議論を尽くしても合意に至らないときの最後の手段","民主主義そのものであり、何よりも重んじるべき方法","少数派の意見を守るために考え出された仕組み","時間のかかる議論を省くための便利な方法"]}]},{id:"n1-r17",title:"鹿が森を食べ尽くすとき",titleZh:"當鹿把森林吃光時",topic:"自然",paragraphs:[{ja:"奈良公園の鹿に見られるように、日本人にとって鹿は古くから親しみのある動物である。しかし今、各地の山では、その鹿が深刻な問題を引き起こしている。増えすぎた鹿が森の下草や若木を食べ尽くし、かつて緑に覆われていた林床が、むき出しの地面に変わりつつあるのだ。一見すると豊かな森でも、足元に目を向ければ、背の低い植物がほとんど姿を消していることが少なくない。",zh:"從奈良公園的鹿就可以看出，對日本人而言，鹿自古以來就是令人感到親近的動物。然而現在，在各地的山裡，這些鹿正引發嚴重的問題。數量過多的鹿把森林裡的林下草本和幼樹吃個精光，過去被綠意覆蓋的林床，正逐漸變成裸露的地面。即使是乍看之下豐茂的森林，往腳下一看，低矮的植物幾乎都已消失的情形也不少見。"},{ja:"鹿がこれほど増えた背景には、いくつかの要因が重なっている。明治時代にオオカミが絶滅し、鹿を捕食する天敵がいなくなったこと。狩猟をする人が高齢化し、その数が減り続けていること。さらに、温暖化によって積雪が減り、かつては冬を越せなかった個体が生き延びるようになったことも指摘されている。いずれも、人間の営みと無縁ではない。",zh:"鹿之所以增加到這種程度，背後有好幾個因素重疊。明治時代狼滅絕，捕食鹿的天敵就此消失；從事狩獵的人逐漸高齡化，人數持續減少；此外也有人指出，由於暖化使積雪減少，過去無法過冬的個體也能存活下來。無論哪一項，都與人類的活動脫不了關係。"},{ja:"下草が失われると、影響は植物だけにとどまらない。下草を住みかや餌場としていた昆虫や、地面近くに巣を作る鳥が減少する。さらに、雨が降るたびに土が流され、山の斜面が崩れやすくなる。一頭一頭の鹿が草を食べるという、ごくありふれた行為が、積み重なることで森全体の姿を変えてしまうのである。",zh:"林下草本一旦消失，影響並不僅止於植物。把林下草本當作棲身之所和覓食場所的昆蟲，以及在靠近地面處築巢的鳥類都會減少。再者，每逢下雨土壤就會被沖走，山坡也變得容易崩塌。一頭一頭的鹿吃草這種再平常不過的行為，累積起來，竟會改變整座森林的樣貌。"},{ja:"こうした事態を受けて、各地で鹿の捕獲や、柵で囲って植物を守る取り組みが進められている。捕獲した鹿の肉を「ジビエ」として活用する動きも広がってきた。ただし、動物を駆除することへの抵抗感から、こうした対策に異を唱える声もある。鹿を害獣とみなすか、守るべき野生動物とみなすかは、立場によって大きく異なるのが実情だ。",zh:"面對這樣的情況，各地正推動捕捉鹿隻、以及用柵欄圍起來保護植物等措施。將捕獲的鹿肉當作「野味」加以利用的做法也逐漸普及。不過，也有人出於對驅除動物的抗拒感，而對這些對策提出異議。要把鹿視為害獸，還是應該保護的野生動物，因立場不同而有很大差異，這就是實際情況。"},{ja:"忘れてはならないのは、鹿そのものに罪があるわけではないということだ。天敵を絶やし、山との関わりを薄れさせてきたのは、ほかならぬ人間である。崩れた均衡を元に戻す責任もまた、人間が負わなければならない。鹿の問題は、人と自然との付き合い方そのものを、私たちに問い直しているのである。",zh:"不能忘記的是，鹿本身並沒有罪。讓天敵絕跡、使人與山林的關係日益淡薄的，不是別人，正是人類。讓失去的平衡恢復原狀的責任，也必須由人類來承擔。鹿的問題，正是在重新質問我們：人與自然究竟該如何相處。"}],vocab:[{word:"下草",reading:"したくさ",meaning:"林下草本、樹下雜草"},{word:"林床",reading:"りんしょう",meaning:"林床、森林地面"},{word:"捕食",reading:"ほしょく",meaning:"捕食"},{word:"天敵",reading:"てんてき",meaning:"天敵"},{word:"個体",reading:"こたい",meaning:"個體"},{word:"捕獲",reading:"ほかく",meaning:"捕獲、捕捉"},{word:"異を唱える",reading:"いをとなえる",meaning:"提出異議、表示反對"},{word:"均衡",reading:"きんこう",meaning:"平衡、均衡"}],questions:[{question:"鹿が増えた背景として、本文で述べられているものはどれか。",questionZh:"下列何者是本文提到的鹿增加的背景？",options:["温暖化で積雪が減り、冬を越せる個体が増えたこと","森の下草が増えて、鹿の餌が豊富になったこと","鹿の肉を食べる習慣が、各地で失われたこと","法律によって、鹿の捕獲が全面的に禁止されたこと"]},{question:"筆者が最も言いたいことは何か。",questionZh:"作者最想表達的是什麼？",options:["鹿の問題は人間が招いたもので、人間が責任を負うべきだ","鹿は森を荒らす害獣なので、一刻も早く駆除するべきだ","鹿は守るべき野生動物なので、捕獲には反対するべきだ","森の変化は自然の現象なので、人間は手を出すべきではない"]}]},{id:"n1-r18",title:"「一キログラム」を定義し直す",titleZh:"重新定義「一公斤」",topic:"科學",paragraphs:[{ja:"私たちが日常的に使う「一キログラム」という重さは、長い間、ある一つの物体によって決められていた。フランスのパリ郊外に厳重に保管されている、白金とイリジウムの合金でできた小さな円柱、「国際キログラム原器」である。十九世紀の終わりに作られたこの原器の質量こそが、定義上、世界で唯一の正確な一キログラムだったのだ。",zh:"我們日常使用的「一公斤」這個重量，長久以來是由某一個物體所決定的。那就是嚴密保管在法國巴黎郊外、由鉑與銥的合金製成的小圓柱——「國際公斤原器」。這個在十九世紀末製成的原器的質量，在定義上正是世界上唯一準確的一公斤。"},{ja:"しかし、物体に基準を委ねる方法には、根本的な弱点があった。原器と各国に配られた複製とを比較したところ、百年余りの間に、両者の質量にわずかな差が生じていることが判明したのである。その差は約五十マイクログラム、指紋一つ分ほどの重さにすぎない。だが、どちらが変化したのかを確かめる術はない。原器そのものが定義である以上、たとえ原器が軽くなったとしても、それを「軽くなった」と言うことさえできないからだ。",zh:"然而，把基準託付給物體的方法，有著根本性的弱點。將原器與分送到各國的複製品比較後，發現在一百多年間，兩者的質量出現了些微差異。差距約為五十微克，只不過相當於一枚指紋的重量。但是，沒有辦法確認究竟是哪一方發生了變化。因為既然原器本身就是定義，即使原器變輕了，也連說它「變輕了」都做不到。"},{ja:"そこで科学者たちが目指したのは、決して変化しない自然界の定数に基づいて単位を定義することであった。選ばれたのは、量子力学の基本的な定数の一つである「プランク定数」である。この値を極めて高い精度で測定したうえで固定し、そこから逆に一キログラムを導き出そうというのだ。測定には世界各国の研究機関が挑み、日本の研究チームも、純度の高いシリコンの球体を用いた方法で大きく貢献した。",zh:"於是科學家們所追求的，是根據絕不會改變的自然界常數來定義單位。被選中的是量子力學的基本常數之一「普朗克常數」。他們以極高的精度測量這個值並將其固定下來，再反過來由此推導出一公斤。世界各國的研究機構都投入了這項測量的挑戰，日本的研究團隊也以使用高純度矽球體的方法做出了重大貢獻。"},{ja:"こうして二〇一九年、一キログラムの定義は百三十年ぶりに改められた。新しい定義のもとでは、特定の物体に頼る必要はなく、原理的には、十分な技術さえあれば世界のどこでも同じ一キログラムを再現できる。もちろん、私たちが店で買う米や肉の重さが変わるわけではない。変わったのは、その重さを支える土台の方なのである。",zh:"就這樣，在二〇一九年，一公斤的定義在睽違一百三十年後被修改了。在新的定義下，不需要依賴特定物體，原理上只要具備足夠的技術，在世界任何地方都能重現相同的一公斤。當然，我們在店裡買的米或肉的重量並不會因此改變。改變的，是支撐這個重量的基礎。"},{ja:"この出来事は、科学における「正確さ」とは何かを考えさせる。私たちは普段、基準というものを疑うことなく使っている。しかし、その基準もまた人間が定めたものであり、より揺るぎないものを求めて問い直され続けてきた。当たり前のように使っている単位の背後には、そうした地道な探究の積み重ねがあるのだ。",zh:"這件事讓我們思考，科學中的「準確」究竟是什麼。我們平常毫不懷疑地使用著所謂的基準。然而，那些基準同樣是人類所訂定的，並且為了追求更穩固不移的東西而不斷被重新檢視。在我們理所當然使用的單位背後，有著這樣踏實探究的累積。"}],vocab:[{word:"厳重",reading:"げんじゅう",meaning:"嚴密、嚴格"},{word:"合金",reading:"ごうきん",meaning:"合金"},{word:"委ねる",reading:"ゆだねる",meaning:"委託、交付"},{word:"判明",reading:"はんめい",meaning:"查明、弄清楚"},{word:"術",reading:"すべ",meaning:"方法、手段"},{word:"定数",reading:"ていすう",meaning:"常數"},{word:"導き出す",reading:"みちびきだす",meaning:"推導出、導出"},{word:"地道",reading:"じみち",meaning:"踏實、腳踏實地"}],questions:[{question:"原器が軽くなっても「軽くなった」と言うことさえできないのはなぜか。",questionZh:"為什麼即使原器變輕了，也連說它「變輕了」都做不到？",options:["原器の質量そのものが、一キログラムの定義だったから","原器が厳重に保管され、誰も触れることができなかったから","複製の方が、原器よりも正確に作られていたから","質量の差があまりに小さく、まったく測定できなかったから"]},{question:"新しい定義について、本文の内容と合っているものはどれか。",questionZh:"關於新的定義，下列何者與本文內容相符？",options:["技術があれば、原理的にはどこでも同じ一キログラムを再現できる","店で買う米や肉の重さが、以前よりわずかに重くなった","日本で作られたシリコンの球体が、新しい原器に選ばれた","プランク定数の代わりに、原器の質量が固定されることになった"]}]},{id:"n1-r19",title:"影が告げた時刻",titleZh:"影子透露的時刻",topic:"推理",paragraphs:[{ja:"古都の外れにある旧家、久我家の蔵から家宝の茶碗が消えたのは、秋晴れの日曜日のことであった。当主の久我が午前九時に蔵を開けて茶碗の無事を確かめ、十一時に再び訪れたときには、棚に桐の箱だけが残されていたという。その二時間、蔵の鍵は母屋の茶の間に掛けたままになっていた。相談を受けた私立探偵の朝霧は、その日のうちに久我家を訪れた。",zh:"位於古都郊外的古老世家久我家，傳家寶茶碗從土藏中消失，是在一個秋高氣爽的星期日。據說當家久我在上午九點打開土藏，確認茶碗安然無恙，十一點再去時，架上只剩下桐木盒。那兩個小時裡，土藏的鑰匙一直掛在主屋的起居室。接受委託的私家偵探朝霧，當天就造訪了久我家。"},{ja:"その日、久我家に出入りしていたのは三人である。一人目は庭師の小松で、朝から弟子二人と庭木の手入れをしていた。弟子たちは、師匠が一度も庭を離れなかったと口をそろえた。二人目は久我の姪の葉子で、九時半から正午まで町の病院で診察を待っていたことが、受付の記録から確かめられた。三人目は、久我と親しい画家の水野である。",zh:"那天進出久我家的有三個人。第一位是園丁小松，他從早上就和兩名徒弟一起修整庭院的樹木。徒弟們異口同聲地說，師傅一次也沒有離開過庭院。第二位是久我的姪女葉子，她從九點半到中午都在鎮上的醫院候診，這一點已從掛號櫃台的紀錄獲得確認。第三位是與久我交情深厚的畫家水野。"},{ja:"水野は一枚の水彩画を差し出しながら言った。「あの日は朝八時から正午まで、川の南岸に座って、対岸に建つ五重塔を描いていました。塔を正面に見て、北を向いて筆を執ったのです。これがその場で仕上げた絵ですよ」。画面には、澄んだ秋空を背に塔がそびえ、その足元から長い影が右手の方へと伸びていた。朝霧は絵をしばらく見つめていたが、やがて静かに顔を上げた。",zh:"水野一邊遞出一幅水彩畫一邊說：「那天我從早上八點到中午，都坐在河的南岸，畫對岸的五重塔。我是正對著塔、面向北方作畫的。這就是我當場完成的畫。」畫面上，五重塔以澄澈的秋日天空為背景高高聳立，一道長長的影子從塔腳下朝右手邊延伸。朝霧凝視那幅畫好一會兒，終於靜靜地抬起頭來。"},{ja:"「水野さん、北を向いて座れば、右手は東、左手は西になります」と朝霧は言った。「午前中、太陽は東の空にある。ですから、塔の影は西、つまり絵の左側に伸びるはずです。ところが、この絵の影は右に伸びている。影が東に向かうのは、太陽が西に傾いた午後のことです。この絵は、午前中に描かれたものではありません」。水野の顔から、みるみる血の気が引いていった。",zh:"「水野先生，如果面向北方坐著，右手邊是東，左手邊是西。」朝霧說，「上午太陽在東邊的天空，所以塔的影子應該朝西，也就是往畫的左側延伸。可是這幅畫裡的影子卻往右延伸。影子朝東，是太陽西斜的下午才會有的事。這幅畫並不是在上午畫的。」水野的臉眼看著失去了血色。"},{ja:"水野は観念したように、深いため息をついた。彼は事件の前日にも同じ場所を訪れており、その日の午後に描いた絵を、日曜日の朝に描いたものと偽っていたのである。久我が庭で小松と話し込んでいる隙に、茶の間の鍵を持ち出し、蔵から茶碗を運び出したのだという。画家としての確かな観察眼が、皮肉にも、自らの嘘を暴く証拠を克明に描き残してしまったのだ。",zh:"水野像是認命般地深深嘆了一口氣。原來他在案發前一天也去過同一個地方，並把那天下午畫的畫，謊稱是星期日早上畫的。據說他是趁久我在庭院和小松談得正起勁時，拿走起居室的鑰匙，從土藏裡把茶碗帶走的。身為畫家的敏銳觀察力，諷刺的是，竟把揭穿自己謊言的證據鉅細靡遺地畫了下來。"}],vocab:[{word:"家宝",reading:"かほう",meaning:"傳家寶"},{word:"蔵",reading:"くら",meaning:"土藏、倉庫"},{word:"口をそろえる",reading:"くちをそろえる",meaning:"異口同聲"},{word:"筆を執る",reading:"ふでをとる",meaning:"執筆、提筆（作畫或寫作）"},{word:"そびえる",reading:"そびえる",meaning:"聳立"},{word:"観念",reading:"かんねん",meaning:"（觀念する）死心、認命"},{word:"暴く",reading:"あばく",meaning:"揭穿、揭露"},{word:"克明",reading:"こくめい",meaning:"細緻、鉅細靡遺"}],questions:[{question:"庭師の小松が犯人ではないと考えられるのはなぜか。",questionZh:"為什麼可以認為園丁小松不是犯人？",options:["弟子たちが、小松は一度も庭を離れなかったと証言したから","病院の受付の記録によって、居場所が確かめられたから","川の南岸に座って、五重塔の絵を描いていたから","蔵の鍵がどこに掛けてあるかを知らなかったから"]},{question:"朝霧が水野の嘘を見抜く手がかりとなったのは何か。",questionZh:"讓朝霧識破水野謊言的線索是什麼？",options:["北を向いて描いたはずの絵で、塔の影が右手に伸びていたこと","絵の中の空が曇っていて、秋晴れの日と合わなかったこと","五重塔が、実際には川の南岸に建っていたこと","絵が水彩ではなく、油絵の具で描かれていたこと"]},{question:"水野が差し出した絵は、実際にはいつ描かれたものか。",questionZh:"水野遞出的那幅畫，實際上是什麼時候畫的？",options:["事件の前日の午後","事件当日の午前","事件当日の午後","事件の翌日の朝"]}]},{id:"n1-r20",title:"語るに落ちる",titleZh:"不打自招",topic:"推理",paragraphs:[{ja:"老舗の和菓子屋「松風堂」の主人、宮内から相談を受けたのは、元刑事の榊であった。宮内の自宅の書斎から、祖父の代から受け継がれてきた品が消えたのだという。最後に確かめたのは前日の夜で、翌朝には書斎の机の引き出しが空になっていた。何がなくなったのかを、宮内はまだ誰にも話していなかった。榊はまず、一つだけ念を押した。「何がなくなったのかは、家族も含めて誰にも言わないでください。知っているのは、あなたと私だけにしておくのです」",zh:"接受老字號和菓子店「松風堂」老闆宮內委託的，是前刑警榊。據說宮內家的書房裡，一件從祖父那一代傳承下來的物品不見了。最後一次確認是在前一天晚上，隔天早上書房書桌的抽屜就空了。不見的是什麼，宮內還沒有告訴任何人。榊首先只叮囑了一件事：「不見的是什麼東西，包括家人在內，請不要告訴任何人。就讓知道的只有您和我兩個人。」"},{ja:"その夜、宮内の家に泊まっていたのは、宮内本人のほかに二人である。泊まりがけで遊びに来ていた甥の和也と、住み込みで働く職人の島田だ。さらに翌朝早くには、家政婦の加藤が掃除に来ていた。榊は三人を一人ずつ書斎に呼び、「この部屋から大切なものが一つなくなりました。何か心当たりはありませんか」とだけ尋ねた。",zh:"那天晚上住在宮內家的，除了宮內本人之外還有兩個人：一位是來家裡玩、留宿過夜的外甥和也，另一位是住在宮內家工作的師傅島田。此外，隔天一大早，家政婦加藤也來打掃了。榊把三人一個一個叫到書房，只問了一句：「這個房間裡有一樣重要的東西不見了。您有沒有什麼頭緒？」"},{ja:"職人の島田は、「書斎には入っていません。朝は四時から店で仕込みをしていましたから」と答えた。家政婦の加藤は少し不安げに、「書斎の床は掃除しましたが、机には手を触れておりません」と言った。甥の和也は、いかにも心外だという顔をした。「僕を疑っているんですか。夜はずっと客間で寝ていましたよ。だいたい、あんな古い時計、今どき誰が欲しがるんです。動くかどうかも怪しいものでしょう」",zh:"師傅島田回答：「我沒有進過書房。早上從四點起我就在店裡備料。」家政婦加藤有些不安地說：「書房的地板我打掃過了，但書桌我沒有碰。」外甥和也則露出一副相當不服氣的表情：「你是在懷疑我嗎？我晚上一直在客房睡覺啊。再說，那種舊錶，現在誰會想要？連能不能走都很難說吧。」"},{ja:"榊は手帳を閉じて、宮内の方を向いた。「宮内さん、なくなったのが何であるか、どなたかにお話しになりましたか」。宮内は首を横に振った。「いいえ。言われたとおり、誰にも話していません」。それを聞くと、榊は和也に向き直った。「私は『大切なもの』としか言っていません。それなのに、あなたはなぜ、なくなったのが時計だとご存じなのですか」",zh:"榊闔上筆記本，轉向宮內。「宮內先生，您有沒有告訴任何人不見的是什麼？」宮內搖了搖頭：「沒有。照您說的，我誰都沒說。」聽到這句話，榊重新轉向和也：「我只說了『重要的東西』。既然如此，您為什麼會知道不見的是錶呢？」"},{ja:"和也は言葉に詰まり、やがてうつむいた。引き出しにしまわれていた銀の懐中時計は、夜中に彼が持ち出し、鞄の底に隠していたのである。島田も加藤も、なくなった物が何であるかには一言も触れなかった。盗まれた物の正体を知りえたのは、持ち主と探偵、そして盗んだ本人だけである。隠し通そうとするあまり、和也はかえって、自分しか知りえない事実を口にしてしまったのだ。",zh:"和也一時語塞，終於低下了頭。原本收在抽屜裡的銀懷錶，是他半夜拿出來，藏在包包底部的。島田和加藤對於不見的東西是什麼，都隻字未提。能夠知道被偷的究竟是什麼的，只有失主、偵探，以及偷走它的本人而已。和也一心想要隱瞞到底，結果反而說出了只有自己才可能知道的事實。"}],vocab:[{word:"老舗",reading:"しにせ",meaning:"老字號、老店"},{word:"念を押す",reading:"ねんをおす",meaning:"叮囑、再三確認"},{word:"泊まりがけ",reading:"とまりがけ",meaning:"留宿、過夜"},{word:"住み込み",reading:"すみこみ",meaning:"住在雇主家工作"},{word:"仕込み",reading:"しこみ",meaning:"（料理、商品的）備料、準備"},{word:"心外",reading:"しんがい",meaning:"出乎意料而感到不滿、委屈"},{word:"言葉に詰まる",reading:"ことばにつまる",meaning:"語塞、說不出話"},{word:"うつむく",reading:"うつむく",meaning:"低頭"}],questions:[{question:"榊が宮内に「誰にも言わないでください」と頼んだのは、何のためだと考えられるか。",questionZh:"榊拜託宮內「請不要告訴任何人」，可以認為是為了什麼？",options:["なくなった物を知っている人物を、犯人として絞り込むため","老舗の評判が悪くなるのを、できるだけ防ぐため","家族に余計な心配をかけないようにするため","警察に知られないうちに、事件を解決するため"]},{question:"和也が犯人だとわかった決め手は何か。",questionZh:"確定和也是犯人的關鍵是什麼？",options:["榊が告げていないのに、なくなった物が時計だと知っていたこと","夜中に客間を抜け出すところを、家政婦の加藤に見られていたこと","書斎の床に、和也の足跡がはっきりと残っていたこと","時計に高い値打ちがあることを、和也だけが知っていたこと"]},{question:"職人の島田は、事件の朝に何をしていたと言っているか。",questionZh:"師傅島田說自己在案發當天早上做了什麼？",options:["四時から店で仕込みをしていた","書斎の床を掃除していた","客間でずっと寝ていた","宮内と一緒に店番をしていた"]}]}]},1934,[]);
